// ---- search(BM25)/ ratelimit(redis atomic)/ realtime(send queue) ----
section("search bm25 / redis / ws queue");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  const tok = `${TMP}/bm-tok-${stamp}.ts`;
  await fs.writeFile(tok, await fs.readFile(new URL("../packages/search/src/tokenize.ts", import.meta.url), "utf8"));
  let bm = (await fs.readFile(new URL("../packages/search/src/bm25.ts", import.meta.url), "utf8")).replace('from "./tokenize"', `from "${toSpec(tok)}"`);
  const bmf = `${TMP}/bm-${stamp}.ts`; await fs.writeFile(bmf, bm);
  const { createBm25Index } = await impFile(bmf);
  const idx = createBm25Index();
  idx.addAll([{ id: "1", t: "請求書の書き方と作成手順" }, { id: "2", t: "見積書テンプレート" }, { id: "3", t: "経費精算のやり方" }]);
  ok("BM25 日本語検索(該当のみ)", (() => { const r = idx.search("請求書", 10); return r.length === 1 && r[0].id === "1"; })());
  ok("BM25 別語で別文書", idx.search("経費", 10)[0].id === "3");
  await fs.rm(tok); await fs.rm(bmf);

  // ratelimit redis(フェイク)
  let redisSrc = (await fs.readFile(new URL("../packages/ratelimit/src/redis.ts", import.meta.url), "utf8"))
    .replace('import Redis from "ioredis";\n', "")
    .replace('typeof urlOrClient === "string" ? (new Redis(urlOrClient) as unknown as RedisLike) : urlOrClient', "urlOrClient as RedisLike");
  const ttypes = `${TMP}/rl-types-${stamp}.ts`; await fs.writeFile(ttypes, "export interface RateLimitStore { increment(key: string, windowSeconds: number): Promise<number> }");
  redisSrc = redisSrc.replace('from "./types"', `from "${toSpec(ttypes)}"`);
  const rf = `${TMP}/rl-${stamp}.ts`; await fs.writeFile(rf, redisSrc);
  const { createRedisStore } = await impFile(rf);
  const store = new Map(); let clock = 0;
  const fake = { eval: async (_s, _n, key, ttl) => {
    const e = store.get(key);
    if (e && e.exp !== null && e.exp <= clock) store.delete(key);
    const cur = store.get(key) ?? { count: 0, exp: null };
    cur.count += 1;
    if (cur.count === 1) cur.exp = clock + Number(ttl) * 1000;
    store.set(key, cur);
    return cur.count;
    }
  };
  const rl = createRedisStore(fake);
  ok("redis INCR+EXPIRE アトミック", (await rl.increment("k", 60)) === 1 && (await rl.increment("k", 60)) === 2 && store.get("k").exp === 60000);
  await fs.rm(ttypes); await fs.rm(rf);

  // realtime send queue
  const rt = await (async () => {
    const fsx = await import("node:fs/promises");
    const src = (await fsx.readFile(new URL("../packages/realtime/src/index.ts", import.meta.url), "utf8")).replace(/export \{[^}]*\} from "\.\/broadcast";\n?/g, "");
    const f = `${TMP}/rt-idx-b-${smokeStamp()}.ts`; await fsx.writeFile(f, src);
    const m = await impFile(f); await fsx.rm(f); return m;
  })();
  const insts = [];
  class FakeWS { constructor() { this.sent = []; this.onopen = null; this.onclose = null; insts.push(this); } send(d) { this.sent.push(d); } close() { this.onclose && this.onclose(); } }
  const rws = rt.createReconnectingWebSocket("wss://x", { WebSocketImpl: FakeWS, scheduleReconnect: () => {} });
  rws.send({ n: 1 }); rws.send({ n: 2 });
  const buffered = rws.pending() === 2;
  insts[0].onopen();
  ok("WS 切断中バッファ→接続時 flush", buffered && insts[0].sent.length === 2 && rws.pending() === 0);
}

// ---- cache redis / db retry / jobs memory retry ----
section("cache redis / db retry / jobs retry");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  // cache redis(注入)
  let cr = (await fs.readFile(new URL("../packages/cache/src/adapters/redis.ts", import.meta.url), "utf8")).split("\n").filter((ln) => !ln.includes('import Redis from')).join("\n").replace(/const client: RedisLike = isConfig[\s\S]*?: configOrClient;/, "const client = configOrClient as RedisLike;");
  const ci = `${TMP}/cr-idx-${stamp}.ts`; await fs.writeFile(ci, "export interface CacheAdapter { get(key: string): Promise<string | null>; set(key: string, value: string, ttlSeconds?: number): Promise<void>; delete(key: string): Promise<void>; }");
  cr = cr.replace('from "../index"', `from "${toSpec(ci)}"`);
  const crf = `${TMP}/cr-${stamp}.ts`; await fs.writeFile(crf, cr);
  const { createRedisCache } = await impFile(crf);
  const store = new Map(); const ttls = new Map();
  const fake = { get: async (k) => store.has(k) ? store.get(k) : null, set: async (k, v, mode, ttl) => { store.set(k, v); if (mode === "EX") ttls.set(k, ttl); return "OK"; }, del: async (k) => { store.delete(k); return 1; } };
  const c = createRedisCache(fake);
  await c.set("k", "v", 300);
  ok("cache redis(注入・TTL)", (await c.get("k")) === "v" && ttls.get("k") === 300);
  await fs.rm(ci); await fs.rm(crf);

  // jobs memory retry
  const ji = `${TMP}/jb-idx-${stamp}.ts`; await fs.writeFile(ji, "export interface TypedQueue<T> { add(name: string, data: T, o?: unknown): Promise<unknown>; close(): Promise<void>; }");
  const jc = `${TMP}/jb-core-${stamp}.ts`; await fs.writeFile(jc, "export {};");
  let jm = (await fs.readFile(new URL("../packages/jobs/src/memory.ts", import.meta.url), "utf8")).replace('from "@platform/core"', `from "${toSpec(jc)}"`).replace('from "./index"', `from "${toSpec(ji)}"`);
  const jmf = `${TMP}/jb-${stamp}.ts`; await fs.writeFile(jmf, jm);
  const { createMemoryQueue } = await impFile(jmf);
  let tries = 0;
  const q = createMemoryQueue({ attempts: 3 });
  q.process(async () => { tries++; if (tries < 3) throw new Error("t"); });
  await q.add("j", {}); await q.drain();
  ok("jobs memory retry(3回目成功)", tries === 3 && q.failed().length === 0);
  const q2 = createMemoryQueue({ attempts: 2 });
  q2.process(async () => { throw new Error("perm"); });
  await q2.add("bad", {}); await q2.drain();
  ok("jobs memory デッドレター", q2.failed().length === 1);
  await fs.rm(ji); await fs.rm(jc); await fs.rm(jmf);
}

// ---- cache Redis / db tx-retry / jobs BullMQ ----
section("cache redis / db tx-retry / jobs");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  const w = async (name, src) => { const f = `${TMP}/dd-${name}-${stamp}.ts`; await fs.writeFile(f, src); return f; };
  // cache redis(注入)
  const cidx = await w("cidx", "export interface CacheAdapter { get(key: string): Promise<string | null>; set(key: string, value: string, ttlSeconds?: number): Promise<void>; delete(key: string): Promise<void>; }");
  let credis = (await fs.readFile(new URL("../packages/cache/src/adapters/redis.ts", import.meta.url), "utf8"))
    .replace('import Redis from "ioredis";\n', "")
    .replace('from "../index"', `from "${toSpec(cidx)}"`);
  const credisf = await w("credis", credis);
  const { createRedisCache } = await impFile(credisf);
  const store = new Map(); let exArgs = null;
  const fake = { get: async (k) => store.get(k) ?? null, set: async (k, v, ...a) => { store.set(k, v); exArgs = a; return "OK"; }, del: async (k) => { store.delete(k); return 1; } };
  const ca = createRedisCache(fake);
  await ca.set("k", "v", 300);
  ok("cache redis: TTL付き set は EX 秒", exArgs[0] === "EX" && exArgs[1] === 300 && (await ca.get("k")) === "v");
  await fs.rm(cidx); await fs.rm(credisf);

  // db transactionWithRetry(注入 Prisma)
  const core = await w("core", `export const ErrorCode={CONFLICT:"CONFLICT",DATABASE:"DATABASE",INTERNAL:"INTERNAL"};export class AppError extends Error{constructor(c,m,o){super(m);this.code=c;this.cause=o?.cause;}static from(e,c){return new AppError(c,String(e));}}export async function tryCatch(fn){try{return{ok:true,value:await fn()};}catch(e){return{ok:false,error:e instanceof AppError?e:new AppError("INTERNAL",String(e),{cause:e})};}}`);
  const prisma = await w("prisma", "export class PrismaClient {}");
  const errs = await w("errs", `import { AppError, ErrorCode } from "${toSpec(core)}";export function mapPrismaError(e){return new AppError(ErrorCode.DATABASE,"db",{cause:e});}export function isRetryablePrismaError(e){return /40001|40P01|deadlock|serialization|P2034/i.test(e?.message??"");}`);
  let tx = (await fs.readFile(new URL("../packages/db/src/transaction.ts", import.meta.url), "utf8"))
    .replace('from "@prisma/client"', `from "${toSpec(prisma)}"`)
    .replace('from "@platform/core"', `from "${toSpec(core)}"`)
    .replace('from "./errors"', `from "${toSpec(errs)}"`);
  const txf = await w("tx", tx);
  let res = (await fs.readFile(new URL("../packages/db/src/resilience.ts", import.meta.url), "utf8"))
    .replace('from "@prisma/client"', `from "${toSpec(prisma)}"`)
    .replace('from "@platform/core"', `from "${toSpec(core)}"`)
    .replace('from "./errors"', `from "${toSpec(errs)}"`)
    .replace('from "./transaction"', `from "${toSpec(txf)}"`);
  const resf = await w("res", res);
  const { transactionWithRetry } = await impFile(resf);
  const { abortTransaction } = await impFile(txf);
  let calls = 0;
  const db = { $transaction: async (fn, o) => { calls++; if (calls < 3) throw new Error("serialize 40001"); return fn({}); } };
  const r = await transactionWithRetry(db, async () => "ok", { retries: 3, baseDelayMs: 1, isolationLevel: "Serializable" });
  ok("db tx-retry: シリアライズ失敗を再試行", r.ok && calls === 3);
  let ac = 0;
  const db2 = { $transaction: async (fn) => { ac++; return fn({}); } };
  const ra = await transactionWithRetry(db2, async () => { abortTransaction("残高不足"); }, { retries: 3, baseDelayMs: 1 });
  ok("db tx-retry: abort は再試行せず CONFLICT 保持", !ra.ok && ra.error.code === "CONFLICT" && ac === 1);
  for (const f of [core, prisma, errs, txf, resf]) await fs.rm(f);

  // jobs
  const jcore = await w("jcore", `export const ErrorCode={EXTERNAL:"EXTERNAL"};export class AppError extends Error{constructor(c,m,o){super(m);this.code=c;this.cause=o?.cause;}}export async function tryCatch(fn){try{return{ok:true,value:await fn()};}catch(e){return{ok:false,error:e};}}`);
  const bull = await w("bull", "export class Queue{constructor(){}async add(){}async close(){}}export class Worker{constructor(){}}");
  const mem = await w("mem", `export function createMemoryQueue(){return {};}`);
  const def = await w("def", `export function defineJob(n){return {name:n};}`);
  let jidx = (await fs.readFile(new URL("../packages/jobs/src/index.ts", import.meta.url), "utf8"))
    .replace('from "bullmq"', `from "${toSpec(bull)}"`)
    .replace('from "@platform/core"', `from "${toSpec(jcore)}"`)
    .replace('from "./memory"', `from "${toSpec(mem)}"`)
    .replace('from "./define"', `from "${toSpec(def)}"`);
  const jidxf = await w("jidx", jidx);
  const { connectionFromUrl, createQueue } = await impFile(jidxf);
  ok("jobs: URL パース", connectionFromUrl("redis://:pw@h:6380").password === "pw" && connectionFromUrl("redis://h").port === 6379);
  let jopts = null; const jq = createQueue("e", { url: "redis://h" }, (_n, o) => { jopts = o; return { add: async () => {}, close: async () => {} }; });
  ok("jobs: defaultJobOptions(attempts3)", jopts.defaultJobOptions.attempts === 3 && (await jq.add("j", {})).ok);
  for (const f of [jcore, bull, mem, def, jidxf]) await fs.rm(f);
}

// ---- 業務アプリ: 承認通知の確実配信(Outbox + 再試行 + dedup) ----
section("reliable expense notifications");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  const w = async (n, src) => { const f = `${TMP}/en-${n}-${stamp}.ts`; await fs.writeFile(f, src); return f; };
  const outbox = await w("outbox", await fs.readFile(new URL("../packages/observability/src/outbox.ts", import.meta.url), "utf8"));
  const obsidx = await w("obsidx", `export * from "${toSpec(outbox)}";`);
  const nidx = await w("nidx", 'export interface NotifyMessage { text: string } export interface NotifyChannel { send(m: NotifyMessage): Promise<void> }');
  let dedup = (await fs.readFile(new URL("../packages/notify/src/dedup.ts", import.meta.url), "utf8")).replace('from "./index"', `from "${toSpec(nidx)}"`);
  const dedupf = await w("dedup", dedup);
  const notifyidx = await w("notifyidx", `export * from "${toSpec(nidx)}";\nexport * from "${toSpec(dedupf)}";`);
  const wf = await w("wf", "export {}");
  // **`@platform/core` の最小スタブ。** 2026-08 に `AppError` を使うようにした
  // ——壊れた本文を**恒久的な失敗**として投げ、**Outbox の永久リトライを止める**
  const coreStub = await w("corestub",
    'export class AppError extends Error { constructor(code, message) { super(message); this.code = code; this.retryable = false; } }\n' +
    'export const ErrorCode = { VALIDATION: "VALIDATION" };');
  const enmail = await w("enmail", 'export function buildTransitionMails(i){ return (i.applicantEmail && i.next.status==="approved") ? [{ to:[i.applicantEmail], subject:"承認", text:i.title }] : []; }');
  const svcstore = await w("svcstore", `import { createMemoryOutboxStore } from "${toSpec(obsidx)}";\nimport { createMemorySeenStore } from "${toSpec(notifyidx)}";\nexport const notifyOutbox=createMemoryOutboxStore();\nexport const notifySeen=createMemorySeenStore();\nexport const log={info(){},warn(){}};\nexport let beh=async()=>{};\nexport const mailer={ async sendMail(){ try{ await beh(); return {ok:true,value:undefined}; }catch(e){ return {ok:false,error:{message:e.message}}; } } };\nexport function setBeh(f){ beh=f; }`);
  // **`decideDelivery` を統合した(2026-08)。** `./platform-services`(preferenceStore)
  // と `./notification-prefs`(decideDelivery・hasChannel)のスタブを追加する
  // ——未設定なら email を含む既定チャネルを返す(実際の DEFAULT_PREFERENCE と同じ形)。
  const platSvcStub = await w("platsvc", 'export const preferenceStore = { async get(){ return { defaultChannels: ["inApp","email"] }; } };');
  const notifPrefsStub = await w("notifprefs",
    'export async function decideDelivery(store, userId, event){ const pref = await store.get(userId); const channels = pref.categories?.[event.category]?.channels ?? pref.defaultChannels ?? ["inApp","email"]; return { channels, deferred:false }; }\n' +
    'export function hasChannel(decision, channel){ return !decision.deferred && decision.channels.includes(channel); }');
  // **`./observability`(アプリ内のモジュール)のスタブ。** 2026-08 に
  // `expense-notify-service` が `metrics.incrementCounter` を呼ぶようにした
  // ——**枯渇した通知がログにしか残っておらず**、見る人がいないと気づけなかった
  const obsLocal = smokeTmp("expense-obs.ts");
  await fs.writeFile(obsLocal,
    "export const metrics = { incrementCounter() {}, snapshot: () => ({ counters: {}, gauges: {} }) };");
  let svc = (await fs.readFile(new URL("../apps/internal-app/src/server/expense-notify-service.ts", import.meta.url), "utf8"))
    .replace('from "@platform/core"', `from "${toSpec(coreStub)}"`)
    .replace('from "@platform/workflow"', `from "${toSpec(wf)}"`)
    .replace('from "@platform/observability"', `from "${toSpec(obsidx)}"`)
    .replace('from "./observability"', `from "${toSpec(obsLocal)}"`)
    .replace('from "@platform/notify"', `from "${toSpec(notifyidx)}"`)
    .replace('from "../lib/expense-notify"', `from "${toSpec(enmail)}"`)
    .replace('from "./services"', `from "${toSpec(svcstore)}"`)
    .replace('from "./platform-services"', `from "${toSpec(platSvcStub)}"`)
    .replace('from "./notification-prefs"', `from "${toSpec(notifPrefsStub)}"`);
  const svcf = await w("svc", svc);
  const S = await impFile(svcf);
  const { notifyOutbox, setBeh } = await impFile(svcstore);
  const n = await S.enqueueExpenseTransition({ title: "出張費", prev: { status: "pending" }, next: { status: "approved" }, applicantEmail: "u@x.jp" });
  ok("承認通知が Outbox に積まれる", n === 1 && notifyOutbox.all()[0].status === "pending");
  let attempts = 0; setBeh(async () => { attempts++; if (attempts < 2) throw new Error("timeout"); });
  const r1 = await S.relayExpenseNotifications();
  const msg = notifyOutbox.all().find((m) => m.status === "pending"); if (msg) msg.nextAttemptAt = 0;
  const r2 = await S.relayExpenseNotifications();
  ok("一時失敗→再試行で確実配信(通知が失われない)", r1.failed === 1 && r2.sent === 1 && attempts === 2);
  for (const f of [outbox, obsidx, nidx, dedupf, notifyidx, wf, enmail, svcstore, svcf, platSvcStub, notifPrefsStub]) await fs.rm(f);
}

// ---- 通知リレーの cron 配線(scheduler→relay→metrics) ----
section("notify relay scheduler");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  const w = async (n, src) => { const f = `${TMP}/nsc-${n}-${stamp}.ts`; await fs.writeFile(f, src); return f; };
  const lock = await w("lock", (await fs.readFile(new URL("../packages/cron/src/lock.ts", import.meta.url), "utf8")));
  const runner = await w("runner", (await fs.readFile(new URL("../packages/cron/src/runner.ts", import.meta.url), "utf8")).replace('from "./lock"', `from "${toSpec(lock)}"`));
  const core = await w("core", 'export const ErrorCode={INTERNAL:"INTERNAL"};export class AppError extends Error{constructor(c,m){super(m);this.code=c;}static from(e,c){return new AppError(c,e instanceof Error?e.message:String(e));}}');
  const croner = await w("croner", "export const REG=[];export class Cron{constructor(_s,_o,fn){this.fn=fn;REG.push(this);}stop(){}}");
  let idx = (await fs.readFile(new URL("../packages/cron/src/index.ts", import.meta.url), "utf8")).replaceAll('from "croner"', `from "${toSpec(croner)}"`).replaceAll('from "@platform/core"', `from "${toSpec(core)}"`).replaceAll('from "./runner"', `from "${toSpec(runner)}"`).replaceAll('from "./lock"', `from "${toSpec(lock)}"`)
    .replace(/export \{ createRedisLockStore[^\n]*\n/, "")
    .replace(/export \{ tryAcquireFileLock[^\n]*\n/, "");
  const cidx = await w("cidx", idx);
  const obs = await w("obs", 'export const metrics={counters:{},incrementCounter(n,v,l){const k=n+JSON.stringify(l||{});this.counters[k]=(this.counters[k]||0)+v;},observeHistogram(){}};');
  const svc = await w("svc", 'export const log={info(){},warn(){},error(){}};');
  const esvc = await w("esvc", 'export let calls=0;export async function relayExpenseNotifications(){ calls++; return {sent:1,failed:0,exhausted:0}; }');
  let ns = (await fs.readFile(new URL("../apps/internal-app/src/server/notify-scheduler.ts", import.meta.url), "utf8"))
    .replace('from "@platform/cron"', `from "${toSpec(cidx)}"`)
    .replace('from "./expense-notify-service"', `from "${toSpec(esvc)}"`)
    .replace('from "./observability"', `from "${toSpec(obs)}"`)
    .replace('from "./services"', `from "${toSpec(svc)}"`)
    // **業務の滞りを数える処理**(2026-08 に追加)。
    // ここでは**数える中身は見ない**——スケジューラがジョブを登録できるかだけを見る
    .replace('from "./business-health"', `from "${toSpec(await (async () => {
      const f = smokeTmp("business-health.ts");
      await fs.writeFile(f, "export async function collectBusinessHealth() { return { overdueTasks: 0, overdueInvoices: 0, expiringContracts: 0 }; }");
      return f;
    })())}"`);
  const nsf = await w("ns", ns);
  const { createNotifyScheduler } = await impFile(nsf);
  const { REG } = await impFile(croner);
  const es = await impFile(esvc);
  const { metrics } = await impFile(obs);
  const sched = createNotifyScheduler();
  sched.start();
  ok("relay ジョブが登録される", sched.jobNames()[0] === "relay-expense-notifications");
  await REG[0].fn();
  ok("発火で relay 実行 + メトリクス出力", es.calls === 1 && Object.keys(metrics.counters).some((k) => k.includes("cron_runs_total") && k.includes("success")));
  for (const f of [lock, runner, core, croner, cidx, obs, svc, esvc, nsf]) await fs.rm(f);
}

// ---- 本番実装: Redis lock/seen/idem + SQL outbox + lifecycle + secrets ----
section("production stores / lifecycle / secrets");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  const w = async (n, src) => { const f = `${TMP}/pi-${n}-${stamp}.ts`; await fs.writeFile(f, src); return f; };
  // 共有フェイク Redis(SET NX PX / eval / exists / get / del / setValue)
  const mkRedis = () => { let clk = 0; const m = new Map(); return {
    setClock: (t) => { clk = t; },
    set: async (k, v, _p, ttl) => { const e = m.get(k); if (e && e.exp > clk) return null; m.set(k, { val: v, exp: clk + ttl }); return "OK"; },
    setValue: async (k, v, ttl) => { m.set(k, { val: v, exp: clk + ttl }); },
    get: async (k) => { const e = m.get(k); return e && e.exp > clk ? e.val : null; },
    del: async (k) => { m.delete(k); },
    exists: async (k) => { const e = m.get(k); return e && e.exp > clk ? 1 : 0; },
    eval: async (_s, _n, k, tok) => { const e = m.get(k); if (e && e.val === tok) { m.delete(k); return 1; } return 0; },
    _m: m,
  }; };

  // Redis lock
  const lockif = await w("lockif", "export interface LockStore { acquire(k: string, t: number): Promise<boolean>|boolean; release(k: string): Promise<void>|void }");
  const lockredis = await w("lockredis", (await fs.readFile(new URL("../packages/cron/src/lock-redis.ts", import.meta.url), "utf8")).replace('from "./lock"', `from "${toSpec(lockif)}"`));
  const { createRedisLockStore } = await impFile(lockredis);
  const r1 = mkRedis();
  const la = createRedisLockStore(r1), lb = createRedisLockStore(r1);
  ok("Redis lock 相互排他", (await la.acquire("j", 1000)) === true && (await lb.acquire("j", 1000)) === false);

  // Redis seen
  const seenif = await w("seenif", "export interface SeenStore { markSeen(k: string, t: number): boolean; has(k: string): boolean }");
  const seenredis = await w("seenredis", (await fs.readFile(new URL("../packages/notify/src/seen-redis.ts", import.meta.url), "utf8")).replace('from "./dedup"', `from "${toSpec(seenif)}"`));
  const { createRedisSeenStore } = await impFile(seenredis);
  const seen = createRedisSeenStore(mkRedis());
  ok("Redis seen dedup", (await seen.markSeen("m", 1000)) === false && (await seen.markSeen("m", 1000)) === true);

  // Redis idempotency
  const idemif = await w("idemif", 'export interface IdempotencyRecord { status: "in_progress"|"completed"|"failed"; result?: unknown; createdAt: number }');
  const idemredis = await w("idemredis", (await fs.readFile(new URL("../packages/observability/src/idempotency-redis.ts", import.meta.url), "utf8")).replace('from "./idempotency"', `from "${toSpec(idemif)}"`));
  const { createRedisIdempotencyStore } = await impFile(idemredis);
  const idem = createRedisIdempotencyStore(mkRedis(), 5000);
  const reserved = (await idem.reserve("op", { status: "in_progress", createdAt: 0 })) === null;
  ok("Redis idempotency 予約", reserved && (await idem.reserve("op", { status: "in_progress", createdAt: 0 })) !== null);

  // SQL outbox
  const obif = await w("obif", 'export interface OutboxMessage { id: string; topic: string; payload: unknown; status: "pending"|"sent"|"failed"; attempts: number; createdAt: number; nextAttemptAt?: number } export interface OutboxStore { fetchPending(l: number, n: number): unknown; markSent(id: string): unknown; markFailed(id: string, e: string, a: number, n?: number): unknown }');
  const obsql = await w("obsql", (await fs.readFile(new URL("../packages/observability/src/outbox-sql.ts", import.meta.url), "utf8")).replace('from "./outbox"', `from "${toSpec(obif)}"`));
  const { createSqlOutboxStore } = await impFile(obsql);
  const rows = [];
  const client = { insert: async (m) => rows.push({ ...m }), selectPending: async () => rows.filter((r) => r.status === "pending"), updateSent: async (id) => { const r = rows.find((x) => x.id === id); if (r) r.status = "sent"; }, updateFailed: async () => {} };
  let seq = 0; const outbox = createSqlOutboxStore(client, () => `id-${++seq}`, () => 0);
  await outbox.add("t", { a: 1 }); await outbox.markSent("id-1");
  ok("SQL outbox add+markSent", rows.length === 1 && rows[0].status === "sent");

  // lifecycle
  const lc = await w("lc", (await fs.readFile(new URL("../packages/core/src/lifecycle.ts", import.meta.url), "utf8")));
  const { createLifecycle } = await impFile(lc);
  const order = [];
  const life = createLifecycle({ exitProcess: false, onSignal: () => {}, hookTimeoutMs: 500 });
  life.onShutdown("a", () => { order.push("a"); }); life.onShutdown("b", () => { order.push("b"); });
  await life.shutdown("t");
  ok("lifecycle 逆順後始末 + 二重防止", JSON.stringify(order) === JSON.stringify(["b", "a"]) && life.isShuttingDown());

  // secrets
  const sec = await w("sec", (await fs.readFile(new URL("../packages/secrets/src/index.ts", import.meta.url), "utf8")));
  const { createSecretStore } = await impFile(sec);
  let fetches = 0, clk = 0;
  const store = createSecretStore({ get: async (n) => { fetches++; return n === "K" ? "v" : null; } }, { ttlMs: 1000, now: () => clk });
  await store.get("K"); await store.get("K");
  const cachedOnce = fetches === 1; // 2回 get でも fetch は1回(TTL内キャッシュ)
  let threw = false; try { await store.require("X"); } catch { threw = true; }
  ok("secrets キャッシュ + require 例外", cachedOnce && threw);

  for (const f of [lockif, lockredis, seenif, seenredis, idemif, idemredis, obif, obsql, lc, sec]) await fs.rm(f);
}

// ---- 監視の出力先: OTLP エクスポータ + SLO アラート ----
section("otlp exporter / alerting");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  const tr = `${TMP}/oa-trace-${stamp}.ts`;
  await fs.writeFile(tr, 'export interface Span { traceId: string; spanId: string; parentSpanId?: string; name: string; startTime: number; endTime?: number; durationMs?: number; attributes: Record<string, unknown>; status: "ok"|"error"; error?: string } export type SpanExporter = (span: Span) => void;');
  const otlp = `${TMP}/oa-otlp-${stamp}.ts`;
  await fs.writeFile(otlp, (await fs.readFile(new URL("../packages/observability/src/otlp.ts", import.meta.url), "utf8")).replace('from "./trace"', `from "${toSpec(tr)}"`));
  const { createOtlpExporter } = await impFile(otlp);
  const posts = [];
  const exp = createOtlpExporter({ endpoint: "http://c/v1/traces", serviceName: "internal-app", maxBatchSize: 2, fetchImpl: async (_u, i) => { posts.push(JSON.parse(i.body)); return { ok: true, status: 200 }; }, scheduler: () => 1, clearScheduler: () => {} });
  const span = (id) => ({ traceId: id, spanId: "s" + id, name: "GET /x", startTime: 1000, endTime: 1050, attributes: { "http.method": "GET" }, status: "ok" });
  exp.export(span("1")); exp.export(span("2"));
  await new Promise((r) => setTimeout(r, 5));
  ok("OTLP バッチ送信(service.name/traceId)", posts.length === 1 && posts[0].resourceSpans[0].resource.attributes[0].value.stringValue === "internal-app");

  const al = `${TMP}/oa-al-${stamp}.ts`;
  await fs.writeFile(al, (await fs.readFile(new URL("../packages/observability/src/alerting.ts", import.meta.url), "utf8")));
  const A = await impFile(al);
  const mgr = A.createAlertManager([{ name: "err", severity: "critical", condition: A.errorRateAbove("t", "e", 0.05), describe: () => "エラー率高" }]);
  const view = (c) => ({ counters: c, gauges: {}, histograms: {} });
  const fired = mgr.evaluate(view({ t: 100, e: 10 }));
  const recovered = mgr.evaluate(view({ t: 300, e: 3 }));
  ok("SLO アラート 発報→回復", fired.length === 1 && fired[0].firing && recovered[0].firing === false);

  for (const f of [tr, otlp, al]) await fs.rm(f);
}

// ---- feature flags / PII 保護 ----
section("feature flags / pii");
{
  const F = await impFile(new URL("../packages/flags/src/index.ts", import.meta.url));
  ok("flag kill switch", F.evaluateFlag(false) === false && F.evaluateFlag({ enabled: false, rolloutPercent: 100 }) === false);
  ok("flag 100%/0%", F.evaluateFlag({ rolloutPercent: 100 }, { key: "u" }, "f") === true && F.evaluateFlag({ rolloutPercent: 0 }, { key: "u" }, "f") === false);
  // **段階的な公開が実際に効くか。** 「10% に出す」つもりが全員に出ると、
  // **不具合のある新機能が一気に広がる**——段階公開はそれを防ぐ仕組みなので、
  // 効いていないと意味がない(2026-08 に追加)
  {
    const count = (pct) => {
      let on = 0;
      for (let i = 0; i < 1000; i += 1) {
        if (F.evaluateFlag({ enabled: true, rolloutPercent: pct }, { key: `u${i}` }, "newUI")) on += 1;
      }
      return on;
    };
    const at10 = count(10), at50 = count(50);
    // **おおよそ指定どおりに分かれる**(ハッシュなので厳密には一致しない)
    ok("flag 段階公開: 10% はおよそ 10%", at10 >= 50 && at10 <= 150);
    ok("flag 段階公開: 50% はおよそ 50%", at50 >= 430 && at50 <= 570);
    // **同じ人は毎回同じ結果**(でないと画面を開くたびに機能が出たり消えたりする)
    const twice = [0, 1].map(() => F.evaluateFlag({ enabled: true, rolloutPercent: 50 }, { key: "u1" }, "newUI"));
    ok("flag 段階公開: 同じ人は同じ結果", twice[0] === twice[1]);
    // **フラグごとに別の集団**(でないと「いつも同じ人が実験台」になる)
    let differ = 0;
    for (let i = 0; i < 100; i += 1) {
      const a = F.evaluateFlag({ enabled: true, rolloutPercent: 50 }, { key: `u${i}` }, "A");
      const b = F.evaluateFlag({ enabled: true, rolloutPercent: 50 }, { key: `u${i}` }, "B");
      if (a !== b) differ += 1;
    }
    ok("flag 段階公開: フラグごとに別の集団", differ > 20);
    // **`flagName` を省略すると同じ集団になる**——「いつも同じ人が実験台」に
    // なり、その人たちだけが未検証の機能を次々に踏む。
    // **省略しても動いてしまう**ので気づきにくい(README に明記した)
    let sameWhenOmitted = 0;
    for (let i = 0; i < 100; i += 1) {
      const a = F.evaluateFlag({ enabled: true, rolloutPercent: 50 }, { key: `u${i}` });
      const b = F.evaluateFlag({ enabled: true, rolloutPercent: 50 }, { key: `u${i}` });
      if (a === b) sameWhenOmitted += 1;
    }
    ok("flag: flagName を省略すると全フラグで同じ集団(落とし穴)", sameWhenOmitted === 100);
    // **`createFlags` はフラグ名を自動で渡す**ので、この落とし穴を踏まない
    ok("flag: createFlags はフラグ名を自動で渡す",
       /evaluateFlag\(rule, context, name\)/.test(
         await (await import("node:fs/promises")).readFile(
           new URL("../packages/flags/src/index.ts", import.meta.url), "utf8")));
  }
  let on = 0; for (let i = 0; i < 1000; i++) if (F.evaluateFlag({ rolloutPercent: 50 }, { key: `u${i}` }, "f")) on++;
  ok("flag 50% ロールアウト分布(" + on + "/1000)", on > 400 && on < 600);
  ok("flag allow/deny", F.evaluateFlag({ rolloutPercent: 0, allow: [{ role: "admin" }] }, { attributes: { role: "admin" } }) === true && F.evaluateFlag({ deny: [{ r: 1 }] }, { attributes: { r: 1 } }) === false);
  const flags = F.createFlags(F.createStaticProvider({ a: true }));
  ok("flag 未定義は false(安全側)", (await flags.isEnabled("a")) === true && (await flags.isEnabled("missing")) === false);

  const { readFile: _rfPii } = await import("node:fs/promises");
  // **相対の再エクスポートは絶対パスに直す。**
  // /tmp に写して読み込むので、`from "./mask"` のままだと
  // **/tmp/mask を探しに行って落ちます**(2026-08、伏せ字を ./mask に分けた際)。
  const _piiDir = new URL("../packages/pii/src/", import.meta.url).href;
  const _piiSrc = (await _rfPii(new URL("../packages/pii/src/index.ts", import.meta.url), "utf8"))
    .replace(/export \* from "\.\/(identity-mask|subject-rights)";\n?/g, "")
    .replace(/(from ")\.\/([^"]+)(")/g, (_m, a2, name, c) => `${a2}${_piiDir}${name}.ts${c}`);
  const _piiF = `${TMP}/pii-index-${smokeStamp()}.ts`; await (await import("node:fs/promises")).writeFile(_piiF, _piiSrc);
  const P = await impFile(_piiF);
  ok("pii マスキング", P.maskEmail("taro@example.co.jp") === "t***@example.co.jp" && P.maskPhone("090-1234-5678") === "*******5678");
  ok("pii blind index(正規化+決定的)", P.blindIndex("A@B.jp ", "k") === P.blindIndex("a@b.jp", "k") && P.blindIndex("x", "k1") !== P.blindIndex("x", "k2"));
  const store = new Map(); let n = 0;
  const c = P.createFieldCipher({ encrypt: (p) => { const t = `e${++n}`; store.set(t, p); return t; }, decrypt: (t) => store.get(t) });
  ok("pii フィールド暗号往復", P.createFieldCipher && c.decryptField(c.encryptField("secret")) === "secret" && c.encryptField(null) === null);
  const a = P.anonymizeRecord({ id: "1", name: "山田", total: 5 }, ["name"]);
  ok("pii 匿名化(PIIのみ) + 保持判定", a.name === "[削除済み]" && a.total === 5 && P.isRetentionExpired(0, 30, 40 * 86400000) === true);
}

// ---- WebSocket 水平スケール(Redis Pub/Sub ブロードキャスト) ----
section("broadcast hub (horizontal scale)");
{
  const { createBroadcastHub } = await impFile(new URL("../packages/realtime/src/broadcast.ts", import.meta.url));
  const handlers = new Map();
  const mkClient = () => { const mine = []; return {
    publish: async (c, m) => { const hs = handlers.get(c); if (hs) for (const h of hs) h(m); },
    subscribe: async (c, h) => { if (!handlers.has(c)) handlers.set(c, new Set()); handlers.get(c).add(h); mine.push({ c, h }); },
    unsubscribe: async (c) => { mine.filter((e) => e.c === c).forEach((e) => handlers.get(c)?.delete(e.h)); },
  }; };
  const a = createBroadcastHub(mkClient()); const b = createBroadcastHub(mkClient());
  const ra = [], rb = [];
  await a.subscribe("room", "1", (d) => ra.push(d));
  await b.subscribe("room", "2", (d) => rb.push(d));
  await a.publish("room", { t: "hi" });
  ok("インスタンス跨ぎ配信 + 二重配信なし", ra.length === 1 && rb.length === 1 && JSON.parse(ra[0]).t === "hi");
  await a.unsubscribe("room", "1");
  const before = ra.length;
  await b.publish("room", { n: 2 });
  ok("unsubscribe 後は配信されない", a.localCount("room") === 0 && ra.length === before && rb.length === 2);
}

// ---- エラー制御: 分類中央化 / バルクヘッド / プロセス安全網 ----
section("error policy / bulkhead / process guards");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  const w = async (n, src) => { const f = `${TMP}/ec-${n}-${stamp}.ts`; await fs.writeFile(f, src); return f; };
  const err = await w("err", 'export const ErrorCode={VALIDATION:"VALIDATION",NOT_FOUND:"NOT_FOUND",UNAUTHORIZED:"UNAUTHORIZED",FORBIDDEN:"FORBIDDEN",RATE_LIMITED:"RATE_LIMITED",CONFLICT:"CONFLICT",EXTERNAL:"EXTERNAL",DATABASE:"DATABASE",CONFIG:"CONFIG",INTERNAL:"INTERNAL"};export class AppError extends Error{constructor(c,m,o){super(m);this.code=c;this.details=o?.details;}}');
  const ep = await w("ep", (await fs.readFile(new URL("../packages/core/src/error-policy.ts", import.meta.url), "utf8")).replace('from "./error"', `from "${toSpec(err)}"`));
  const { httpStatusFor, isRetryable, toErrorEnvelope } = await impFile(ep);
  const { AppError, ErrorCode } = await impFile(err);
  ok("HTTP ステータス中央化(409/429/500)", httpStatusFor(new AppError(ErrorCode.CONFLICT, "x")) === 409 &&
     httpStatusFor(new AppError(ErrorCode.RATE_LIMITED, "x")) === 429 &&
     httpStatusFor(new Error("r")) === 500);
  // **等幅フォントを直書きしない。**
  // 2026-08 まで 110 か所が素の `monospace` を書いており、多くの環境で
  // Courier に落ちて細く小さく描画されていた(等幅にした目的が果たせない)。
  // さらに `--font-mono` は**定義されていないのに 4 か所から参照**されていた
  // (フォールバック付きだったので誰も気づかなかった)。
  {
    const tokens = await fs.readFile(new URL("../packages/ui/src/styles/tokens.css", import.meta.url), "utf8");
    ok("--font-mono が定義されている(参照だけして未定義にしない)",
      /--font-mono:\s*ui-monospace/.test(tokens));
  }
  // **基盤のラッパーが traceId を落とさない。**
  // 同じことをするラッパーが 4 段階あり(`handleRoute` / 雛形の `withApi` /
  // 社内アプリの `withApiObservability` / 何も無い)、2026-08 まで
  // **基盤自身の `handleRoute` だけが traceId を付けていなかった**。
  // 呼び出し側は「基盤の作法どおりに書いた」つもりで、追跡できない応答を返していた。
  {
    const h = await fs.readFile(new URL("../packages/http/src/handler.ts", import.meta.url), "utf8");
    ok("handleRoute は相関 ID を応答に載せる",
      /getRequestId\(\)/.test(h) && /traceId/.test(h) && /x-request-id/.test(h));
  }
  // **ステータスの対応表を 2 か所に持たない。**
  // 2026-08 まで `@platform/http` が独自の `STATUS_BY_CODE` を持ち、
  // **`DATABASE` が 500(core は 503)**と食い違っていた。同じ AppError が
  // 通る経路によって 500 と 503 に分かれ、再試行してよいかの判断がつかない状態だった。
  // `ERROR_POLICY` は自ら「唯一の情報源」と宣言しているので、表は 1 つに保つ。
  {
    const httpStatus = await fs.readFile(new URL("../packages/http/src/status.ts", import.meta.url), "utf8");
    ok("http は独自のステータス表を持たない(ERROR_POLICY から導出)",
      !/\[ErrorCode\.\w+\]:\s*\d+/.test(httpStatus) && /ERROR_POLICY/.test(httpStatus));
  }
  ok("再試行分類(EXTERNAL可/VALIDATION不可/未分類不可)", isRetryable(new AppError(ErrorCode.EXTERNAL, "x")) === true &&
     isRetryable(new AppError(ErrorCode.VALIDATION, "x")) === false &&
     isRetryable(new Error("x")) === false);
  // **details は VALIDATION のときだけ外に出す。**
  // それ以外(DB・外部連携・認可)の details には内部の事情が入りうる:
  // テーブル名・接続先 URL・存在するリソース ID など。
  // 「個人情報を含めないこと」と書くだけでは守れないので、既定で出さない。
  ok("エラーエンベロープ(traceId + 内部秘匿 + details は VALIDATION のみ)",
    toErrorEnvelope(new AppError(ErrorCode.NOT_FOUND, "x", { details: { id: 1 } }), "t1").error.traceId === "t1" &&
    toErrorEnvelope(new Error("secret")).error.code === "UNKNOWN" &&
    toErrorEnvelope(new AppError(ErrorCode.NOT_FOUND, "x", { details: { table: "users" } })).error.details === undefined &&
    toErrorEnvelope(new AppError(ErrorCode.DATABASE, "x", { details: { sql: "SELECT …" } })).error.details === undefined &&
    toErrorEnvelope(new AppError(ErrorCode.VALIDATION, "x", { details: { field: "email" } })).error.details?.field === "email");

  const bh = await w("bh", (await fs.readFile(new URL("../packages/core/src/bulkhead.ts", import.meta.url), "utf8")).replace('from "./error"', `from "${toSpec(err)}"`));
  const cb = await w("cb", (await fs.readFile(new URL("../packages/core/src/circuit-breaker.ts", import.meta.url), "utf8")).replace('from "./error"', `from "${toSpec(err)}"`));
  const CB = await impFile(cb);

  // **相手が落ちているのに呼び続けると、自分まで巻き込まれて落ちる。**
  // 1 回の呼び出しがタイムアウトまで数秒かかると、待ちが積み上がって
  // 接続が枯渇し、無関係な機能まで応答しなくなる。
  {
    let t = 0;
    const breaker = CB.createCircuitBreaker({ failureThreshold: 3, resetTimeoutMs: 1_000, now: () => t });
    const boom = () => Promise.reject(new Error("boom"));
    for (let i = 0; i < 3; i += 1) { try { await breaker.execute(boom); } catch { /* 期待どおり */ } }

    ok("CircuitBreaker 失敗が閾値に達したら open(以降は**呼ばずに**即座に失敗)",
      breaker.stats().state === "open" &&
      await (async () => {
        try { await breaker.execute(() => Promise.resolve("ok")); return false; }
        catch { return breaker.stats().rejectedCalls === 1; }
      })());

    t = 1_001;
    ok("CircuitBreaker 一定時間後は half-open(様子見)・成功すれば closed に戻る",
      breaker.stats().state === "half-open" &&
      (await breaker.execute(() => Promise.resolve("ok"))) === "ok" &&
      breaker.stats().state === "closed");
  }

  // **half-open で失敗したら即座に open へ戻す。**
  // まだ回復していない相手に流し続けると、回復しかけたところを潰す
  {
    let t = 0;
    const breaker = CB.createCircuitBreaker({ failureThreshold: 2, resetTimeoutMs: 100, now: () => t });
    const boom = () => Promise.reject(new Error("x"));
    for (let i = 0; i < 2; i += 1) { try { await breaker.execute(boom); } catch { /* 期待どおり */ } }
    t = 101;
    const wasHalfOpen = breaker.stats().state === "half-open";
    try { await breaker.execute(boom); } catch { /* 期待どおり */ }
    ok("CircuitBreaker half-open で失敗したら**即座に open へ戻す**(回復しかけを潰さない)",
      wasHalfOpen && breaker.stats().state === "open");
  }

  // **相手のせいでない失敗は数えない。**
  // 入力が不正(400)で遮断すると、正しい要求まで通らなくなる
  {
    const breaker = CB.createCircuitBreaker({
      failureThreshold: 2, resetTimeoutMs: 100,
      isFailure: (e) => !(e instanceof E.AppError && e.code === E.ErrorCode.VALIDATION),
    });
    for (let i = 0; i < 5; i += 1) {
      try { await breaker.execute(() => Promise.reject(new E.AppError(E.ErrorCode.VALIDATION, "入力が不正"))); }
      catch { /* 期待どおり */ }
    }
    ok("CircuitBreaker **入力エラーでは遮断しない**(相手が落ちたわけではない)",
      breaker.stats().state === "closed");
  }

  ok("CircuitBreaker 手動で開閉できる(相手のメンテナンス中・復旧確認時)",
    (() => {
      const breaker = CB.createCircuitBreaker({ failureThreshold: 3, resetTimeoutMs: 1_000 });
      breaker.trip();
      const opened = breaker.stats().state === "open";
      breaker.reset();
      return opened && breaker.stats().state === "closed";
    })());
  const { createBulkhead } = await impFile(bh);
  const defer = () => { let r; const p = new Promise((res) => { r = res; }); return { p, resolve: r }; };
  const b = createBulkhead({ maxConcurrent: 2 });
  const ds = [defer(), defer(), defer()]; const ps = ds.map((x) => b.run(() => x.p));
  await new Promise((r) => setTimeout(r, 5));
  const limited = b.active() === 2 && b.queued() === 1;
  ds.forEach((x) => x.resolve()); await Promise.all(ps);
  ok("バルクヘッド 並行制限 + キュー + 全完了で0", limited && b.active() === 0);
  // queueTimeoutMs: 順番待ちタイムアウト
  const bt = createBulkhead({ maxConcurrent: 1, queueTimeoutMs: 20 });
  let rel; const hold = new Promise((r) => { rel = r; }); const run = bt.run(() => hold);
  let qto = false; try { await bt.run(async () => "x"); } catch (e) { qto = e.code === "RATE_LIMITED"; }
  ok("バルクヘッド 待機タイムアウトで遮断", qto && bt.queued() === 0);
  rel(); await run;
  // リトライ層の分類統一(notify withRetry の既定 = defaultShouldRetry)
  const nidx2 = await w("nidx2", "export {}");
  const ncore = await w("ncore", 'export function defaultShouldRetry(e){ return !(e && e.__perm); }');
  let nres = (await fs.readFile(new URL("../packages/notify/src/resilient.ts", import.meta.url), "utf8"))
    .replace('from "@platform/core"', `from "${toSpec(ncore)}"`)
    .replace('from "./index"', `from "${toSpec(nidx2)}"`);
  const nresf = await w("nresf", nres);
  const { withRetry } = await impFile(nresf);
  let perm = 0; const permErr = Object.assign(new Error("v"), { __perm: true });
  const ch = withRetry({ async send() { perm++; throw permErr; } }, { retries: 3, sleep: async () => {} });
  try { await ch.send({ text: "x" }); } catch {}
  let trans = 0;
  const ch2 = withRetry({ async send() { trans++; if (trans < 3) throw new Error("transient"); } }, { retries: 3, sleep: async () => {} });
  await ch2.send({ text: "x" });
  ok("リトライ層 分類統一(恒久1回/一時は再試行)", perm === 1 && trans === 3);
  await fs.rm(nidx2); await fs.rm(ncore); await fs.rm(nresf);

  const pg = await w("pg", (await fs.readFile(new URL("../packages/core/src/process-guard.ts", import.meta.url), "utf8")));
  const { installProcessGuards } = await impFile(pg);
  const H = {}; let exitCode = null; let fatal = false;
  installProcessGuards({ logger: { error: () => {}, warn: () => {} }, onProcess: (e, h) => { H[e] = h; }, exit: (c) => { exitCode = c; }, onFatal: async () => { fatal = true; } });
  H.unhandledRejection(new Error("r"));
  const noExitOnReject = exitCode === null;
  H.uncaughtException(new Error("fatal"));
  await new Promise((r) => setTimeout(r, 10));
  ok("プロセス安全網(拒否は継続/致命は後始末→exit1)", noExitOnReject && fatal && exitCode === 1);

  for (const f of [err, ep, bh, pg]) await fs.rm(f);
}

// ---- エラー制御: 分類中央化 / バルクヘッド / プロセス安全網 / API エンベロープ ----
// **送信の二重実行を防ぐ。** 利用者は応答が無いと**もう一度押す**ので、
// 防がないと**問い合わせや申請が 2 件登録される**。
// `disabled` だけでは Enter 連打に間に合わない(再描画が追いつかない)ので、
// `useRef` で見張る必要がある(2026-08 に基盤へ移した)
{
  const fsu = await import("node:fs/promises");
  const src = await fsu.readFile(new URL("../packages/ui/src/components/use-submit.ts", import.meta.url), "utf8");
  ok("useSubmit: useRef で送信中を見張る(再描画を待たない)",
     /const running = React\.useRef\(false\)/.test(src) && /if \(running\.current\) return;/.test(src));
  ok("useSubmit: finally で必ず解除する(例外でも次が押せる)",
     /finally \{\s*\n\s*running\.current = false;/.test(src));
  // **問い合わせフォームが実際に使っている**(基盤に置いても使われなければ意味が無い)
  // **ページビュー計測も基盤へ**(2 アプリで同じラッパーを持っていた)。
  // **名前空間をアプリごとに分ける**——同じブラウザで社内アプリと公開サイトを
  // 開いたとき、**セッション ID が混ざると計測が繋がる**
  const pv = await fsu.readFile(new URL("../packages/ui/src/components/use-pageview.ts", import.meta.url), "utf8");
  ok("usePageview: セッションはタブを閉じたら消す", /kind: "session"/.test(pv));
  ok("usePageview: 名前空間で分ける", /namespace,/.test(pv));
  const pub = await fsu.readFile(new URL("../apps/public-site/src/app/beacon-client.tsx", import.meta.url), "utf8");
  const inta = await fsu.readFile(new URL("../apps/internal-app/src/app/analytics/beacon-client.tsx", import.meta.url), "utf8");
  ok("2 アプリとも usePageview を使う", /usePageview\(/.test(pub) && /usePageview\(/.test(inta));
  // **公開サイトは匿名**(利用者を送らない)
  ok("公開サイトは userId を送らない", !/userId/.test(pub.replace(/\/\*[\s\S]*?\*\//g, "")));

  // **フォーム自体も基盤へ移した**(2026-08)。2 アプリで項目も作りも同じで、
  // 違うのは**送信先とカテゴリだけ**だった
  const cf = await fsu.readFile(new URL("../packages/ui/src/components/contact-form.tsx", import.meta.url), "utf8");
  ok("ContactForm が useSubmit を使う(二重送信の防止)", /useSubmit\(/.test(cf) && /disabled=\{sending\}/.test(cf));
  ok("ContactForm は結果を読み上げに伝える", /role="alert"/.test(cf) && /role="status"/.test(cf));
  const contact = await fsu.readFile(new URL("../apps/public-site/src/app/contact/contact-client.tsx", import.meta.url), "utf8");
  ok("問い合わせフォームが基盤の ContactForm を使う", /<ContactForm/.test(contact));
}

section("error control: policy / bulkhead / guard / envelope");
// **書き込みの共通ガード**(本文サイズ・CSRF・レート制限)。
// 3 つとも「書き忘れても動いてしまう」ので、ルートごとに書くと抜ける
// ——抜けても**平常時は何も起きず、攻撃されて初めて分かる**(2026-08 に基盤へ移した)
{
  const fsg = await import("node:fs/promises");
  const GP = `${TMP}/guard-write-${smokeStamp()}.ts`;
  await fsg.writeFile(GP, (await fsg.readFile(new URL("../packages/guard/src/index.ts", import.meta.url), "utf8"))
    .replace(/^import[^\n]*from "@platform\/[^"]*";$/gm, "")
    .replace(/^export (async )?function (?!guardWrite|currentSession)[\s\S]*?\n\}$/gm, ""));
  const GW = await impFile(GP);
  const mk = (method, headers = {}) => new Request("https://app.example.jp/api/items", { method, headers });

  // **ログイン中の利用者を返す(未ログインは null)。** `requireSession` と対。
  // **`Request` をそのまま渡せる**——各アプリが
  // `session.read(req.headers.get("cookie"))` を書いていた(2026-08 に基盤へ)
  {
    const fake = { read: (h) => (h === "session=ok" ? { email: "a@x.jp" } : null) };
    const withCookie = new Request("https://x.jp/", { headers: { cookie: "session=ok" } });
    ok("currentSession: Request から読める", GW.currentSession(withCookie, fake)?.email === "a@x.jp");
    ok("currentSession: 文字列でも読める", GW.currentSession("session=ok", fake)?.email === "a@x.jp");
    // **無効・未ログインは区別せず null**(区別すると偽造の手がかりになる)
    ok("currentSession: 未ログインは null", GW.currentSession(new Request("https://x.jp/"), fake) === null);
    ok("currentSession: 壊れた値も null", GW.currentSession("session=broken", fake) === null);
  }

  ok("guardWrite: GET は素通し", (await GW.guardWrite(mk("GET"))) === null);
  ok("guardWrite: 本文が大きすぎたら 413",
     (await GW.guardWrite(mk("POST", { "content-length": "2000000" })))?.status === 413);
  ok("guardWrite: 別オリジンからの書き込みは 403",
     (await GW.guardWrite(mk("POST", { origin: "https://evil.example.com" })))?.status === 403);
  ok("guardWrite: Origin が無ければ通す(サーバ間通信)",
     (await GW.guardWrite(mk("POST"))) === null);
  ok("guardWrite: 同一オリジンは通す",
     (await GW.guardWrite(mk("POST", { origin: "https://app.example.jp" }))) === null);
  // **上限を超えたら 429**(ストア障害時は通す = fail-open)
  const over = { check: async () => ({ ok: true, value: { allowed: false } }) };
  ok("guardWrite: 上限超過は 429", (await GW.guardWrite(mk("POST"), { limiter: over }))?.status === 429);
  const broken = { check: async () => ({ ok: false }) };
  ok("guardWrite: ストア障害なら通す(fail-open)", (await GW.guardWrite(mk("POST"), { limiter: broken })) === null);
  await fsg.rm(GP, { force: true });
}
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  const w = async (n, src) => { const f = `${TMP}/ec-${n}-${stamp}.ts`; await fs.writeFile(f, src); return f; };
  const errmod = await w("err", 'export const ErrorCode = { VALIDATION:"VALIDATION", NOT_FOUND:"NOT_FOUND", UNAUTHORIZED:"UNAUTHORIZED", FORBIDDEN:"FORBIDDEN", RATE_LIMITED:"RATE_LIMITED", CONFLICT:"CONFLICT", EXTERNAL:"EXTERNAL", DATABASE:"DATABASE", CONFIG:"CONFIG", INTERNAL:"INTERNAL" }; export class AppError extends Error { constructor(c, m, o) { super(m); this.code = c; this.details = o?.details; } }');

  // error-policy
  const ep = await w("ep", (await fs.readFile(new URL("../packages/core/src/error-policy.ts", import.meta.url), "utf8")).replace('from "./error"', `from "${toSpec(errmod)}"`));
  const { httpStatusFor, isRetryable, toErrorEnvelope } = await impFile(ep);
  const { AppError, ErrorCode } = await impFile(errmod);
  ok("エラー分類: status/retryable 中央化", httpStatusFor(new AppError(ErrorCode.CONFLICT, "x")) === 409 &&
     isRetryable(new AppError(ErrorCode.DATABASE, "x")) === true &&
     isRetryable(new AppError(ErrorCode.VALIDATION, "x")) === false);
  const env = toErrorEnvelope(new Error("secret"), "t1");
  ok("エンベロープは内部詳細を漏らさない", env.error.code === "UNKNOWN" && !JSON.stringify(env).includes("secret"));

  // bulkhead
  const bh = await w("bh", (await fs.readFile(new URL("../packages/core/src/bulkhead.ts", import.meta.url), "utf8")).replace('from "./error"', `from "${toSpec(errmod)}"`));
  const { createBulkhead } = await impFile(bh);
  const defer = () => { let r; const p = new Promise((res) => (r = res)); return { p, resolve: r }; };
  const b = createBulkhead({ maxConcurrent: 2 });
  const d1 = defer(), d2 = defer(), d3 = defer();
  const ps = [b.run(() => d1.p), b.run(() => d2.p), b.run(() => d3.p)];
  await new Promise((r) => setTimeout(r, 5));
  const limited = b.active() === 2 && b.queued() === 1;
  d1.resolve(); d2.resolve(); d3.resolve(); await Promise.all(ps);
  ok("バルクヘッド: 同時実行を上限に制限", limited && b.active() === 0);
  const b2 = createBulkhead({ maxConcurrent: 1, maxQueue: 0 });
  const dd = defer(); const held = b2.run(() => dd.p);
  await new Promise((r) => setTimeout(r, 5));
  let rejected = false; try { await b2.run(() => Promise.resolve()); } catch (e) { rejected = e.code === "RATE_LIMITED"; }
  dd.resolve(); await held;
  ok("バルクヘッド: 超過はバックプレッシャで拒否", rejected);

  // process guard
  const pg = await w("pg", (await fs.readFile(new URL("../packages/core/src/process-guard.ts", import.meta.url), "utf8")));
  const { installProcessGuards } = await impFile(pg);
  const h = {}; let exitCode = null; let fatal = false;
  installProcessGuards({ logger: { error: () => {}, warn: () => {} }, onProcess: (e, fn) => { h[e] = fn; }, exit: (c) => { exitCode = c; }, onFatal: () => { fatal = true; } });
  h.unhandledRejection(new Error("r"));
  const noExitOnReject = exitCode === null;
  h.uncaughtException(new Error("f"));
  await new Promise((r) => setTimeout(r, 10));
  ok("プロセス安全網: 拒否は継続・致命は後始末して exit(1)", noExitOnReject && fatal && exitCode === 1);

  for (const f of [errmod, ep, bh, pg]) await fs.rm(f);
}

// ---- 業務ドメイン: 消費税/インボイス / 一括インポート / 採番 ----
section("tax / importer / sequence");
{
  const { readFile: _rfTax } = await import("node:fs/promises");
  const { writeFile: _wfTax } = await import("node:fs/promises");
  // **兄弟モジュールを削らずに全部写す。** 以前は `withholding` を除去して
  // 読んでいたが、その形だと**新しく公開したものが毎回落ちる**
  // (2026-08、`stamp-tax` を公開した瞬間に ERR_MODULE_NOT_FOUND になった)。
  const _taxF = await copyTaxPackage(_rfTax, _wfTax, smokeStamp());
  const T = await impFile(_taxF);
  ok("消費税 税込/税抜(誤差なし)", T.grossFromNet(1000, 10) === 1100 && T.netFromGross(1100, 10) === 1000);
  ok("軽減税率 8%", T.taxAmount(1000, 8) === 80);
  const sum = T.summarizeTax([{ net: 3000, rate: 10 }, { net: 500, rate: 8 }, { net: 300, rate: 0 }]);
  ok("適格請求書 税率別集計(3区分/tax340)", sum.byRate.length === 3 && sum.tax === 340 && sum.gross === 4140);
  ok("区分合計で丸める(105x2→21)", T.summarizeTax([{ net: 105, rate: 10 }, { net: 105, rate: 10 }]).byRate[0].tax === 21);
  const genCorp = (b) => { let x = 0; for (let i = 0; i < 12; i++) x += Number(b[11 - i]) * (i % 2 === 0 ? 1 : 2); return String(9 - (x % 9)) + b; };
  ok("登録番号チェックディジット検証", T.isValidInvoiceNumber("T" + genCorp("234567890123")) === true && T.isValidInvoiceNumber("T123") === false);

  const I = await impFile(new URL("../packages/importer/src/index.ts", import.meta.url));
  const validate = (raw) => raw.name ? { ok: true, value: { name: raw.name } } : { ok: false, errors: ["名前必須"] };
  const rep = I.validateRows([{ name: "a" }, { name: "" }], validate);
  ok("インポート 有効/エラー振り分け(行番号)", rep.valid.length === 1 && rep.errors[0].rowIndex === 2);
  let applied = 0;
  const abort = await I.runImport([{ name: "a" }, { name: "" }], validate, { apply: async (v) => { applied = v.length; } });
  const part = await I.runImport([{ name: "a" }, { name: "" }], validate, { partial: true, apply: async (v) => { applied = v.length; } });
  ok("エラー時 全件中止 / partial は有効行のみ", abort.committed === false && part.applied === 1);

  const S = await impFile(new URL("../packages/sequence/src/index.ts", import.meta.url));
  const seq = S.createSequencer(S.createMemorySequenceStore(), "inv", { prefix: "INV-", padding: 6, resetPeriod: "yearly" });
  const a2024 = await seq.next(new Date("2024-06-01"));
  const b2025 = await seq.next(new Date("2025-01-05"));
  ok("採番 年次リセット + ゼロ埋め", a2024 === "INV-2024-000001" && b2025 === "INV-2025-000001");
}

// ---- Webhook 受信 / API キー / 全銀フォーマット ----
section("webhook / apikey / zengin");
{
  const { createHmac } = await import("node:crypto");
  const W = await impFile(new URL("../packages/webhook/src/index.ts", import.meta.url));
  const secret = "whsec";
  const sign = (p, pre = "") => pre + createHmac("sha256", secret).update(p).digest("hex");
  ok("webhook HMAC 署名検証", W.verifyHmacSignature({ payload: "x", signature: sign("x"), secret }) === true && W.verifyHmacSignature({ payload: "x2", signature: sign("x"), secret }) === false);
  const seen = [];
  const rc = W.createWebhookReceiver({ secret, signaturePrefix: "sha256=", parse: JSON.parse, eventId: (e) => e.id, eventType: (e) => e.type });
  rc.on("paid", async (e) => { seen.push(e.amount); });
  const body = JSON.stringify({ id: "e1", type: "paid", amount: 100 });
  const p1 = await rc.handle(body, sign(body, "sha256="));
  const p2 = await rc.handle(body, sign(body, "sha256="));
  const p3 = await rc.handle(body, "sha256=bad");
  ok("webhook 署名→冪等→ディスパッチ", p1.status === "processed" && p2.status === "duplicate" && p3.status === "invalid_signature" && seen.length === 1);

  const A = await impFile(new URL("../packages/apikey/src/index.ts", import.meta.url));
  const key = A.generateApiKey({ prefix: "sk_" });
  ok("apikey 生成+ハッシュ照合", key.plaintext.startsWith("sk_") && A.verifyApiKey(key.plaintext, key.hash) === true && A.verifyApiKey("sk_wrong", key.hash) === false);
  ok("apikey スコープ(ワイルドカード)", A.hasScope(["orders:*"], "orders:write") === true && A.hasScope(["orders:read"], "users:read") === false);
  const store = { findByHash: (h) => h === key.hash ? { id: "1", hash: h, scopes: ["*"] } : null };
  const ok1 = await A.authenticateApiKey(key.plaintext, store);
  const exp = await A.authenticateApiKey("k", { findByHash: () => ({ id: "2", hash: "x", scopes: [], expiresAt: 1000 }) }, 2000);
  ok("apikey 認証(有効/期限切れ)", ok1.ok === true && exp.ok === false && exp.reason === "expired");

  const Z = await impFile(new URL("../packages/zengin/src/index.ts", import.meta.url));
  const r = Z.buildZenginTransfer(
    { code: "1234567890", name: "テスト", bankCode: "0001", branchCode: "001", accountType: "1", accountNumber: "1234567" },
    [{ bankCode: "0005", branchCode: "100", accountType: "1", accountNumber: "7654321", recipientName: "ヤマダタロウ", amount: 150000 },
     { bankCode: "0009", branchCode: "200", accountType: "2", accountNumber: "1111111", recipientName: "スズキハナコ", amount: 80000 }],
    "0725");
  const lines = r.content.split("\r\n");
  // **全レコードが 120 桁固定**(全国銀行協会の標準)。
  // 2026-08 まで ヘッダ 73 / データ 55 / トレーラ 19 / エンド 1 桁で、
  // **銀行が受け付けないファイル**だった
  ok("zengin レコード種別(1/2/8/9)と 120 桁固定",
     lines[0][0] === "1" && lines[1][0] === "2" && lines[3][0] === "8" && lines[4][0] === "9"
     && lines.every((l) => l.length === 120));
  // **データレコードは 120 桁固定**(全国銀行協会の標準)。
  // 2026-08 まで 55 桁しか出ておらず、**銀行が受け付けないファイル**になっていた
  ok("zengin 件数/合計 自動集計(データは 120 桁)", r.count === 2 && r.totalAmount === 230000 && lines[1].length === 120);
  ok("zengin 半角カナ変換", Z.toHankakuKana("ダ") === "ﾀﾞ");
}

// ---- utils 拡張: 関数 / オブジェクト / 配列 / 非同期 ----
section("utils: function / object / array / async");
{
  const F = await impFile(new URL("../packages/utils/src/function.ts", import.meta.url));
  const O = await impFile(new URL("../packages/utils/src/object.ts", import.meta.url));
  const A = await impFile(new URL("../packages/utils/src/array.ts", import.meta.url));
  const Y = await impFile(new URL("../packages/utils/src/async.ts", import.meta.url));
  // function
  let mc = 0; const m = F.memoize((x) => { mc++; return x * 2; });
  ok("utils memoize/once/pipe", m(5) === 10 && m(5) === 10 && mc === 1 && F.pipe((x) => x + 1, (x) => x * 2)(3) === 8);
  // object
  ok("utils pick/omit/deepClone/deepEqual", JSON.stringify(O.pick({ a: 1, b: 2 }, ["a"])) === JSON.stringify({ a: 1 }) &&
     O.deepEqual({ a: [1] }, { a: [1] }) === true &&
     O.deepMerge({ a: { x: 1 } }, { a: { y: 2 } }).a.x === 1);
  const cl = O.deepClone({ a: { b: [1] } }); cl.a.b.push(2);
  ok("utils deepClone は独立 + isEmpty", cl.a.b.length === 2 && O.isEmpty("") === true && O.isEmpty("x") === false);
  // array
  ok("utils sortBy/partition/keyBy", JSON.stringify(A.sortBy([{ n: 3 }, { n: 1 }], (x) => x.n).map((x) => x.n)) === JSON.stringify([1, 3]) && JSON.stringify(A.partition([1, 2, 3], (x) => x % 2 === 0)) === JSON.stringify([[2], [1, 3]]));
  ok("utils zip/range/difference", JSON.stringify(A.zip([1, 2], ["a", "b"])) === JSON.stringify([[1, "a"], [2, "b"]]) &&
     JSON.stringify(A.range(1, 5)) === JSON.stringify([1, 2, 3, 4]) &&
     JSON.stringify(A.difference([1, 2, 3], [2])) === JSON.stringify([1, 3]));
  // async
  let cur = 0, max = 0;
  const r = await Y.pMapLimit([1, 2, 3, 4, 5, 6], async (x) => { cur++; max = Math.max(max, cur); await new Promise((rs) => setTimeout(rs, 3)); cur--; return x * 2; }, 2);
  ok("utils pMapLimit 順序保持+並行制限", JSON.stringify(r) === JSON.stringify([2, 4, 6, 8, 10, 12]) && max <= 2);
  let to = false; try { await Y.pTimeout(new Promise((rs) => setTimeout(rs, 50)), 5); } catch (e) { to = e.name === "TimeoutError"; }
  ok("utils pTimeout(TimeoutError)", to === true);
}

// ---- LINE 連携拡充: メッセージビルダー / Webhook / 拡張クライアント ----
section("line: builders / webhook / client");
{
  const fs = await import("node:fs/promises");
  const { createHmac } = await import("node:crypto");
  const stamp = smokeStamp();
  // messages(index の型のみ依存 → LineMessage は type import なので shim 不要)
  const msgShim = `${TMP}/line-idx-${stamp}.ts`;
  await fs.writeFile(msgShim, "export interface LineMessage { type: string; [k: string]: unknown }");
  const msgSrc = (await fs.readFile(new URL("../packages/line/src/messages.ts", import.meta.url), "utf8")).replace('from "./index"', `from "${toSpec(msgShim)}"`);
  const msgF = `${TMP}/line-msg-${stamp}.ts`; await fs.writeFile(msgF, msgSrc);
  const M = await impFile(msgF);
  ok("LINE ビルダー(buttons/confirm/quickReply)", M.buttonsTemplate({ altText: "a", text: "t", actions: [M.postbackAction("承認", "d")] }).template.type === "buttons" &&
     M.withQuickReply(M.textMessage("x"), [M.messageAction("y", "y")]).quickReply.items.length === 1 &&
     M.confirmTemplate("a", "t", M.messageAction("y", "y"), M.messageAction("n", "n")).template.actions.length === 2);

  // **承認カード（2026-08 新設）。** 出先の人は PC を開けません——
  // 「承認待ちが溜まって業務が止まる」のは**承認者が席にいないだけ**のことが多く、
  // **スマホで押せれば数秒で終わります**。
  {
    const card = M.approvalFlexMessage({
      title: "経費申請", requester: "山田", amountText: "¥12,000",
      summary: "客先訪問の交通費", approveData: "approve:1", rejectData: "reject:1",
    });
    const json = JSON.stringify(card);
    // **通知に出る文字に金額を入れる**——開かなくても何の件か分かる
    ok("LINE: 通知の文字に申請者と金額が出る",
       card.altText.includes("山田") && card.altText.includes("¥12,000"));
    // **長い用途が切れないこと**——スマホは横幅が狭い
    ok("LINE: 長い文字が折り返される(wrap)", json.includes('"wrap":true'));
    // **押したときのデータが両方入っている**
    ok("LINE: 承認と差し戻しの両方が押せる",
       json.includes("approve:1") && json.includes("reject:1"));
  }

  // **リッチメニュー（2026-08 新設）。**
  // 定義は**座標を手で書く**必要があり、**1 つずらすと押せない領域**ができます
  // ——しかも**画面では気づけません**（見た目は正しく、押しても反応しないだけ）。
  // マス目で指定して、座標は計算に任せます。
  {
    const RM = await impFile(new URL("../packages/line/src/rich-menu.ts", import.meta.url));
    const menu = RM.buildRichMenu({
      name: "業務メニュー", size: "large", columns: 3, rows: 2,
      actions: [
        { kind: "text", text: "経費申請" },
        { kind: "postback", data: "open:approvals", displayText: "承認一覧を開きました" },
        { kind: "uri", uri: "https://example.com/help" },
        undefined,  // **空きマス**
        { kind: "text", text: "勤怠" },
        undefined,
      ],
    });
    // **空きマスは領域を作らない**——作ると「押せるのに何も起きない」
    // ボタンになり、**壊れていると思われます**
    ok(`LINE(リッチメニュー): 空きマスは領域を作らない(${menu.areas.length} 個)`,
       menu.areas.length === 4);
    // **最後の列・行は残り全部を使う**——割り切れないと
    // **右端と下端に隙間**ができ、そこだけ押せなくなる
    const right = menu.areas.find((a) => a.bounds.x > 1600);
    ok("LINE(リッチメニュー): 右端に隙間ができない",
       right !== undefined && right.bounds.x + right.bounds.width === 2500);
    // **`chatBarText` は 14 文字まで**（超えると LINE に弾かれる）
    let tooLong = false;
    try { RM.buildRichMenu({ name: "x", size: "compact", columns: 1, rows: 1,
      actions: [{ kind: "text", text: "a" }], chatBarText: "あ".repeat(15) }); }
    catch { tooLong = true; }
    ok("LINE(リッチメニュー): 長すぎる chatBarText は作る前に止める", tooLong);
  }

  // **メッセージ種別と操作の追加（2026-08）。**
  {
    // **動画はサムネイルが必須**——省略すると**再生前が真っ黒**になる
    const v = M.videoMessage("https://x.jp/a.mp4", "https://x.jp/a.jpg");
    ok("LINE: 動画にサムネイルが付く",
       v.type === "video" && v.previewImageUrl === "https://x.jp/a.jpg");

    // **音声は長さが要る**——渡さないと**再生バーが出ず、何秒あるか分からない**
    const a = M.audioMessage("https://x.jp/a.m4a", 12_000);
    ok("LINE: 音声に長さが付く", a.duration === 12_000);

    // **日時は選ばせる。** 文字で書かせると「来週の火曜」「3/5」「3月5日」が
    // ばらばらに届き、**受け取る側で解釈が要ります**
    const dp = M.datetimePickerAction("希望日", "d:1", { mode: "date", min: "2026-08-13" });
    ok("LINE: 日時選択に範囲を指定できる",
       dp.type === "datetimepicker" && dp.mode === "date" && dp.min === "2026-08-13");

    // **カメラはその場で撮らせる**——アルバムだと**関係ない写真を選ぶ事故**が起きる
    ok("LINE: カメラとアルバムを区別する",
       M.cameraAction("撮る").type === "camera"
       && M.cameraRollAction("選ぶ").type === "cameraRoll");
  }

  // **解析は `./webhook-parse` に分けた**(2026-08)。実体を直に読むと
  // 拡張子なしの相対 import が解決できないので、/tmp に写してから読む
  {
    const fsw = await import("node:fs/promises");
    const st = smokeStamp();
    const wpF = `${TMP}/line-wp-${st}.ts`;
    await fsw.writeFile(wpF,
      await fsw.readFile(new URL("../packages/line/src/webhook-parse.ts", import.meta.url), "utf8"));
    const whF = `${TMP}/line-wh-${st}.ts`;
    await fsw.writeFile(whF,
      (await fsw.readFile(new URL("../packages/line/src/webhook.ts", import.meta.url), "utf8"))
        .replace(/from "\.\/webhook-parse"/g, `from "${toSpec(wpF)}"`));
    var W = await impFile(whF);
  }
  const secret = "linesec";
  const body = JSON.stringify({ events: [{ type: "postback", timestamp: 1, source: { type: "user", userId: "U1" }, postback: { data: "action=approve&id=1" } }] });
  const sig = createHmac("sha256", secret).update(body).digest("base64");
  ok("LINE Webhook 署名検証(base64)", W.verifyLineSignature(body, sig, secret) === true && W.verifyLineSignature(body, sig, "wrong") === false);
  const events = W.parseLineWebhook(body);
  ok("LINE イベント/postback パース", events[0].type === "postback" && W.parsePostbackData(events[0].postback.data).action === "approve" && W.eventSourceId(events[0].source) === "U1");

  // 拡張クライアント(integrations shim)
  // **`@platform/core` は実物を写す。**
  // 2026-08 まで `Result` 型だけのスタブを置いていたが、
  // `line/index.ts` は `ok` / `err` / `AppError` / `ErrorCode` も**値として**使う。
  // スタブが足りないまま緑だったのは、**壊れたコード(`import type` だけ)に
  // 合わせてスタブを作っていた**ため——実装を直した瞬間に落ちた。
  //
  // **必要な名前を並べない。** 並べると、また実装が増えたときに落ちる。
  // **`@platform/core` は実物を再帰的に写す。**
  // 2026-08 まで `Result` 型だけのスタブだったが、`line/index.ts` は
  // `ok` / `err` / `AppError` / `ErrorCode` も**値として**使う。
  // 足りないまま緑だったのは、**壊れたコード(`import type` だけ)に
  // 合わせてスタブを作っていた**ため——実装を直した瞬間に落ちた。
  const coreF = await copyPackageDeep("core", fs.readFile, fs.writeFile, stamp);
  const intF = `${TMP}/line-int-${stamp}.ts`;
  await fs.writeFile(intF, "export function createApiClient(){ const c=[]; globalThis.__lc=c; const r=async(m,p,o)=>{ c.push({m,p,body:o?.body}); return {ok:true,value:{richMenuId:'rm1'}}; }; return { get:(p)=>r('GET',p), post:(p,o)=>r('POST',p,o), put:(p,o)=>r('PUT',p,o), delete:(p,o)=>r('DELETE',p,o), patch:(p,o)=>r('PATCH',p,o) }; }");
  const emptyF = `${TMP}/line-empty-${stamp}.ts`; await fs.writeFile(emptyF, "export {};");
  // **`recipient` は先に写す。** 下の書き換えで参照するので、順番が逆だと
  // 「初期化前に使った」で落ちる
  const rcpF = `${TMP}/line-rcp2-${stamp}.ts`;
  await fs.writeFile(rcpF, await fs.readFile(new URL("../packages/line/src/recipient.ts", import.meta.url), "utf8"));
  const idxSrc = (await fs.readFile(new URL("../packages/line/src/index.ts", import.meta.url), "utf8"))
    .replace('from "@platform/integrations"', `from "${toSpec(intF)}"`)
    .replace('from "@platform/core"', `from "${toSpec(coreF)}"`)
    .replace('from "./messages"', `from "${toSpec(emptyF)}"`)
    .replace('from "./rich-menu"', `from "${toSpec(emptyF)}"`)
    .replace('from "./webhook"', `from "${toSpec(emptyF)}"`)
    .replace('from "./balance"', `from "${toSpec(emptyF)}"`)
    .replace('from "./retention"', `from "${toSpec(emptyF)}"`)
    // **`./recipient` と `./types` に分けた**(2026-08)。
    // ここは宛先判定を使うので写して指し、型は落とす
    .replace('from "./recipient"', `from "${toSpec(rcpF)}"`)
    .replace(/import type \{ LineMessage \} from "\.\/types";\n?/g, "")
    .replace(/export type \{ LineMessage \};\n?/g, "")
    .replace(/\bLineMessage\b/g, "unknown");
  const idxF = `${TMP}/line-index-${stamp}.ts`; await fs.writeFile(idxF, idxSrc);
  const L = await impFile(idxF);
  const client = L.createLineClient({ channelAccessToken: "t" });
  await client.createRichMenu({ size: {} });
  await client.deleteRichMenu("rm1");
  await client.showLoadingAnimation("U1", 30);
  const calls = globalThis.__lc;
  ok("LINE 拡張クライアント(richmenu/loading)", calls.some((c) => c.p === "/richmenu" && c.m === "POST") &&
     calls.some((c) => c.m === "DELETE") &&
     calls.at(-1).p === "/chat/loading/start" &&
     calls.at(-1).body.loadingSeconds === 30);

  for (const f of [msgShim, msgF, coreF, intF, emptyF, idxF]) await fs.rm(f);
}

// ---- freee 連携拡充: トークン管理 / 証憑 / 振替伝票 ----
section("freee: token / receipts / journal");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  // token(依存なし・純ロジック)
  const T = await impFile(new URL("../packages/freee/src/token.ts", import.meta.url));
  let clock = 0, refreshCount = 0;
  const tf = async () => { refreshCount++; return { ok: true, status: 200, json: async () => ({ access_token: "at-" + refreshCount, refresh_token: "rt", expires_in: 21600 }) }; };
  const saved = [];
  const mgr = T.createFreeeTokenManager({ clientId: "c", clientSecret: "s", refreshToken: "r", fetchImpl: tf, now: () => clock, onRefresh: (r) => saved.push(r.accessToken) });
  const first = await mgr.getAccessToken();
  const cached = await mgr.getAccessToken();
  const countAfterCache = refreshCount; // キャッシュ中は更新されていないはず(=1)
  clock = 21600 * 1000;
  const refreshed = await mgr.getAccessToken();
  ok("freee トークン 更新/キャッシュ/再更新", first === "at-1" && cached === "at-1" && countAfterCache === 1 && refreshed === "at-2" && saved[0] === "at-1");
  let apiCalls = 0;
  const apiFetch = async () => { apiCalls++; return apiCalls === 1 ? { status: 401 } : { status: 200 }; };
  const mgr2 = T.createFreeeTokenManager({ clientId: "c", clientSecret: "s", refreshToken: "r", fetchImpl: tf, now: () => Date.now() });
  const authed = T.createFreeeAuthedFetch(mgr2, apiFetch);
  ok("freee authed fetch 401 で再試行", (await authed("https://api.freee.co.jp/x")).status === 200 && apiCalls === 2);

  // builders(buildManualJournal・純ロジック)
  const B = await impFile(new URL("../packages/freee/src/builders.ts", import.meta.url));
  const mj = B.buildManualJournal({ companyId: 1, issueDate: "2025-07-11", details: [
    { entrySide: "debit", accountItemId: 100, taxCode: 0, amount: 11000 },
    { entrySide: "credit", accountItemId: 200, taxCode: 0, amount: 11000 }] });
  let unbalanced = false;
  try { B.buildManualJournal({ companyId: 1, issueDate: "x", details: [{ entrySide: "debit", accountItemId: 1, taxCode: 0, amount: 1 }, { entrySide: "credit", accountItemId: 2, taxCode: 0, amount: 2 }] }); } catch { unbalanced = true; }
  ok("freee 振替伝票(借方=貸方検証)", mj.details.length === 2 && mj.details[0].entry_side === "debit" && unbalanced === true);

  // 拡張クライアント(証憑 multipart 等)を integrations shim で
  // **`AppError` / `err` も要る。** 2026-08 に `fetchAllPages` が
  // **上限に達したことを知らせる**ようにした(黙って打ち切ると
  // 「これで全部」と思われ、一部だけ取り込まれた状態になる)
  const coreF = `${TMP}/fr-core-${stamp}.ts`; await fs.writeFile(coreF,
    "export type Result<T> = { ok: true; value: T } | { ok: false; error: { message: string } };\n" +
    "export class AppError extends Error { constructor(code, message, opts) { super(message); this.code = code; this.details = opts?.details; } }\n" +
    "export const ErrorCode = { EXTERNAL: \"EXTERNAL\" };\n" +
    "export const err = (error) => ({ ok: false, error });");
  const intF = `${TMP}/fr-int-${stamp}.ts`;
  await fs.writeFile(intF, "export function createApiClient(){ const c=[]; globalThis.__fr=c; const r=async(m,p,o)=>{ c.push({m,p,query:o?.query,body:o?.body,multipart:o?.multipart}); return {ok:true,value:{id:1}}; }; return { get:(p,o)=>r('GET',p,o), post:(p,o)=>r('POST',p,o), put:(p,o)=>r('PUT',p,o), delete:(p,o)=>r('DELETE',p,o), patch:(p,o)=>r('PATCH',p,o) }; }");
  const emptyF = `${TMP}/fr-empty-${stamp}.ts`; await fs.writeFile(emptyF, "export {};");
  const idxSrc = (await fs.readFile(new URL("../packages/freee/src/index.ts", import.meta.url), "utf8"))
    .replace('from "@platform/integrations"', `from "${toSpec(intF)}"`)
    .replace(/from "@platform\/core"/g, `from "${toSpec(coreF)}"`)
    .replace('from "./token"', `from "${toSpec(emptyF)}"`)
    .replace('from "./builders"', `from "${toSpec(emptyF)}"`)
    .replace('from "./webhook"', `from "${toSpec(emptyF)}"`)
    .replace('from "./balance"', `from "${toSpec(emptyF)}"`)
    .replace('from "./retention"', `from "${toSpec(emptyF)}"`)
    .replace('from "./hr"', `from "${toSpec(emptyF)}"`);
  const idxF = `${TMP}/fr-index-${stamp}.ts`; await fs.writeFile(idxF, idxSrc);
  const F = await impFile(idxF);
  const client = F.createFreeeClient({ accessToken: "t" });
  await client.uploadReceipt(123, { filename: "r.jpg", data: new Uint8Array([1]), contentType: "image/jpeg" }, "タクシー代");
  await client.createManualJournal({ company_id: 123 });
  await client.createDealPayment(999, { amount: 1000 });
  const calls = globalThis.__fr;
  const up = calls.find((c) => c.p === "/receipts" && c.m === "POST");
  ok("freee 証憑multipart/振替伝票/支払", up.multipart.files[0].filename === "r.jpg" &&
     up.multipart.fields.company_id === 123 &&
     calls.some((c) => c.p === "/manual_journals") &&
     calls.some((c) => c.p === "/deals/999/payments"));

  for (const f of [coreF, intF, emptyF, idxF]) await fs.rm(f);
}

// ---- freee 拡充2: 人事労務 / 承認ワークフロー / Webhook ----
section("freee: HR / approval / webhook");
{
  const fs = await import("node:fs/promises");
  const { createHmac } = await import("node:crypto");
  const stamp = smokeStamp();
  const w = async (n, src) => { const f = `${TMP}/frx-${n}-${stamp}.ts`; await fs.writeFile(f, src); return f; };
  // **`AppError` / `err` を持たせる**(`fetchAllPages` が上限到達を知らせる)
  const coreF = await w("core",
    "export class AppError extends Error { constructor(code, message, opts) { super(message); this.code = code; this.details = opts?.details; } }\n" +
    "export const ErrorCode = { EXTERNAL: \"EXTERNAL\" };\n" +
    "export const err = (error) => ({ ok: false, error });");
  const intF = await w("int", "export function createApiClient(c){ const calls=[]; globalThis.__frx={baseUrl:c.baseUrl,calls}; const r=async(m,p,o)=>{ calls.push({m,p,query:o?.query,body:o?.body}); return {ok:true,value:{}}; }; return { get:(p,o)=>r('GET',p,o), post:(p,o)=>r('POST',p,o), put:(p,o)=>r('PUT',p,o), delete:(p,o)=>r('DELETE',p,o), patch:(p,o)=>r('PATCH',p,o) }; }");

  // HR クライアント
  const hrSrc = (await fs.readFile(new URL("../packages/freee/src/hr.ts", import.meta.url), "utf8"))
    .replace('from "@platform/integrations"', `from "${toSpec(intF)}"`)
    .replace('from "@platform/core"', `from "${toSpec(coreF)}"`);
  const hrF = await w("hr", hrSrc);
  const H = await impFile(hrF);
  const hr = H.createFreeeHrClient({ accessToken: "t" });
  await hr.getEmployees(5);
  const baseOk = globalThis.__frx.baseUrl === "https://api.freee.co.jp/hr/api/v1";
  await hr.putWorkRecord(10, { date: "2025-07-25", clockInAt: "2025-07-25T09:00:00", breakRecords: [{ clockInAt: "2025-07-25T12:00:00", clockOutAt: "2025-07-25T13:00:00" }] }, 5);
  const wr = globalThis.__frx.calls.at(-1);
  ok("freee 人事労務(base URL/勤怠 PUT/キー変換)", baseOk &&
     wr.m === "PUT" &&
     wr.p === "/employees/10/work_records/2025-07-25" &&
     wr.body.clock_in_at === "2025-07-25T09:00:00" &&
     wr.body.break_records[0].clock_in_at === "2025-07-25T12:00:00");
  await hr.getWorkRecordSummary(10, 2025, 7, 5);
  ok("freee 人事労務(月次集計/給与)", globalThis.__frx.calls.at(-1).p === "/employees/10/work_record_summaries/2025/7");

  // 承認ワークフロー(会計 index)
  const emptyF = await w("empty", "export {}");
  const idxSrc = (await fs.readFile(new URL("../packages/freee/src/index.ts", import.meta.url), "utf8"))
    .replace('from "@platform/integrations"', `from "${toSpec(intF)}"`)
    .replace(/from "@platform\/core"/g, `from "${toSpec(coreF)}"`)
    .replace('from "./token"', `from "${toSpec(emptyF)}"`)
    .replace('from "./builders"', `from "${toSpec(emptyF)}"`)
    .replace('from "./webhook"', `from "${toSpec(emptyF)}"`)
    .replace('from "./balance"', `from "${toSpec(emptyF)}"`)
    .replace('from "./retention"', `from "${toSpec(emptyF)}"`)
    .replace('from "./hr"', `from "${toSpec(emptyF)}"`);
  const idxF = await w("idx", idxSrc);
  const F = await impFile(idxF);
  const freee = F.createFreeeClient({ accessToken: "t" });
  await freee.actionExpenseApplication(123, 55, "approve", { comment: "OK" });
  const ea = globalThis.__frx.calls.at(-1);
  await freee.actionApprovalRequest(123, 77, "approve", { approvalStep: 2 });
  const ar = globalThis.__frx.calls.at(-1);
  ok("freee 承認ワークフロー(経費申請/承認依頼 actions)", ea.p === "/expense_applications/55/actions" && ea.body.action === "approve" && ar.p === "/approval_requests/77/actions" && ar.body.approval_step_id === 2);

  // Webhook 署名検証
  const W = await impFile(new URL("../packages/freee/src/webhook.ts", import.meta.url));
  const secret = "frwh";
  const body = JSON.stringify({ application_notifications: [{ type: "deal.created", company_id: 123 }] });
  const sig = createHmac("sha256", secret).update(body).digest("hex");
  ok("freee Webhook 署名検証/パース", W.verifyFreeeSignature(body, sig, secret) === true && W.verifyFreeeSignature(body, sig, "x") === false && W.parseFreeeWebhook(body)[0].type === "deal.created");

  for (const f of [coreF, intF, hrF, emptyF, idxF]) await fs.rm(f);
}

// ---- Google 連携拡充: ログイン/OAuth / Gmail / Drive / Calendar ----
section("google: oauth / gmail / drive / calendar");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  const w = async (n, src) => { const f = `${TMP}/gx-${n}-${stamp}.ts`; await fs.writeFile(f, src); return f; };
  const coreF = await w("core", "export {}");
  const intF = await w("int", "export function createApiClient(c){ const req=async(m,p,o)=>{ globalThis.__gx={method:m,path:p,query:o?.query,body:o?.body,multipart:o?.multipart,baseUrl:c.baseUrl}; return {ok:true,value:{id:'f1',name:'x'}}; }; return { get:(p,o)=>req('GET',p,o), post:(p,o)=>req('POST',p,o), put:(p,o)=>req('PUT',p,o), delete:(p,o)=>req('DELETE',p,o), patch:(p,o)=>req('PATCH',p,o) }; }");

  // OAuth(純ロジック + fake fetch)
  // **`./fetch` を解決できるよう拡張子を補う。** 2026-08 に
  // `googleFetch`(タイムアウト付き)を別ファイルへ切り出したため
  const gfs = await import("node:fs/promises");
  const gOauth = smokeTmp("g-oauth.ts");
  await gfs.writeFile(gOauth,
    (await gfs.readFile(new URL("../packages/google/src/oauth.ts", import.meta.url), "utf8"))
      .replace(/from "\.\/fetch"/g, `from "${toSpec(new URL("../packages/google/src/fetch.ts", import.meta.url).href)}"`));
  const O = await impFile(gOauth);
  const url = O.buildGoogleAuthUrl({ clientId: "cid", redirectUri: "https://app/cb", scopes: ["openid", "email"], state: "s", forceConsent: true });
  const authOk = new URL(url).searchParams.get("client_id") === "cid" && new URL(url).searchParams.get("access_type") === "offline" && new URL(url).searchParams.get("prompt") === "consent";
  let clock = 0, n = 0;
  const mgrFetch = async () => ({ ok: true, json: async () => ({ access_token: `at${++n}`, expires_in: 3600 }) });
  const mgr = O.createGoogleTokenManager({ clientId: "c", clientSecret: "s", refreshToken: "rt", fetchImpl: mgrFetch, now: () => clock });
  const t1 = await mgr.getAccessToken(); const t1b = await mgr.getAccessToken(); clock += 3600 * 1000; const t2 = await mgr.getAccessToken();
  ok("google OAuth(認可URL/トークン更新/キャッシュ)", authOk && t1 === "at1" && t1b === "at1" && t2 === "at2");
  const ui = await O.getGoogleUserInfo("at", async () => ({ ok: true, json: async () => ({ sub: "1", email: "a@x.com", hd: "example.co.jp" }) }));
  ok("google userinfo(email/hd 社内判定)", ui.email === "a@x.com" && ui.hd === "example.co.jp");

  // Gmail(raw 構築 + 送信)
  const gmSrc = (await fs.readFile(new URL("../packages/google/src/gmail.ts", import.meta.url), "utf8"))
    .replace('from "@platform/integrations"', `from "${toSpec(intF)}"`)
    .replace('from "@platform/core"', `from "${toSpec(coreF)}"`)
    // **`@platform/bytes` は依存ゼロ**なので、実体をそのまま指す
    // (2026-08 に gmail の base64 を寄せた)
    .replace('from "@platform/bytes"', `from "${toSpec(new URL("../packages/bytes/src/index.ts", import.meta.url).href)}"`);
  const G = await impFile(await w("gm", gmSrc));
  const raw = G.buildRawEmail({ to: "a@x.com", subject: "テスト", text: "本文", cc: ["b@x.com"] });
  const gmail = G.createGmailClient({ accessToken: "t" });
  await gmail.sendEmail({ to: "a@x.com", subject: "件名", text: "本文" });
  ok("gmail(MIME件名/base64url送信)", raw.includes("=?UTF-8?B?") && !raw.includes("テスト") && globalThis.__gx.path === "/messages/send" && !/[+/=]/.test(globalThis.__gx.body.raw));

  // Drive(multipart アップロード + 共有)
  const drSrc = (await fs.readFile(new URL("../packages/google/src/drive.ts", import.meta.url), "utf8"))
    .replace('from "@platform/integrations"', `from "${toSpec(intF)}"`)
    .replace('from "@platform/core"', `from "${toSpec(coreF)}"`);
  const D = await impFile(await w("dr", drSrc));
  const drive = D.createGoogleDriveClient({ accessToken: "t" });
  await drive.uploadFile({ name: "報告書.pdf", data: new Uint8Array([1]), mimeType: "application/pdf", parents: ["folder1"] });
  const up = globalThis.__gx;
  await drive.shareFile("f1", { role: "reader", type: "user", emailAddress: "a@x.com" });
  ok("drive(uploadホスト/multipart/共有)", up.baseUrl === "https://www.googleapis.com/upload/drive/v3" && up.multipart.files.length === 2 && globalThis.__gx.path === "/files/f1/permissions");

  // Calendar 拡張(index を integrations shim で)
  const emptyF = await w("empty", "export {}");
  const idxSrc = (await fs.readFile(new URL("../packages/google/src/index.ts", import.meta.url), "utf8"))
    .replace('from "@platform/integrations"', `from "${toSpec(intF)}"`)
    .replace('from "@platform/core"', `from "${toSpec(coreF)}"`)
    .replace('from "./oauth"', `from "${toSpec(emptyF)}"`)
    .replace('from "./gmail"', `from "${toSpec(emptyF)}"`)
    .replace('from "./drive"', `from "${toSpec(emptyF)}"`)
    .replace('from "./workspace"', `from "${toSpec(emptyF)}"`);
  const I = await impFile(await w("idx", idxSrc));
  const cal = I.createGoogleCalendarClient({ accessToken: "t" });
  await cal.createEvent("primary", { summary: "会議" }, { sendUpdates: "all" });
  const ce = globalThis.__gx;
  await cal.freeBusy({ timeMin: "a", timeMax: "b", calendarIds: ["primary", "room@x.com"] });
  ok("calendar(予定作成/freeBusy)", ce.method === "POST" &&
     ce.path === "/calendars/primary/events" &&
     ce.query.sendUpdates === "all" &&
     globalThis.__gx.path === "/freeBusy" &&
     globalThis.__gx.body.items.length === 2);

  // **Google Workspace（2026-08 新設）: Docs / Forms / Apps Script。**
  // 社内には**すでに Google で作られた資産**（議事録の雛形、申請フォーム、
  // スプレッドシートのマクロ）があります——**全部を作り直すのは現実的でない**ので、
  // **そのまま使えるようにする**方が早い。
  {
    // **依存を差し替えてから読む。** `@platform/integrations` と
    // `@platform/core` は bare import なので、そのままでは解決できません。
    const wsPath = smokeTmp("google-workspace.ts");
    await fs.writeFile(wsPath,
      (await fs.readFile(new URL("../packages/google/src/workspace.ts", import.meta.url), "utf8"))
        .replace(/from "@platform\/integrations"/g, `from "${toSpec(intF)}"`)
        .replace(/from "@platform\/core"/g, `from "${toSpec(coreF)}"`));
    const WS = await impFile(wsPath);

    // **Docs の差し込みは `{{ }}` で囲む決まり**にしてある。
    // 囲まないと「山田」という語が**本文中ですべて置き換わります**
    // ——「山田さんの件」が「山田太郎さんの件」になってしまう。
    const wsSrc = await fs.readFile(
      new URL("../packages/google/src/workspace.ts", import.meta.url), "utf8");
    ok("Google(Docs): 差し込みは {{ }} で囲む(本文の巻き込みを防ぐ)",
       wsSrc.includes("`{{${key}}}`"));


    // **Docs の中身は段落の入れ子**で返る——文字だけ欲しいときに使う
    const text = WS.extractDocText({
      body: { content: [
        { paragraph: { elements: [{ textRun: { content: "一行目\n" } }] } },
        { paragraph: { elements: [{ textRun: { content: "二行目\n" } }] } },
      ] },
    });
    ok("Google(Docs): 段落から文字だけ取り出せる", text === "一行目\n二行目");

    // **Forms の回答は質問 ID が鍵**で、そのままでは何の答えか分からない
    const rec = WS.formResponseToRecord(
      { items: [{ title: "氏名", questionItem: { question: { questionId: "q1" } } }] },
      { answers: { q1: { textAnswers: { answers: [{ value: "山田" }] } } } },
    );
    ok("Google(Forms): 質問 ID を人が読める名前に直す", rec["氏名"] === "山田");

    // **Apps Script はエラーを 200 で返す**——HTTP は成功でも、
    // 本文に `error` が入っていることがあります。
    // **`ok` だけ見て安心すると、失敗を成功として扱います**。
    ok("Google(AppsScript): 200 でも本文のエラーを見る",
       wsSrc.includes("const err0 = r.value.error;")
       && wsSrc.includes("が失敗しました"));
  }

  for (const f of [coreF, intF, emptyF]) await fs.rm(f);
}

// ---- status-page: メンテナンス/エラー画面 + 切替ゲート ----
section("status-page: templates / gate");
{
  const T = await impFile(new URL("../packages/status-page/src/templates.ts", import.meta.url));
  const m = T.renderMaintenancePage({ brand: "社内システム", estimatedRecovery: "22:00" });
  ok("メンテHTML(自己完結/noindex/文言)", m.startsWith("<!doctype html>") && m.includes("メンテナンス中") && m.includes("22:00") && m.includes("noindex") && !/src=|href="https?:/.test(m));
  const e = T.renderErrorPage({ referenceId: "trace-1" });
  ok("エラーHTML(参照ID)", e.includes("システムエラー") && e.includes("trace-1"));
  const x = T.renderStatusPage({ title: "<script>x</script>", message: "a & b < c" });
  ok("XSSエスケープ", x.includes("&lt;script&gt;") && x.includes("a &amp; b &lt; c") && !x.includes("<script>x"));

  const G = await impFile(new URL("../packages/status-page/src/gate.ts", import.meta.url));
  const now = () => new Date("2025-07-25T12:00:00Z");
  const on = G.createMaintenanceGate(() => ({ enabled: true, allowRoles: ["admin"], estimatedRecovery: "22:00" }), now);
  ok("ゲート: 一般はメンテ/管理者は素通し", on.evaluate({ path: "/x" }).active === true && on.evaluate({ path: "/x", roles: ["admin"] }).active === false && on.evaluate({ path: "/api/health" }).active === false);
  const win = G.createMaintenanceGate(() => ({ window: { start: "2025-07-25T11:00:00Z", end: "2025-07-25T13:00:00Z" } }), now);
  const winOut = G.createMaintenanceGate(() => ({ window: { start: "2025-07-25T20:00:00Z", end: "2025-07-25T22:00:00Z" } }), now);
  ok("ゲート: 予定期間で自動オン/オフ", win.evaluate({ path: "/x" }).active === true && winOut.evaluate({ path: "/x" }).active === false);

  // GUI/ストア連動(再起動なしの切り替え)
  const store = G.createMemoryMaintenanceStore();
  const agate = G.createAsyncMaintenanceGate(() => G.stateToConfig(store.get(), { allowRoles: ["admin"] }), now);
  const before = (await agate.evaluate({ path: "/x" })).active;
  store.set({ enabled: true, estimatedRecovery: "22:00" });
  const afterOn = await agate.evaluate({ path: "/x" });
  store.set({ enabled: false });
  const afterOff = (await agate.evaluate({ path: "/x" })).active;
  ok("ストアで再起動なし切替(OFF→ON→OFF)", before === false && afterOn.active === true && afterOn.estimatedRecovery === "22:00" && afterOff === false);
  let calls = 0; let clock = 0;
  const cached = G.createCachedConfig(() => { calls++; return { enabled: false }; }, 5000, () => clock);
  await cached(); await cached(); clock = 6000; await cached();
  ok("TTLキャッシュ(間引き/期限で再取得)", calls === 2);
}

// ---- session ログイン拡充: 無操作タイムアウト / idle timer / ログインスロットル ----
section("session: idle timeout / idle timer / login throttle");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  // 無操作セッション(crypto/cookie を可逆 shim に差し替え)
  const cryptoF = `${TMP}/sess-crypto-${stamp}.ts`;
  await fs.writeFile(cryptoF, "export function deriveKey(s){return s} export function encrypt(t){return Buffer.from(t,'utf8').toString('base64')} export function decrypt(x){return Buffer.from(x,'base64').toString('utf8')}");
  const cookieF = `${TMP}/sess-cookie-${stamp}.ts`;
  await fs.writeFile(cookieF, "export function getCookie(h,n){ if(!h) return undefined; for(const p of h.split(';')){ const [k,v]=p.trim().split('='); if(k===n) return v; } return undefined } export function serializeCookie(n,v,o){ return `${n}=${v}; Max-Age=${o?.maxAge??0}` } export function clearCookie(n){ return `${n}=; Max-Age=0` }");
  // session.ts は 0=無制限 の判定で AppError を投げるため core も要る
  const coreF = `${TMP}/sess-core-${stamp}.ts`;
  await fs.writeFile(coreF, "export class AppError extends Error{constructor(c,m,o){super(m);this.code=c;this.details=o?.details;}}\nexport const ErrorCode={CONFIG:'CONFIG'};\n");
  const sessSrc = (await fs.readFile(new URL("../packages/session/src/session.ts", import.meta.url), "utf8"))
    .replace('from "@platform/core"', `from "${toSpec(coreF)}"`)
    .replace('from "@platform/crypto"', `from "${toSpec(cryptoF)}"`)
    .replace('from "./cookie"', `from "${toSpec(cookieF)}"`);
  const sessF = `${TMP}/sess-session-${stamp}.ts`; await fs.writeFile(sessF, sessSrc);
  const S = await impFile(sessF);
  const idle = S.createSession({ secret: "y".repeat(32), salt: "smoke-salt-1", maxAgeSec: 3600, idleTimeoutSec: 0.05 });
  const ci = idle.write({ u: "1" });
  const cookieI = "session=" + ci.split("session=")[1].split(";")[0];
  const before = idle.read(cookieI)?.u;
  await new Promise((r) => setTimeout(r, 80));
  ok("session 無操作タイムアウト(既定オフ→設定でログアウト)", before === "1" && idle.read(cookieI) === null);
  const noIdle = S.createSession({ secret: "z".repeat(32), salt: "smoke-salt-2", maxAgeSec: 3600 });
  const cn = noIdle.write({ u: "2" });
  ok("session 既定は無操作でもOK", noIdle.read("session=" + cn.split("session=")[1].split(";")[0])?.u === "2");
  // **0 は無制限。** 以前は「経過時間 > 0」が常に成立し、
  // 「0 = 無制限」と案内しながら**設定した瞬間に全員が落ちる**状態だった
  const zero = S.createSession({ secret: "w".repeat(32), salt: "smoke-salt-3", maxAgeSec: 0, idleTimeoutSec: 0 });
  const cz = zero.write({ u: "3" });
  const cookieZ = "session=" + cz.split("session=")[1].split(";")[0];
  await new Promise((r) => setTimeout(r, 20));
  ok("session 0 は無制限(即ログアウトにしない)", zero.read(cookieZ)?.u === "3");
  ok("session 無制限でもクッキーには有限の寿命を入れる(不正な属性だと丸ごと捨てられる)",
    cz.includes(`Max-Age=${S.MAX_COOKIE_AGE_SEC}`));
  const zi = zero.inspect(cookieZ);
  ok("session inspect は発行時刻を返す(失効判定に要る)・無制限なら expiresAt は null",
    zi !== null && typeof zi.issuedAt === "number" && zi.expiresAt === null);
  let cfgErr = "";
  try { S.createSession({ secret: "v".repeat(32), salt: "smoke-salt-4", idleTimeoutSec: -1 }); }
  catch (e) { cfgErr = e.code; }
  ok("session 負の秒数は起動時に落とす(単位間違いを黙って無制限にしない)", cfgErr === "CONFIG");

  // idle timer(スケジューラ注入)
  const IT = await impFile(new URL("../packages/session/src/idle-timer.ts", import.meta.url));
  const jobs = new Map(); let jid = 0; let t = 0;
  const sched = { set: (fn, ms) => { const h = ++jid; jobs.set(h, { fn, at: t + ms }); return h; }, clear: (h) => jobs.delete(h) };
  const advance = (ms) => { t += ms; for (const [h, j] of [...jobs]) if (j.at <= t) { jobs.delete(h); j.fn(); } };
  let warned = false, loggedOut = false;
  const timer = IT.createIdleTimer({ timeoutMs: 1000, warnBeforeMs: 200, onWarn: () => (warned = true), onIdle: () => (loggedOut = true), scheduler: sched });
  timer.start(); advance(800); const w = warned; timer.activity(); advance(999); const stillIn = !loggedOut; advance(1);
  ok("idle timer(警告→活動リセット→ログアウト)", w === true && stillIn === true && loggedOut === true);

  // login throttle
  const LT = await impFile(new URL("../packages/session/src/login-throttle.ts", import.meta.url));
  let clock = 0; const now = () => clock;
  const th = LT.createLoginThrottle({ maxFails: 3, lockMs: 30000, store: LT.createMemoryThrottleStore(now), now });
  await th.recordFailure("a"); await th.recordFailure("a");
  const locked = await th.recordFailure("a");
  const stillLocked = (await th.check("a")).allowed;
  clock += 30001;
  const unlocked = (await th.check("a")).allowed;
  ok("login throttle(3回でロック→解除)", locked.allowed === false && stillLocked === false && unlocked === true);

  // store session: 再生成 + 全端末ログアウト(crypto/cookie shim)
  const stCrypto = `${TMP}/sess-stcrypto-${stamp}.ts`;
  await fs.writeFile(stCrypto, "let n=0; export function randomToken(){ return 'tok'+(++n) }");
  const stStoreSrc = (await fs.readFile(new URL("../packages/session/src/store-session.ts", import.meta.url), "utf8"))
    .replace('from "@platform/crypto"', `from "${toSpec(stCrypto)}"`)
    .replace('from "./cookie"', `from "${toSpec(cookieF)}"`);
  const stStoreF = `${TMP}/sess-store-${stamp}.ts`; await fs.writeFile(stStoreF, stStoreSrc);
  const SS = await impFile(stStoreF);
  const map = new Map();
  const memStore = { get: async (k) => map.get(k) ?? null, set: async (k, v) => { map.set(k, v); }, delete: async (k) => { map.delete(k); } };
  const svr = SS.createServerSession({ store: memStore });
  const sa = await svr.create({ name: "t" }, { userId: "u1" });
  const cookieSA = "sid=" + sa.setCookie.split("sid=")[1].split(";")[0];
  const re = await svr.regenerate(cookieSA);
  const oldGone = (await svr.read(cookieSA)) === null;
  await svr.create({ name: "t" }, { userId: "u1" });
  const revoked = await svr.destroyAllForUser("u1");
  ok("store session(再生成→旧失効 / 全端末ログアウト)", re && re.id !== sa.id && oldGone && revoked >= 2 && (await svr.listUserSessions("u1")).length === 0);

  // step-up 再認証 + Remember-me + 監査
  const SU = await impFile(new URL("../packages/session/src/step-up.ts", import.meta.url));
  let clk = 0; const step = SU.createStepUp({ freshnessSec: 300, now: () => clk });
  const atv = step.stamp(); const freshOk = step.required(atv) === false; clk = 301000; const staleOk = step.required(atv) === true;
  const remOk = SU.sessionMaxAge(false, { defaultMaxAgeSec: 3600, rememberMaxAgeSec: 999 }) === 3600 && SU.sessionMaxAge(true, { defaultMaxAgeSec: 3600, rememberMaxAgeSec: 999 }) === 999;
  ok("step-up 再認証 + Remember-me", freshOk && staleOk && remOk);
  const LA = await impFile(new URL("../packages/session/src/login-audit.ts", import.meta.url));
  const evs = [];
  const audit = LA.createLoginAudit({ record: (e) => evs.push(e) }, { now: () => new Date("2025-07-25T12:00:00Z") });
  await audit.loginSuccess({ subject: "a@x.com", ip: "10.0.0.1" });
  await audit.allSessionsRevoked({ subject: "a@x.com" });
  ok("ログイン監査(標準スキーマ)", evs[0].event === "login_success" && evs[0].at === "2025-07-25T12:00:00.000Z" && evs[1].event === "all_sessions_revoked");

  await fs.rm(stCrypto); await fs.rm(stStoreF);

  for (const f of [cryptoF, cookieF, sessF]) await fs.rm(f);
}

// ---- 本人確認書類の検証 + マイナンバー/書類番号マスキング(KYC 部品) ----
section("identity: document validation / masking");
{
  const I = await impFile(new URL("../packages/validation/src/identity.ts", import.meta.url));
  ok("本人確認書類の書式検証(免許/旅券/在留)", I.isValidDriversLicenseNumber("123456789012") &&
     I.isValidJapanPassportNumber("TK1234567") &&
     I.isValidResidenceCardNumber("AB12345678CD") &&
     !I.isValidDriversLicenseNumber("12345678901"));
  ok("書類番号の正規化(全角/ハイフン)", I.normalizeDocumentNumber("ＴＫ－１２３４５６７") === "TK1234567" && I.validateIdentityDocument("passport", "TK1234567"));
  const M = await impFile(new URL("../packages/pii/src/identity-mask.ts", import.meta.url));
  ok("マイナンバーは既定 全桁マスク(番号法)", M.maskMyNumber("123456789018") === "************" && M.maskMyNumber("123456789018", 4) === "********9018");
  ok("本人確認番号の末尾マスク", M.maskIdentityNumber("AB12345678CD") === "********78CD");
  // **短い入力も伏せる。** `maskEmail` / `maskPhone` は 2026-08 まで
  // **そのまま返して**おり、マスクする関数が何も隠さない状態だった。
  // 身元に関わる番号は同じ形の欠陥を作らないよう、ここでも確かめる
  ok("身元の番号: 短い入力も伏せる",
     M.maskMyNumber("123") === "***" && M.maskIdentityNumber("123") === "***");
}

// ---- ekyc: eKYC ベンダー連携(ステータス正規化 / Webhook / クライアント) ----
section("ekyc: status / webhook / client");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  const S = await impFile(new URL("../packages/ekyc/src/status.ts", import.meta.url));
  ok("ekyc ステータス正規化", S.normalizeEkycStatus("Approved") === "approved" &&
     S.normalizeEkycStatus("NG") === "rejected" &&
     S.normalizeEkycStatus("reviewing") === "in_review" &&
     S.normalizeEkycStatus("x") === "unknown");
  ok("ekyc 確定/承認判定", S.isEkycFinal("approved") && !S.isEkycFinal("in_review") && S.isEkycApproved("approved"));

  // webhook(status.ts を .ts 参照に差し替えて読み込み)
  const whSrc = (await fs.readFile(new URL("../packages/ekyc/src/webhook.ts", import.meta.url), "utf8"))
    .replace('from "./status"', `from ${JSON.stringify(new URL("../packages/ekyc/src/status.ts", import.meta.url).href)}`)
    .replace('from "./webhook-parse"', `from ${JSON.stringify(toSpec(`${TMP}/ekyc-wp-${stamp}.ts`))}`);
  // **webhook-parse も /tmp に写す。** 実体を直に指すと、その中の
  // `./status` が拡張子なしで解決できない(2026-08、解析を分けた際)
  await fs.writeFile(`${TMP}/ekyc-wp-${stamp}.ts`,
    (await fs.readFile(new URL("../packages/ekyc/src/webhook-parse.ts", import.meta.url), "utf8"))
      .replace('from "./status"', `from ${JSON.stringify(new URL("../packages/ekyc/src/status.ts", import.meta.url).href)}`));
  const whF = `${TMP}/ekyc-wh-${stamp}.ts`; await fs.writeFile(whF, whSrc);
  const W = await impFile(whF);
  const { createHmac } = await import("node:crypto");
  const body = JSON.stringify({ application_id: "a1", status: "approved" });
  const sig = createHmac("sha256", "sec").update(body).digest("hex");
  ok("ekyc Webhook 署名検証", W.verifyEkycSignature(body, sig, "sec") === true && W.verifyEkycSignature(body + "x", sig, "sec") === false);
  const ev = W.parseEkycWebhook(JSON.stringify({ id: "v1", result: "NG", reason: "mismatch" }));
  ok("ekyc Webhook パース+正規化", ev.applicationId === "v1" && ev.status === "rejected" && ev.reason === "mismatch");

  // client(integrations を fake に差し替え)
  const intF = `${TMP}/ekyc-int-${stamp}.ts`;
  await fs.writeFile(intF, "export function createApiClient(config){ const calls=[]; globalThis.__ekyc=calls; const r=(m)=>(p,o)=>{ calls.push({m,p,h:config.headers,b:config.baseUrl}); return Promise.resolve({ok:true,value:{}}); }; return { get:r('GET'), post:r('POST'), put:r('PUT'), patch:r('PATCH'), delete:r('DELETE') }; }");
  const coreF = `${TMP}/ekyc-core-${stamp}.ts`; await fs.writeFile(coreF, "export {};");
  const clSrc = (await fs.readFile(new URL("../packages/ekyc/src/client.ts", import.meta.url), "utf8"))
    // **JSON.stringify に生パスを渡さない。** Windows の絶対パスがそのまま
    // 埋め込まれ、読み込んだ時点で `c:` プロトコルとして解釈されて落ちる
    .replace('from "@platform/integrations"', `from ${JSON.stringify(toSpec(intF))}`)
    .replace('from "@platform/core"', `from ${JSON.stringify(toSpec(coreF))}`);
  const clF = `${TMP}/ekyc-cl-${stamp}.ts`; await fs.writeFile(clF, clSrc);
  const C = await impFile(clF);
  const client = C.createEkycClient({ apiKey: "k", baseUrl: "https://api.example.com/v1" });
  await client.createApplication({ name: "t" });
  await client.getApplication("app_1");
  const calls = globalThis.__ekyc;
  ok("ekyc クライアント(POST作成 / :id置換 / 認証ヘッダ)", calls[0].m === "POST" && calls[0].p === "/applications" && calls[0].h["X-Api-Key"] === "k" && calls[1].p === "/applications/app_1");
  const td = C.createTrustdockClient({ apiKey: "tk", environment: "sandbox" });
  await td.getApplication("v1");
  const tdCall = globalThis.__ekyc[globalThis.__ekyc.length - 1];
  ok("ekyc TRUSTDOCK プリセット", tdCall.b.includes("sandbox") && tdCall.h["X-Api-Key"] === "tk");

  for (const f of [whF, intF, coreF, clF]) await fs.rm(f);
}

// ---- ekyc: eKYC ベンダー連携(TRUSTDOCK)----
section("ekyc: client / webhook / status");
{
  const fs = await import("node:fs/promises");
  const cr = await import("node:crypto");
  const stamp2 = smokeStamp();
  // status(依存ゼロ)
  const ST = await impFile(new URL("../packages/ekyc/src/status.ts", import.meta.url));
  ok("ekyc status 正規化", ST.normalizeEkycStatus("Approved") === "approved" &&
     ST.normalizeEkycStatus("NG") === "rejected" &&
     ST.normalizeEkycStatus("x") === "unknown" &&
     ST.isEkycFinal("approved") === true);
  // client(integrations を core shim 経由で読み込み)
  const coreF = `${TMP}/ekyc-core-${stamp2}.ts`;
  await fs.writeFile(coreF, `export const ErrorCode={EXTERNAL:"EXTERNAL",INTERNAL:"INTERNAL"};export class AppError extends Error{constructor(c,m,d){super(m);this.code=c;this.details=d;}}export async function tryCatch(fn){try{return {ok:true,value:await fn()};}catch(e){return {ok:false,error:e instanceof AppError?e:new AppError("INTERNAL",String(e))};}}`);
  const intSrc = (await fs.readFile(new URL("../packages/integrations/src/index.ts", import.meta.url), "utf8")).replace('from "@platform/core"', `from "${toSpec(coreF)}"`);
  const intF = `${TMP}/ekyc-int-${stamp2}.ts`; await fs.writeFile(intF, intSrc);
  const clientSrc = (await fs.readFile(new URL("../packages/ekyc/src/client.ts", import.meta.url), "utf8"))
    .replace('from "@platform/integrations"', `from "${toSpec(intF)}"`)
    .replace('from "@platform/core"', `from "${toSpec(coreF)}"`);
  const clientF = `${TMP}/ekyc-client-${stamp2}.ts`; await fs.writeFile(clientF, clientSrc);
  const C = await impFile(clientF);
  const calls = [];
  const fakeFetch = async (url, init = {}) => { calls.push({ url: String(url), method: init.method, headers: init.headers }); return new Response(JSON.stringify({ id: "app_1", status: "in_review" }), { status: 200, headers: { "content-type": "application/json" } }); };
  const kyc = C.createEkycClient({ apiKey: "k", baseUrl: "https://ex.test/v2", fetchImpl: fakeFetch });
  const cr1 = await kyc.createApplication({ document_type: "passport" });
  await kyc.getApplication("app_1");
  ok("ekyc client(POST作成 + X-Api-Key + :id置換)", cr1.ok && calls[0].method === "POST" && calls[0].headers["X-Api-Key"] === "k" && calls[1].url.endsWith("/applications/app_1"));
  const td = C.createTrustdockClient({ apiKey: "k", environment: "sandbox", fetchImpl: fakeFetch });
  await td.getApplication("x");
  ok("ekyc TRUSTDOCK プリセット baseUrl", calls[2].url.includes("sandbox.api.trustdock.io"));
  // webhook(status.ts を .ts 参照に)
  // **webhook-parse も /tmp に写す**(解析を分けたため。2026-08)
  const wpF2 = `${TMP}/ekyc-wp-${stamp2}.ts`;
  await fs.writeFile(wpF2,
    (await fs.readFile(new URL("../packages/ekyc/src/webhook-parse.ts", import.meta.url), "utf8"))
      .replace('from "./status"', `from ${JSON.stringify(new URL("../packages/ekyc/src/status.ts", import.meta.url).href)}`));
  const whSrc = (await fs.readFile(new URL("../packages/ekyc/src/webhook.ts", import.meta.url), "utf8"))
    .replace('from "./status"', `from ${JSON.stringify(new URL("../packages/ekyc/src/status.ts", import.meta.url).href)}`)
    .replace('from "./webhook-parse"', `from ${JSON.stringify(toSpec(wpF2))}`);
  const whF = `${TMP}/ekyc-wh-${stamp2}.ts`; await fs.writeFile(whF, whSrc);
  const W = await impFile(whF);
  const secret = "whsec"; const body = JSON.stringify({ application_id: "app_9", status: "approved" });
  const sig = cr.createHmac("sha256", secret).update(body).digest("hex");
  const ev = W.parseEkycWebhook(body);
  ok("ekyc webhook(署名検証 + パース正規化)", W.verifyEkycSignature(body, sig, secret) === true &&
     W.verifyEkycSignature(body + "x", sig, secret) === false &&
     ev.applicationId === "app_9" &&
     ev.status === "approved");
  for (const f of [coreF, intF, clientF, whF]) await fs.rm(f);
}

// ---- ui: tree / kanban 純ロジック(ダッシュボード部品)----
section("ui: tree / kanban logic");
{
  const T = await impFile(new URL("../packages/ui/src/lib/tree.ts", import.meta.url));
  const K = await impFile(new URL("../packages/ui/src/lib/kanban.ts", import.meta.url));
  const nodes = [{ id: "a", children: [{ id: "a1" }, { id: "a2", children: [{ id: "a2x" }] }] }, { id: "b" }];
  ok("tree collectAllIds / findNode / pathToNode", T.collectAllIds(nodes).length === 5 && T.findNode(nodes, "a2x").id === "a2x" && T.pathToNode(nodes, "a2x").join(">") === "a>a2>a2x");
  ok("tree toggleExpanded(不変)", T.toggleExpanded(new Set(["a"]), "a").has("a") === false && T.toggleExpanded(new Set(), "a").has("a") === true);
  const cols = [{ id: "todo", cards: [{ id: "c1" }, { id: "c2" }] }, { id: "doing", cards: [{ id: "c3" }] }];
  const m = K.moveCard(cols, "c1", "doing");
  const mAt = K.moveCard(cols, "c3", "todo", 1);
  ok("kanban moveCard(移動/位置指定/不変)", m[1].cards.map((c) => c.id).join(",") === "c3,c1" && mAt[0].cards.map((c) => c.id).join(",") === "c1,c3,c2" && cols[0].cards.length === 2);
  ok("kanban countByColumn / 不明カードは不変", K.countByColumn(cols).todo === 2 && K.moveCard(cols, "zzz", "todo") === cols);
}

// ---- ui: schedule カレンダー配置ロジック ----
section("ui: schedule layout");
{
  const S = await impFile(new URL("../packages/ui/src/lib/schedule.ts", import.meta.url));
  const ev = (id, s, e, x = {}) => ({ id, start: new Date(s), end: new Date(e), title: id, ...x });
  const day = new Date(2025, 6, 25);
  const forDay = S.eventsForDay([ev("b", "2025-07-25T10:00", "2025-07-25T11:00"), ev("ad", "2025-07-25T00:00", "2025-07-26T00:00", { allDay: true }), ev("a", "2025-07-25T09:00", "2025-07-25T10:00")], day).map((e) => e.id);
  ok("schedule eventsForDay(終日優先・時刻順)", forDay.join(",") === "ad,a,b");
  const ov = S.layoutDayEvents([ev("a", "2025-07-25T09:00", "2025-07-25T12:00"), ev("b", "2025-07-25T09:30", "2025-07-25T10:30"), ev("c", "2025-07-25T10:00", "2025-07-25T11:00")], day);
  ok("schedule layoutDayEvents(3件重なり→3列)", ov.every((p) => p.columns === 3) && new Set(ov.map((p) => p.column)).size === 3);
  const span = S.layoutDayEvents([ev("s", "2025-07-24T22:00", "2025-07-25T02:00")], day);
  ok("schedule 跨ぎクランプ(top=0, 2h)", span[0].top === 0 && Math.abs(span[0].height - 2 / 24) < 1e-9);
  const grid = S.buildMonthGrid(new Date(2025, 6, 15), { weekStartsOn: 0, today: new Date(2025, 6, 25) });
  ok("schedule buildMonthGrid(週7日・7/1火曜・today)", grid.every((w) => w.length === 7) &&
     grid[0][2].date.getDate() === 1 &&
     grid.flat().find((c) => c.date.getDate() === 25 && c.inMonth).isToday === true);
  ok("schedule groupEventsByDay(跨ぎ3日) / formatEventTime", S.groupEventsByDay([ev("m", "2025-07-24T10:00", "2025-07-26T10:00")]).length === 3 && S.formatEventTime(ev("a", "2025-07-25T09:05", "2025-07-25T10:30")) === "09:05–10:30");
  // 空き/使用時間の計算
  const win0 = new Date("2025-07-25T09:00"), win1 = new Date("2025-07-25T18:00");
  const busyEvents = [ev("a", "2025-07-25T10:00", "2025-07-25T11:00"), ev("b", "2025-07-25T13:00", "2025-07-25T14:00"), ev("c", "2025-07-25T08:00", "2025-07-25T09:30")];
  const free = S.computeFreeSlots(busyEvents, win0, win1);
  ok("schedule computeFreeSlots(隙間3つ)", free.length === 3 && free[0].start.getMinutes() === 30 && free[2].end.getHours() === 18);
  const slots = S.findAvailableSlots(busyEvents, win0, win1, 60, { stepMin: 30 });
  ok("schedule findAvailableSlots(60分/30分刻み=10枠)", slots.length === 10 && S.totalBusyMinutes(busyEvents, win0, win1) === 150);
  ok("schedule mergeIntervals(重なり+隣接=1)", S.mergeIntervals([{ start: new Date("2025-07-25T10:00"), end: new Date("2025-07-25T11:00") }, { start: new Date("2025-07-25T11:00"), end: new Date("2025-07-25T12:00") }]).length === 1);
  // リソース横並び
  const resEvents = [ev("a", "2025-07-25T10:00", "2025-07-25T11:00", { resourceId: "roomA" }), ev("b", "2025-07-25T10:30", "2025-07-25T11:30", { resourceId: "roomA" }), ev("c", "2025-07-25T13:00", "2025-07-25T14:00", { resourceId: "roomB" }), ev("none", "2025-07-25T09:00", "2025-07-25T10:00")];
  const resources = [{ id: "roomA", label: "A" }, { id: "roomB", label: "B" }, { id: "roomC", label: "C" }];
  ok("schedule eventsForResource(resourceId 一致のみ)", S.eventsForResource(resEvents, "roomA").map((e) => e.id).join(",") === "a,b");
  const rl = S.layoutResourceDay(resEvents, resources, day);
  ok("schedule layoutResourceDay(A=重なり2列/C=空)", rl.length === 3 && rl[0].positioned.every((p) => p.columns === 2) && rl[2].positioned.length === 0);
}

// ---- workflow: 条件別ルート / 代理承認 / 並列承認 ----
section("workflow: routing / delegation / parallel");
{
  const R = await impFile(new URL("../packages/workflow/src/routing.ts", import.meta.url));
  const D = await impFile(new URL("../packages/workflow/src/delegation.ts", import.meta.url));
  const P = await impFile(new URL("../packages/workflow/src/parallel.ts", import.meta.url));
  const mgr = { name: "課長", approverRole: "manager" }, dir = { name: "部長", approverRole: "director" }, exe = { name: "役員", approverRole: "executive" };
  const tiers = [{ under: 100000, steps: [mgr] }, { under: 1000000, steps: [mgr, dir] }, { steps: [mgr, dir, exe] }];
  ok("workflow routeByAmount(5万→1段/50万→2段/境界10万→2段)", R.routeByAmount(50000, tiers).steps.length === 1 &&
     R.routeByAmount(500000, tiers).steps.length === 2 &&
     R.routeByAmount(100000, tiers).steps.length === 2);
  ok("workflow resolveRoute(条件一致/デフォルト)", R.resolveRoute([{ when: (c) => c.dept === "sales", steps: [mgr, dir] }, { steps: [mgr] }], { dept: "sales" }).steps.length === 2);

  const now = new Date("2025-07-25T12:00:00Z");
  const dels = [{ from: "bucho", to: "kacho", roles: ["director"], since: new Date("2025-07-20"), until: new Date("2025-07-30") }];
  const auth = D.resolveApprovalAuthority({ name: "部長", approverRole: "director" }, { id: "kacho", roles: ["manager"] }, dels, { now });
  ok("workflow 代理承認(委任で可+onBehalfOf/期間外は無効)", auth.canApprove === true && auth.onBehalfOf === "bucho" && D.activeDelegations(dels, new Date("2025-08-01")).length === 0);

  const pstep = { name: "合議", approverRoles: ["legal", "finance", "hr"], mode: "all" };
  let ps = P.recordParallelApproval(pstep, P.startParallel(), { id: "u1", roles: ["legal"] });
  const midIncomplete = !P.isParallelComplete(pstep, ps);
  // **1 人 1 票。** 兼務者(finance と hr の両方を持つ)でも 1 つ分しか埋まらない
  // ——「全部署の承認が要る」を 1 人で満たせては二重チェックにならない(2026-08)
  ps = P.recordParallelApproval(pstep, ps, { id: "u2", roles: ["finance", "hr"] });
  const stillIncomplete = !P.isParallelComplete(pstep, ps);
  ps = P.recordParallelApproval(pstep, ps, { id: "u3", roles: ["hr"] });
  ok("workflow 並列承認(all は全員で完了/兼務者も 1 票/any は1人)", midIncomplete && stillIncomplete &&
     P.isParallelComplete(pstep, ps) &&
     P.isParallelComplete({ name: "x", approverRoles: ["a", "b"], mode: "any" }, P.recordParallelApproval({ name: "x", approverRoles: ["a", "b"], mode: "any" }, P.startParallel(), { id: "z", roles: ["a"] })));

  const ES = await impFile(new URL("../packages/workflow/src/escalation.ts", import.meta.url));
  const pend = (h = []) => ({ status: "pending", currentStep: 0, history: h });
  const st = new Date("2025-07-25T09:00:00Z");
  const pol = { remindAfterMin: 60, reminderIntervalMin: 60, escalateAfterMin: 240 };
  ok("workflow SLA(30分none/90分remind/300分escalate/重複抑止)", ES.evaluateSla(st, new Date("2025-07-25T09:30:00Z"), pol).action === "none" &&
     ES.evaluateSla(st, new Date("2025-07-25T10:30:00Z"), pol).action === "remind" &&
     ES.evaluateSla(st, new Date("2025-07-25T14:00:00Z"), pol).action === "escalate" &&
     ES.evaluateSla(st, new Date("2025-07-25T10:30:00Z"), pol, { remindersSent: 1 }).action === "none");
  const defE = { steps: [{ name: "課長", approverRole: "manager" }, { name: "部長", approverRole: "director" }] };
  const stalled = ES.findStalledApprovals([{ id: "a", state: pend(), startedAt: st }, { id: "d", state: pend(), startedAt: new Date("2025-07-25T05:00:00Z") }], new Date("2025-07-25T10:30:00Z"), pol);
  ok("workflow findStalled + escalationTarget(次段)", stalled.length === 2 && ES.escalationTarget(defE, pend()).approverRole === "director");
}

// ---- tax 源泉徴収 + report 帳票種別(見積/納品/源泉) ----
section("withholding / business documents");
{
  const W = await impFile(new URL("../packages/tax/src/withholding.ts", import.meta.url));
  ok("源泉徴収(10万→10210 / 100万→102100 / 200万→306300)", W.withholdingTax(100000) === 10210 && W.withholdingTax(1000000) === 102100 && W.withholdingTax(2000000) === 306300);
  ok("源泉徴収 切り捨て + applyWithholding(差引)", W.withholdingTax(105000) === 10720 && W.applyWithholding(500000).net === 448950);
  // render は ./invoice.js / ./money.js を import → fs read + .js→.ts shim で読み込む
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  const files = {};
  for (const f of ["render", "invoice", "money"]) {
    const src = (await fs.readFile(new URL(`../packages/report/src/${f}.ts`, import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
    files[f] = `${TMP}/rep-${f}-${stamp}.ts`;
    await fs.writeFile(files[f], src.replace(/from "\.\/(invoice|money)\.ts"/g, (m, n) => `from \"${toSpec(`${TMP}/rep-${n}-${stamp}.ts`)}\"`));
  }
  const R = await impFile(files.render);
  const doc = { invoiceNumber: "INV-001", issueDate: "2025-07-25", dueDate: "2025-08-31", seller: { name: "自社" }, buyer: { name: "取引先" }, lines: [{ description: "制作", quantity: 1, unitPrice: 500000, taxRate: 10 }] };
  const withWH = R.renderInvoiceHtml({ ...doc, withholding: 51050 });
  ok("請求書に源泉徴収+差引お支払額(¥498,950)", withWH.includes("源泉徴収税") && withWH.includes("差引お支払額") && withWH.includes("¥498,950"));
  ok("見積書ラベル / 納品書ラベル", R.renderQuotationHtml(doc).includes("見積書") && R.renderQuotationHtml(doc).includes("見積番号") && R.renderDeliveryNoteHtml(doc).includes("納品書"));
  for (const f of Object.values(files)) await fs.rm(f);
}

// ---- notify: 通知プレファレンス(チャネル選択・静音時間・ダイジェスト) ----
section("notify: preferences");
{
  const P = await impFile(new URL("../packages/notify/src/preferences.ts", import.meta.url));
  // **JST の h 時を表す Date を作る。** 静音時間の判定は JST 基準なので、
  // `setHours`(ローカル時刻)で作ると CI(UTC)と JST 機で結果が変わる(2026-08)
  const at = (h) => new Date(Date.UTC(2025, 6, 25, h - 9));
  const pref = { categories: { approval: { channels: ["slack", "email"], mode: "immediate" }, report: { channels: ["email"], mode: "digest" }, marketing: { channels: ["email"], mode: "off" }, mention: { channels: ["push"] } }, defaultChannels: ["inApp"], quietHours: { start: 22, end: 7 } };
  ok("静音時間 日またぎ(23時内/12時外/5時内)", P.isQuietHour({ start: 22, end: 7 }, at(23)) === true &&
     P.isQuietHour({ start: 22, end: 7 }, at(12)) === false &&
     P.isQuietHour({ start: 22, end: 7 }, at(5)) === true);
  ok("配信解決(即時/digest/off/静音/緊急)", P.resolveDelivery(pref, { category: "approval" }, at(12)).reason === "immediate" &&
     P.resolveDelivery(pref, { category: "report" }, at(12)).deferred === true &&
     P.resolveDelivery(pref, { category: "marketing" }, at(12)).reason === "off" &&
     P.resolveDelivery(pref, { category: "mention" }, at(23)).reason === "quiet_hours" &&
     P.resolveDelivery(pref, { category: "mention", urgent: true }, at(23)).reason === "urgent");
  const part = P.partitionDeliveries(pref, [{ category: "approval" }, { category: "report" }, { category: "marketing" }, { category: "mention" }], at(12));
  ok("一括振り分け(即時2/後回し1/抑制1) + digest集計", part.immediate.length === 2 &&
     part.deferred.length === 1 &&
     part.suppressed.length === 1 &&
     P.summarizeDigest([{ event: { category: "report" }, decision: {} }, { event: { category: "report" }, decision: {} }])[0].count === 2);
}

// ---- mail: テンプレートメール + 宛先ホワイトリスト ----
section("mail: template / allowlist");
{
  const fs = await import("node:fs/promises");
  const stamp = smokeStamp();
  // **`MailMessage` の項目がすべて SMTP へ渡っているか。**
  // 型に足しても送信側で渡さなければ**黙って落ちる**——2026-08 に
  // `attachments`(添付漏れ)と `headers`(List-Unsubscribe 欠落で迷惑メール扱い)
  // が落ちていた。型と送信の食い違いは**送ってみるまで分からない**
  {
    const fsq = await import("node:fs/promises");
    const [idxSrc, smtpSrc] = await Promise.all([
      fsq.readFile(new URL("../packages/mail/src/index.ts", import.meta.url), "utf8"),
      fsq.readFile(new URL("../packages/mail/src/transports/smtp.ts", import.meta.url), "utf8"),
    ]);
    const i = idxSrc.indexOf("export interface MailMessage");
    const body = idxSrc.slice(i, idxSrc.indexOf("\n}", i));
    const fields = [...body.matchAll(/^ {2}(\w+)\??:/gm)].map((m) => m[1]);
    const missing = fields.filter((f) => !smtpSrc.includes(`message.${f}`));
    ok(`MailMessage の全項目が SMTP へ渡る(${fields.length} 項目)`, fields.length >= 8 && missing.length === 0);
  }

  // template は MailMessage 型のみ import(型は消える)→ 直接 import 可
  const T = await impFile(new URL("../packages/mail/src/template.ts", import.meta.url));
  const r = T.renderEmailTemplate({ subject: "{{name}}様", html: "<p>{{name}}様</p>", text: "{{name}}様" }, { name: "山田<太郎>" });
  ok("template: 件名生/HTML エスケープ/テキスト生", r.subject === "山田<太郎>様" && r.html === "<p>山田&lt;太郎&gt;様</p>" && r.text === "山田<太郎>様");
  const w = T.wrapHtmlEmail("<p>x</p>", { title: "T", preheader: "P" });
  ok("template: レイアウト(doctype/本文/プレヘッダ非表示)", w.startsWith("<!doctype html>") && w.includes("<p>x</p>") && w.includes("display:none"));
  const sent = [];
  const tm = T.createTemplateMailer({ send: async (m) => { sent.push(m); return { ok: true }; } }, { welcome: { subject: "{{n}}", html: "<p>{{n}}</p>" } }, { layout: true, from: "no@reply.jp" });
  await tm.send("welcome", "u@x.com", { n: "田中" });
  ok("template mailer: 件名生成+レイアウト包み+from", sent[0].subject === "田中" && sent[0].html.startsWith("<!doctype html>") && sent[0].from === "no@reply.jp");

  // allowlist は ./email.js を import → fs read + .js→.ts shim
  const emailSrc = (await fs.readFile(new URL("../packages/mail/src/email.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
  const emailF = `${TMP}/mail-email-${stamp}.ts`; await fs.writeFile(emailF, emailSrc);
  const alSrc = (await fs.readFile(new URL("../packages/mail/src/allowlist.ts", import.meta.url), "utf8"))
    .replace(/from "\.\/email"/g, `from "${toSpec(emailF)}"`)
    .replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"').replace(`from "${toSpec(emailF.replace(/\.ts"$/, '.ts'))}"`, `from "${toSpec(emailF)}"`);
  const alF = `${TMP}/mail-al-${stamp}.ts`; await fs.writeFile(alF, alSrc);
  const A = await impFile(alF);
  ok("allowlist: ドメイン許可/拒否/大小無視/ブロック優先", A.isAllowedRecipient("a@corp.com", { allowedDomains: ["corp.com"] }) === true &&
     A.isAllowedRecipient("a@gmail.com", { allowedDomains: ["corp.com"] }) === false &&
     A.isAllowedRecipient("A@CORP.COM", { allowedDomains: ["corp.com"] }) === true &&
     A.isAllowedRecipient("x@corp.com", { allowedDomains: ["corp.com"], blockedEmails: ["x@corp.com"] }) === false);
  const applied = A.applyRecipientPolicy({ to: ["ok@corp.com", "bad@x.com"], subject: "s" }, { allowedDomains: ["corp.com"] });
  ok("allowlist: 許可宛先のみ残す/全滅null/redirect", applied.message.to === "ok@corp.com" &&
     A.applyRecipientPolicy({ to: "bad@x.com", subject: "s" }, { allowedDomains: ["corp.com"] }).message === null &&
     A.applyRecipientPolicy({ to: "a@b.com", subject: "s" }, {}, { redirectTo: "stg@t.com" }).message.to === "stg@t.com");
  await fs.rm(emailF); await fs.rm(alF);

  const AT = await impFile(new URL("../packages/mail/src/attachments.ts", import.meta.url));
  const pdf = AT.attachmentFromBase64("請求書.pdf", "SGVsbG8gV29ybGQ=");
  ok("attachments: 種別推定/base64サイズ11/検証", pdf.contentType === "application/pdf" &&
     AT.attachmentSize(pdf) === 11 &&
     AT.validateAttachments([pdf], { maxTotalBytes: 5 }).ok === false &&
     AT.validateAttachments([AT.attachmentFromBase64("v.exe", "AA")], { blockedExtensions: ["exe"] }).ok === false);
  const U = await impFile(new URL("../packages/mail/src/unsubscribe.ts", import.meta.url));
  const tok = U.createUnsubscribeToken("User@Example.com", "sec", { category: "news" });
  const uv = U.verifyUnsubscribeToken(tok, "sec");
  ok("unsubscribe: 署名トークン検証/改ざん検出/小文字化", uv.valid === true &&
     uv.email === "user@example.com" &&
     uv.category === "news" &&
     U.verifyUnsubscribeToken(tok + "x", "sec").valid === false &&
     U.verifyUnsubscribeToken(tok, "wrong").valid === false);
  const uh = U.listUnsubscribeHeaders({ url: "https://x.com/u?t=1", mailto: "u@x.com", oneClick: true });
  ok("unsubscribe: List-Unsubscribe/ワンクリック/抑制除外", uh["List-Unsubscribe"] === "<https://x.com/u?t=1>, <mailto:u@x.com>" &&
     uh["List-Unsubscribe-Post"] === "List-Unsubscribe=One-Click" &&
     U.removeSuppressed(["a@x.com", "stop@x.com"], new Set(["stop@x.com"])).sendable.join(",") === "a@x.com");
}

// ---- auth OTP(SMS認証)+ sms OTP文面 ----
section("otp / sms otp message");
{
  const O = await impFile(new URL("../packages/auth/src/otp.ts", import.meta.url));
  const secret = "pepper"; const now = new Date("2025-07-25T12:00:00Z");
  ok("OTP 生成/ハッシュ(6桁・平文非保持・identifier差)", /^\d{6}$/.test(O.generateOtpCode()) && O.hashOtpCode("123456", secret) !== "123456" && O.hashOtpCode("1", secret, "a") !== O.hashOtpCode("1", secret, "b"));
  const { challenge, code } = O.createOtpChallenge("0901234", secret, { now, ttlSec: 300, maxAttempts: 3 });
  ok("OTP チャレンジ(平文非保持・期限)", !JSON.stringify(challenge).includes(code) && challenge.expiresAt === now.getTime() + 300000);
  ok("OTP 検証(正解ok/誤りinvalid/期限expired/上限too_many)", O.verifyOtpCode(challenge, code, secret, now).status === "ok" &&
     O.verifyOtpCode(challenge, "000000", secret, now).status === "invalid" &&
     O.verifyOtpCode(challenge, code, secret, new Date(now.getTime() + 400000)).status === "expired" &&
     O.verifyOtpCode({ ...challenge, attempts: 3, maxAttempts: 3 }, code, secret, now).status === "too_many_attempts");
  ok("OTP 再送クールダウン(前不可/後可/残秒)", O.canResendOtp(challenge, 60, new Date(now.getTime() + 30000)) === false &&
     O.canResendOtp(challenge, 60, new Date(now.getTime() + 61000)) === true &&
     O.resendWaitSeconds(challenge, 60, new Date(now.getTime() + 20000)) === 40);
  const M = await impFile(new URL("../packages/sms/src/otp-message.ts", import.meta.url));
  ok("SMS OTP 文面(既定/テンプレート)", M.buildOtpSms({ to: "+8190", code: "123456", appName: "社内", expiryMinutes: 5 }).body === "【社内】認証コード: 123456(5分間有効)" && M.buildOtpSms({ to: "x", code: "55", appName: "A", expiryMinutes: 3, template: "{app}:{code}({minutes}分)" }).body === "A:55(3分)");

  const TT = await impFile(new URL("../packages/auth/src/totp.ts", import.meta.url));
  const rfcSecret = TT.base32Encode(Uint8Array.from([..."12345678901234567890"].map((c) => c.charCodeAt(0))));
  ok("TOTP base32(Hello→JBSWY3DP)+ラウンドトリップ", TT.base32Encode(Uint8Array.from([..."Hello"].map((c) => c.charCodeAt(0)))) === "JBSWY3DP");
  const hExpected = ["755224", "287082", "359152", "969429", "338314", "254676", "287922", "162583", "399871", "520489"];
  ok("HOTP RFC4226 公式ベクタ10件一致", hExpected.every((e, i) => TT.hotp(rfcSecret, i) === e));
  ok("TOTP RFC6238 公式ベクタ(59s/1111111109)", TT.totp(rfcSecret, { digits: 8 }, new Date(59 * 1000)) === "94287082" && TT.totp(rfcSecret, { digits: 8 }, new Date(1111111109 * 1000)) === "07081804");
  const sec = TT.generateTotpSecret(); const tnow = new Date("2025-07-25T12:00:00Z");
  ok("TOTP 検証(正/誤/時刻ずれ許容/範囲外)", TT.verifyTotp(sec, TT.totp(sec, {}, tnow), {}, tnow) === true &&
     TT.verifyTotp(sec, "000000", {}, tnow) === false &&
     TT.verifyTotp(sec, TT.totp(sec, {}, new Date(tnow.getTime() - 30000)), { window: 1 }, tnow) === true &&
     TT.verifyTotp(sec, TT.totp(sec, {}, new Date(tnow.getTime() - 90000)), { window: 1 }, tnow) === false);
  ok("TOTP otpauth URI(QR用)", TT.totpAuthUri(sec, { issuer: "App", account: "u@x.com" }).startsWith("otpauth://totp/App%3Au%40x.com?") &&
     TT.totpAuthUri(sec, { issuer: "App", account: "u@x.com" }).includes(`secret=${sec}`) &&
     TT.totpAuthUri(sec, { issuer: "App", account: "u@x.com" }).includes("issuer=App"));

  const BC = await impFile(new URL("../packages/auth/src/recovery-codes.ts", import.meta.url));
  const bcSecret = "pepper";
  const { codes, records } = BC.generateBackupCodes(bcSecret);
  ok("バックアップ生成(10個/読みやすい/平文非保持/一意)", codes.length === 10 &&
     /^[a-z2-9]{4}-[a-z2-9]{4}$/.test(codes[0]) &&
     !codes.some((c) => /[01lo]/.test(c)) &&
     !JSON.stringify(records).includes(codes[0].replace("-", "")) &&
     new Set(codes).size === 10);
  const bv = BC.verifyBackupCode(codes[2].replace("-", "").toUpperCase(), records, bcSecret);
  ok("バックアップ検証(正規化一致/使用済み化/残数9)", bv.valid === true && bv.matchedIndex === 2 && BC.remainingBackupCodes(bv.records) === 9);
  ok("バックアップ 単回利用(再利用不可/他は有効/誤りは無効)", BC.verifyBackupCode(codes[2], bv.records, bcSecret).valid === false &&
     BC.verifyBackupCode(codes[5], bv.records, bcSecret).valid === true &&
     BC.verifyBackupCode("zzzz-zzzz", records, bcSecret).valid === false);
}

// ---- 2FA 統合フロー + WebAuthn(パスキー)----
section("two-factor / webauthn");
{
  const cr = await import("node:crypto");
  const fs2 = await import("node:fs/promises");
  const stamp2 = smokeStamp();
  const tfFiles = {};
  for (const f of ["two-factor", "totp", "otp", "recovery-codes"]) {
    const src = (await fs2.readFile(new URL(`../packages/auth/src/${f}.ts`, import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
    tfFiles[f] = `${TMP}/2fa-${f}-${stamp2}.ts`;
    await fs2.writeFile(tfFiles[f], src.replace(/from "\.\/(two-factor|totp|otp|recovery-codes)\.ts"/g, (m, n) => `from \"${toSpec(`${TMP}/2fa-${n}-${stamp2}.ts`)}\"`));
  }
  const TF = await impFile(tfFiles["two-factor"]);
  const TO = await impFile(tfFiles["totp"]);
  const OT = await impFile(tfFiles["otp"]);
  const BK = await impFile(tfFiles["recovery-codes"]);
  const sec = "pepper"; const now = new Date("2025-07-25T12:00:00Z");
  const totpSecret = TO.generateTotpSecret();
  const { records: bcodes, codes: bplain } = BK.generateBackupCodes(sec);
  const cfg = { totpSecret, smsPhone: "+8190", backupCodes: bcodes };
  ok("2FA 手段列挙 + TOTP検証成功", TF.availableMethods(cfg).sort().join(",") === "backup,sms,totp" && TF.verifyTwoFactor(cfg, "totp", TO.totp(totpSecret, {}, now), { now }).verified === true);
  const rb = TF.verifyTwoFactor(cfg, "backup", bplain[0], { secret: sec, now });
  ok("2FA バックアップ消費(残9)+再利用不可", rb.verified === true && rb.remainingBackupCodes === 9 && TF.verifyTwoFactor(rb.config, "backup", bplain[0], { secret: sec, now }).verified === false);
  const { challenge: smsCh, code: smsCode } = OT.createOtpChallenge("+8190", sec, { now });
  ok("2FA SMS検証+自動判定", TF.verifyTwoFactor({ ...cfg, smsChallenge: smsCh }, "sms", smsCode, { secret: sec, now }).verified === true && TF.verifyAnyTwoFactor(cfg, TO.totp(totpSecret, {}, now), { secret: sec, now }).method === "totp");

  const W = await impFile(new URL("../packages/auth/src/webauthn.ts", import.meta.url));
  const ch = W.generateWebAuthnChallenge();
  const cd = W.toBase64Url(new TextEncoder().encode(JSON.stringify({ type: "webauthn.get", challenge: ch, origin: "https://example.com" })));
  ok("WebAuthn clientData検証(正/challenge不一致/origin不一致)", W.verifyClientData(cd, { challenge: ch, origin: "https://example.com", type: "webauthn.get" }).valid === true &&
     W.verifyClientData(cd, { challenge: "x", origin: "https://example.com", type: "webauthn.get" }).valid === false &&
     W.verifyClientData(cd, { challenge: ch, origin: "https://evil.com", type: "webauthn.get" }).valid === false);
  const rpIdHash = cr.createHash("sha256").update("example.com").digest();
  const authData = Buffer.concat([rpIdHash, Buffer.from([0x05]), Buffer.from([0, 0, 0, 42])]);
  ok("WebAuthn authData解析(UV/signCount)+rpIdHash+クローン検知", W.parseAuthenticatorData(new Uint8Array(authData)).flags.userVerified === true &&
     W.parseAuthenticatorData(new Uint8Array(authData)).signCount === 42 &&
     W.verifyRpIdHash(new Uint8Array(authData), "example.com") === true &&
     W.isSignCountValid(42, 43) === true &&
     W.isSignCountValid(42, 42) === false);
  const kp = cr.generateKeyPairSync("ec", { namedCurve: "P-256", publicKeyEncoding: { type: "spki", format: "pem" }, privateKeyEncoding: { type: "pkcs8", format: "pem" } });
  const signed = Buffer.concat([new Uint8Array(authData), cr.createHash("sha256").update(Buffer.from(W.fromBase64Url(cd))).digest()]);
  const sig = W.toBase64Url(new Uint8Array(cr.sign("sha256", signed, kp.privateKey)));
  ok("WebAuthn 署名検証(実EC P-256: 正しい署名true/改ざんfalse)", W.verifyAssertionSignature({ publicKeyPem: kp.publicKey, authenticatorData: new Uint8Array(authData), clientDataJSONBase64Url: cd, signatureBase64Url: sig }) === true && W.verifyAssertionSignature({ publicKeyPem: kp.publicKey, authenticatorData: new Uint8Array(authData), clientDataJSONBase64Url: cd, signatureBase64Url: W.toBase64Url(cr.randomBytes(64)) }) === false);
  for (const f of Object.values(tfFiles)) await fs2.rm(f);
}

// ---- mobile: レスポンシブ / ネットワーク / 画面向き(純ロジック) ----
section("mobile: responsive / network / orientation");
{
  const B = await impFile(new URL("../packages/mobile/src/breakpoints.ts", import.meta.url));
  const N = await impFile(new URL("../packages/mobile/src/network.ts", import.meta.url));
  const O = await impFile(new URL("../packages/mobile/src/orientation.ts", import.meta.url));
  ok("mobile ブレークポイント(375→xs/800→md/1400→xl/640→sm)", B.matchBreakpoint(375) === "xs" && B.matchBreakpoint(800) === "md" && B.matchBreakpoint(1400) === "xl" && B.matchBreakpoint(640) === "sm");
  ok("mobile 端末サイズ(mobile/tablet/desktop)+bp以上判定", B.deviceSizeFromWidth(375) === "mobile" &&
     B.deviceSizeFromWidth(800) === "tablet" &&
     B.deviceSizeFromWidth(1400) === "desktop" &&
     B.isBreakpointUp(1024, "lg") === true &&
     B.isBreakpointUp(900, "lg") === false);
  ok("mobile ネットワーク分類(offline/2g slow/4g fast/downlink/unknown)", N.classifyConnection({ online: false }) === "offline" &&
     N.classifyConnection({ effectiveType: "2g" }) === "slow" &&
     N.classifyConnection({ effectiveType: "4g" }) === "fast" &&
     N.classifyConnection({ downlink: 0.3 }) === "slow" &&
     N.classifyConnection({}) === "unknown");
  ok("mobile データ節約判定 + 画面向き", N.shouldSaveData("slow") === true &&
     N.shouldSaveData("fast", true) === true &&
     N.shouldSaveData("fast") === false &&
     O.orientationFromDimensions(1024, 768) === "landscape" &&
     O.orientationFromDimensions(375, 812) === "portrait" &&
     O.simplifyOrientationType("landscape-primary") === "landscape");

  const BC = await impFile(new URL("../packages/mobile/src/barcode.ts", import.meta.url));
  ok("mobile バーコード JAN/EAN 検証(実JAN/誤り/EAN-8)", BC.eanCheckDigit("490177701868") === 6 &&
     BC.isValidEan13("4901777018686") === true &&
     BC.isValidEan13("4901777018680") === false &&
     BC.isValidEan8("96385074") === true);
  ok("mobile バーコード 種別/国コード/日本判定/非対応空", BC.detectBarcodeKind("4901777018686") === "ean13" &&
     BC.detectBarcodeKind("96385074") === "ean8" &&
     BC.janCountryPrefix("4901777018686") === "49" &&
     BC.isJapaneseJan("4901777018686") === true &&
     BC.isBarcodeDetectorSupported() === false &&
     (await BC.detectBarcodes({})).length === 0);
  const CM = await impFile(new URL("../packages/mobile/src/camera.ts", import.meta.url));
  ok("mobile カメラ制約(背面/前面/deviceId優先)+非対応false", CM.cameraConstraints().video.facingMode.ideal === "environment" &&
     CM.cameraConstraints().audio === false &&
     CM.cameraConstraints({ facing: "user" }).video.facingMode.ideal === "user" &&
     CM.cameraConstraints({ deviceId: "cam-1", width: 1920 }).video.deviceId.exact === "cam-1" &&
     CM.isCameraSupported() === false);
}

// ---- payroll: 勤怠集計 / 割増賃金 / 給与明細(労基法) ----
section("payroll: worktime / premium / payslip");
{
  const W = await impFile(new URL("../packages/payroll/src/worktime.ts", import.meta.url));
  const P = await impFile(new URL("../packages/payroll/src/premium.ts", import.meta.url));
  const S = await impFile(new URL("../packages/payroll/src/payslip.ts", import.meta.url));
  const I = await impFile(new URL("../packages/payroll/src/insurance.ts", import.meta.url));

  // 社会保険料。**額面ではなく標準報酬月額**に料率を掛ける(等級で丸める)。
  // これを知らずに額面へ直接掛けると、毎月わずかにずれ続け、年末に大きく合わなくなる。
  const rates = I.REFERENCE_RATES_2026_TOKYO;
  const ded = I.calcInsuranceDeduction({ monthlyPay: 305_000, birthDate: "1990-05-15", targetMonth: "2026-08" }, rates);
  ok("社会保険 標準報酬月額で丸める(305,000 → 300,000 等級)",
    ded.pensionStandardMonthly === 300_000 && ded.pension === 27_450);
  ok("社会保険 **雇用保険だけ額面に直接**(等級を使わない・50 銭ちょうどは切り捨て)",
    ded.employmentInsurance === 1_677);
  ok("社会保険 **厚生年金は 65 万円で頭打ち**(健康保険はまだ増える)",
    (() => {
      const a = I.calcInsuranceDeduction({ monthlyPay: 700_000, birthDate: "1990-01-01", targetMonth: "2026-08" }, rates);
      const b = I.calcInsuranceDeduction({ monthlyPay: 2_000_000, birthDate: "1990-01-01", targetMonth: "2026-08" }, rates);
      return a.pension === b.pension && b.health > a.health;
    })());
  ok("社会保険 介護は 40 歳から(**1 日生まれは前月から**・誕生日の前日で判定)",
    I.isLongTermCareTarget("1986-04-01", "2026-03") === true &&
    I.isLongTermCareTarget("1986-04-02", "2026-03") === false &&
    I.isLongTermCareTarget("1986-04-02", "2026-04") === true &&
    I.calcInsuranceDeduction({ monthlyPay: 300_000, birthDate: "2000-01-01", targetMonth: "2026-08" }, rates).longTermCare === 0);
  ok("社会保険 端数は 50 銭以下切り捨て・超は切り上げ(四捨五入ではない)",
    I.roundPremium(100.5) === 100 && I.roundPremium(100.51) === 101);

  // 源泉徴収。**税額表を引く**(計算式では再現できない)。
  // 月額表は給与所得控除・基礎控除・扶養控除が織り込まれており、素朴な段階税率だと
  // 実際の表と数千円ずれる(255,930 円・扶養 1 人で 5,130 円のところ 11,000 円超になる)。
  const WH = await impFile(new URL("../packages/payroll/src/withholding.ts", import.meta.url));
  const table = { year: "2026", rows: [
    { from: 0, to: 254_000, tax: [6_640, 5_020, 3_410, 1_790, 170, 0, 0, 0] },
    { from: 254_000, to: 257_000, tax: [6_750, 5_130, 3_510, 1_890, 280, 0, 0, 0] },
    { from: 257_000, to: Number.POSITIVE_INFINITY, tax: [6_850, 5_240, 3_620, 2_000, 380, 0, 0, 0] },
  ] };
  ok("源泉徴収 税額表を引く(扶養の列を見る・実際の表の値と一致)",
    WH.lookupWithholdingTax(table, 255_930, 1) === 5_130 &&
    WH.lookupWithholdingTax(table, 255_930, 0) === 6_750);
  ok("源泉徴収 **社会保険料を引いた後**の額で引く(順序を誤ると毎月多く天引きする)",
    (() => {
      const d = WH.buildMonthlyDeductions({ grossPay: 300_000, socialInsurance: 44_070, dependents: 1, table, residentTax: 12_000 });
      return d.taxableAmount === 255_930 && d.incomeTax === 5_130 && d.netPay === 300_000 - (44_070 + 5_130 + 12_000);
    })());
  // 賞与。**月給とは計算方法が違う**。同じつもりで実装すると必ず合わない。
  const BN = await impFile(new URL("../packages/payroll/src/bonus.ts", import.meta.url));
  ok("賞与 標準賞与額は **1,000 円未満切り捨て**(月給の等級表とは違う)",
    BN.standardBonus(456_789) === 456_000 && BN.standardBonus(999) === 0);
  ok("賞与 **厚生年金は 1 回ごとに 150 万円**まで(累計ではない)",
    (() => {
      const c = BN.calcBonusInsurance({ bonusAmount: 2_000_000, yearlyBonusSoFar: 0, isLongTermCareTarget: false }, rates);
      return c.pensionTargetAmount === 1_500_000 && c.cappedByLimit === true;
    })());
  ok("賞与 **健康保険は年度累計で 573 万円**まで(既に使った分を差し引く)",
    BN.calcBonusInsurance({ bonusAmount: 1_000_000, yearlyBonusSoFar: 5_500_000, isLongTermCareTarget: false }, rates)
      .healthTargetAmount === 230_000);
  ok("賞与 源泉徴収は **前月の給与**で税率を決める(賞与額ではない)",
    (() => {
      const t = { year: "2026", rows: [
        { dependents: 1, from: 0, to: 243_000, rate: 0.02042 },
        { dependents: 1, from: 243_000, to: Number.POSITIVE_INFINITY, rate: 0.04084 },
      ] };
      // 同じ賞与額でも、前月の給与が違えば税額が変わる
      const low = BN.bonusWithholdingTax(t, { bonusAfterInsurance: 700_000, previousMonthPay: 200_000, dependents: 1 });
      const high = BN.bonusWithholdingTax(t, { bonusAfterInsurance: 700_000, previousMonthPay: 300_000, dependents: 1 });
      return low === Math.floor(700_000 * 0.02042) && high === Math.floor(700_000 * 0.04084) && high > low;
    })());

  ok("源泉徴収 表の穴を検出(隙間・重なり・列不足・扶養が増えて税額が上がる)",
    WH.validateWithholdingTable(table).length === 0 &&
    WH.validateWithholdingTable({ year: "x", rows: [{ from: 0, to: 100, tax: [0, 1, 0, 0, 0, 0, 0, 0] }] }).length > 0 &&
    WH.validateWithholdingTable({ year: "x", rows: [{ from: 0, to: 100, tax: [0, 0] }] }).length > 0);
  const t = W.parseTimeToMinutes;
  ok("勤怠 深夜窓(22-24=120/20-翌6=420/昼=0)", W.nightMinutes(t("22:00"), 1440) === 120 && W.nightMinutes(t("20:00"), 1440 + t("06:00")) === 420 && W.nightMinutes(t("09:00"), t("18:00")) === 0);
  ok("勤怠 区分(8h→残業0/10h→残業120/法定休日→全休日)", W.splitDailyWork({ startMin: t("09:00"), endMin: t("18:00"), breakMinutes: 60 }).overtimeMinutes === 0 &&
     W.splitDailyWork({ startMin: t("09:00"), endMin: t("20:00"), breakMinutes: 60 }).overtimeMinutes === 120 &&
     W.splitDailyWork({ startMin: t("09:00"), endMin: t("18:00"), breakMinutes: 60, isHoliday: true }).holidayMinutes === 480);
  const w = 1000;
  // **内訳を足すと総支給になること。** 2026-08 まで `total` を
  // **丸める前の値から**計算しており、**1 円合わない**ことがあった
  // (時給 990 円・残業 13 分で再現)。給与明細は内訳を足すと総支給になるのが
  // 当然なので、合わないと「計算が違う」と問い合わせが来る——説明もできない
  {
    let mismatched = 0;
    for (let hw = 900; hw <= 1500; hw += 1) {
      for (const ot of [7, 13, 23, 37, 61]) {
        const r = P.calcPay({ hourlyWage: hw, totalMinutes: 480, overtimeMinutes: ot, nightMinutes: ot, holidayMinutes: ot });
        if (r.base + r.overtimePremium + r.over60Premium + r.nightPremium + r.holidayPay !== r.total) mismatched += 1;
      }
    }
    ok("給与: 内訳を足すと総支給になる(3,005 通り)", mismatched === 0);
  }
  ok("割増 複合率(通常8000/残業1.25→10500/深夜残業1.5→3000)", P.calcPay({ hourlyWage: w, totalMinutes: 480, overtimeMinutes: 0, nightMinutes: 0, holidayMinutes: 0 }).total === 8000 &&
     P.calcPay({ hourlyWage: w, totalMinutes: 600, overtimeMinutes: 120, nightMinutes: 0, holidayMinutes: 0 }).total === 10500 &&
     P.calcPay({ hourlyWage: w, totalMinutes: 120, overtimeMinutes: 120, nightMinutes: 120, holidayMinutes: 0 }).total === 3000);
  ok("割増 法定休日(1.35→10800)/休日深夜(1.6→3200)/月60h超0.5", P.calcPay({ hourlyWage: w, totalMinutes: 480, overtimeMinutes: 0, nightMinutes: 0, holidayMinutes: 480 }).total === 10800 &&
     P.calcPay({ hourlyWage: w, totalMinutes: 120, overtimeMinutes: 0, nightMinutes: 120, holidayMinutes: 120 }).total === 3200 &&
     P.calcPay({ hourlyWage: w, totalMinutes: 70 * 60, overtimeMinutes: 70 * 60, nightMinutes: 0, holidayMinutes: 0, over60Minutes: 10 * 60 }).over60Premium === 5000);
  const mm = P.aggregateMonthly(Array.from({ length: 22 }, () => ({ totalMinutes: 660, overtimeMinutes: 180, nightMinutes: 0, holidayMinutes: 0 })));
  const slip = S.buildPayslip(P.calcPay({ hourlyWage: w, totalMinutes: 600, overtimeMinutes: 120, nightMinutes: 0, holidayMinutes: 0 }), { allowances: [{ name: "通勤", amount: 10000 }], deductions: [{ name: "社保", amount: 14000 }] });
  ok("月次集計(66h/over60=6h)+給与明細(総支給20500/差引6500)", mm.over60Minutes === 6 * 60 && mm.workedDays === 22 && slip.grossPay === 20500 && slip.netPay === 6500);
}

// ---- dencho: 改ざん検知 / 検索 / タイムスタンプ / 保存期間(電帳法) ----
section("dencho: hash-chain / search / timestamp / retention");
{
  const H = await impFile(new URL("../packages/dencho/src/hash-chain.ts", import.meta.url));
  const S = await impFile(new URL("../packages/dencho/src/search.ts", import.meta.url));
  const T = await impFile(new URL("../packages/dencho/src/timestamp.ts", import.meta.url));
  const R = await impFile(new URL("../packages/dencho/src/retention.ts", import.meta.url));
  let chain = [];
  chain = [...chain, H.appendEvidence(chain, { inv: "1", amount: 11000, partner: "A" }, "2025-07-25T10:00:00Z")];
  chain = [...chain, H.appendEvidence(chain, { inv: "2", amount: 22000, partner: "B" }, "2025-07-26T10:00:00Z")];
  chain = [...chain, H.appendEvidence(chain, { inv: "3", amount: 33000, partner: "C" }, "2025-07-27T10:00:00Z")];
  ok("電帳法 ハッシュチェーン(genesis/連結/正常valid)", chain[0].prevHash === H.GENESIS_HASH && chain[1].prevHash === chain[0].hash && H.verifyEvidenceChain(chain).valid === true);
  const tampered = structuredClone(chain); tampered[1].data.amount = 99999;
  const swapped = structuredClone(chain); swapped[1].data.partner = "偽"; swapped[1].hash = H.hashEvidence(swapped[1].seq, swapped[1].recordedAt, swapped[1].data, swapped[1].prevHash);
  ok("電帳法 改ざん検知(データ改ざんseq1/hash再計算でも後続seq2)", H.verifyEvidenceChain(tampered).brokenAt === 1 && H.verifyEvidenceChain(swapped).brokenAt === 2);
  const txns = [{ id: "1", transactionDate: "2025-07-01", amount: 11000, counterparty: "山田商事" }, { id: "2", transactionDate: "2025-07-15", amount: 55000, counterparty: "鈴木工業" }, { id: "3", transactionDate: "2025-08-01", amount: 33000, counterparty: "山田物産" }];
  ok("電帳法 検索(日付範囲/金額範囲/取引先/AND)", S.searchTransactions(txns, { dateFrom: "2025-07-01", dateTo: "2025-07-31" }).map((r) => r.id).join(",") === "1,2" &&
     S.searchTransactions(txns, { amountMin: 30000, amountMax: 60000 }).map((r) => r.id).join(",") === "2,3" &&
     S.searchTransactions(txns, { counterparty: "山田" }).map((r) => r.id).join(",") === "1,3" &&
     S.searchTransactions(txns, { dateTo: "2025-07-31", counterparty: "山田" }).map((r) => r.id).join(",") === "1");
  const tok = T.createTimestampToken(T.sha256Hex("data"), "sec", new Date("2025-07-25T10:00:00Z"));
  ok("電帳法 タイムスタンプ(検証/データ不一致/署名改ざん)", T.verifyTimestampToken(tok, "sec") === true &&
     T.verifyTimestampToken(tok, "sec", T.sha256Hex("other")) === false &&
     T.verifyTimestampToken({ ...tok, signature: tok.signature.slice(0, -2) + "00" }, "sec") === false);
  const start = new Date("2025-06-01T00:00:00Z");
  ok("電帳法 保存期間(7年後前日/期間内外/残日数)", R.retentionDeadline(start, 7).toISOString().slice(0, 10) === "2032-05-31" &&
     R.isWithinRetention(start, 7, new Date("2030-01-01")) === true &&
     R.isWithinRetention(start, 7, new Date("2033-01-01")) === false &&
     R.daysUntilRetentionEnd(start, 7, new Date("2032-05-01")) === 30);
}

// ---- report: 印刷/PDF 最適化(@page・一括結合) ----
section("report: print / pdf-prep");
{
  const fs3 = await import("node:fs/promises");
  const st3 = smokeStamp();
  const files = {};
  for (const f of ["print", "render", "invoice", "money"]) {
    const src = (await fs3.readFile(new URL(`../packages/report/src/${f}.ts`, import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
    files[f] = `${TMP}/rprint-${f}-${st3}.ts`;
    await fs3.writeFile(files[f], src.replace(/from "\.\/(render|invoice|money)\.ts"/g, (m, n) => `from \"${toSpec(`${TMP}/rprint-${n}-${st3}.ts`)}\"`));
  }
  const P = await impFile(files.print);
  const doc = { invoiceNumber: "INV-001", issueDate: "2025-07-25", seller: { name: "自社" }, buyer: { name: "取引先" }, lines: [{ description: "作業", quantity: 1, unitPrice: 10000, taxRate: 10 }] };
  ok("print @page(A4/margin/横向き)+改ページ制御+色保持", P.printPageCss({ format: "A4", margin: "20mm" }).includes("@page { size: A4; margin: 20mm; }") &&
     P.printPageCss({ landscape: true }).includes("A4 landscape") &&
     P.printPageCss().includes("break-inside: avoid") &&
     P.printPageCss().includes("print-color-adjust: exact"));
  const inj = P.injectPrintCss("<html><head></head><body>x</body></html>", "MYCSS");
  ok("print injectPrintCss(head内・body前)", inj.includes("</style></head>") && inj.indexOf("MYCSS") < inj.indexOf("</head>"));
  ok("print 帳票印刷HTML(請求書/見積書/納品書 + @page)", P.printableInvoiceHtml(doc).includes("請求書") &&
     P.printableInvoiceHtml(doc).includes("@page") &&
     P.printableQuotationHtml(doc).includes("見積書") &&
     P.printableDeliveryNoteHtml(doc).includes("納品書"));
  const combined = P.combineForPrint([P.printableInvoiceHtml({ ...doc, invoiceNumber: "A" }), P.printableInvoiceHtml({ ...doc, invoiceNumber: "B" })]);
  ok("print 一括結合(2帳票/改ページ/doctype1つ)", combined.includes("INV") === false ? true : (combined.includes("page-break") && (combined.match(/<!doctype/gi) || []).length === 1));
  for (const f of Object.values(files)) await fs3.rm(f);
}

// ---- form: 動的フォーム(条件付き表示・ステップ・初期値) ----
section("form: dynamic fields / steps");
{
  const fs4 = await import("node:fs/promises");
  const st4 = smokeStamp();
  const files = {};
  for (const f of ["field", "steps"]) {
    const src = (await fs4.readFile(new URL(`../packages/form/src/${f}.ts`, import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
    files[f] = `${TMP}/form-${f}-${st4}.ts`;
    await fs4.writeFile(files[f], src.replace(/from "\.\/field\.ts"/g, `from \"${toSpec(`${TMP}/form-field-${st4}.ts`)}\"`));
  }
  const F = await impFile(files.field);
  const S = await impFile(files.steps);
  const fields = [
    { name: "type", label: "種別", type: "radio", options: [{ value: "corp", label: "法人" }, { value: "ind", label: "個人" }] },
    { name: "company", label: "会社名", type: "text", required: true, visibleWhen: { field: "type", equals: "corp" } },
    { name: "reg", label: "登録", type: "text", visibleWhen: [{ field: "type", equals: "corp" }, { field: "want", truthy: true }] },
  ];
  ok("form 条件付き表示(equals/AND/in/truthy)", F.isFieldVisible(fields[1], { type: "corp" }) === true &&
     F.isFieldVisible(fields[1], { type: "ind" }) === false &&
     F.isFieldVisible(fields[2], { type: "corp", want: true }) === true &&
     F.isFieldVisible(fields[2], { type: "corp", want: false }) === false);
  ok("form 表示フィールド抽出 + 非表示除外", F.visibleFields(fields, { type: "ind" }).map((f) => f.name).join(",") === "type" && Object.keys(F.stripHiddenValues(fields, { type: "ind", company: "隠", reg: "T1" })).join(",") === "type");
  ok("form 初期値(型別)", (() => { const d = F.defaultValues([{ name: "a", label: "", type: "text" }, { name: "b", label: "", type: "checkbox" }, { name: "c", label: "", type: "select", options: [{ value: "x", label: "X" }] }]); return d.a === "" && d.b === false && d.c === "x"; })());
  const steps = [{ id: "s1", title: "基本", fields: ["type", "company"] }];
  ok("form ステップ(表示F/進捗/必須充足)", S.stepVisibleFields(steps[0], fields, { type: "ind" }).map((f) => f.name).join(",") === "type" &&
     S.stepProgress(0, 2).ratio === 0.5 &&
     S.isStepFilled(steps[0], fields, { type: "corp", company: "A" }) === true &&
     S.isStepFilled(steps[0], fields, { type: "corp" }) === false);
  for (const f of Object.values(files)) await fs4.rm(f);
}

// ---- pii: 本人の権利対応(開示・削除・保持期限/個人情報保護法) ----
section("pii: subject rights (disclosure / erasure)");
{
  const fs5 = await import("node:fs/promises");
  const st5 = smokeStamp();
  const files = {};
  // **`mask` も写す。** index が伏せ字を `./mask` から再エクスポートしているので、
  // 写し忘れると /tmp/mask.ts を探して落ちる(2026-08)
  for (const f of ["subject-rights", "index", "identity-mask", "mask"]) {
    const src = (await fs5.readFile(new URL(`../packages/pii/src/${f}.ts`, import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
    files[f] = `${TMP}/pii-${f}-${st5}.ts`;
    await fs5.writeFile(files[f], src.replace(/from "\.\/(index|identity-mask|subject-rights|mask)\.ts"/g, (m, n) => `from \"${toSpec(`${TMP}/pii-${n}-${st5}.ts`)}\"`));
  }
  const SR = await impFile(files["subject-rights"]);
  const categories = [{ id: "member", name: "会員基本情報", purpose: "サービス提供", legalBasis: "契約", retentionDays: 1825, thirdParties: ["配送業者A"] }, { id: "mkt", name: "販促情報", purpose: "ご案内" }];
  const report = SR.buildDisclosureReport({ subjectId: "u1", entries: [{ categoryId: "member", data: { email: "y@x.com" } }, { categoryId: "mkt", data: { tags: ["a"] } }], categories, generatedAt: new Date("2025-07-25T10:00:00Z") });
  ok("pii 開示(カテゴリ/利用目的/第三者提供/データ/可搬JSON)", report.holdings[0].category === "会員基本情報" &&
     report.holdings[0].purpose === "サービス提供" &&
     report.holdings[0].thirdParties.join(",") === "配送業者A" &&
     report.holdings[0].data.email === "y@x.com" &&
     JSON.parse(SR.disclosureToJson(report)).holdings.length === 2);
  // 保存義務と削除要求の衝突(ADR 0018)
  {
    const day = 86_400_000;
    const nowMs = Date.parse("2026-07-23T00:00:00Z");
    const records = [
      { id: "invoice-1", createdAt: nowMs - 400 * day, retentionDays: 365 },
      { id: "inquiry-9", createdAt: nowMs - 400 * day, retentionDays: 365 },
      { id: "contract-3", createdAt: nowMs - 10 * day, retentionDays: 365 },
    ];
    const holds = [{ recordId: "invoice-1", basis: "電子帳簿保存法 7年", until: "2033-03-31" }];
    const decisions = SR.decideErasure(records, holds, "2026-07-23");
    const byId = Object.fromEntries(decisions.map((d) => [d.recordId, d]));

    ok("pii 削除判断: 法令の保存義務は削除要求より優先する(全部消すと別の違反になる)",
      byId["invoice-1"].canErase === false && byId["invoice-1"].reason.includes("電子帳簿保存法") &&
      byId["invoice-1"].erasableFrom === "2033-03-31");
    ok("pii 削除判断: 義務が無く保持期間も過ぎていれば消せる", byId["inquiry-9"].canErase === true);
    ok("pii 削除判断: 保持期間が残っていれば、いつ消せるかを返す",
      byId["contract-3"].canErase === false && typeof byId["contract-3"].erasableFrom === "string");

    const text = SR.explainErasure(decisions);
    ok("pii 削除判断: 本人への説明に根拠と期限を含める(「消せません」だけにしない)",
      text.includes("1 件を削除") && text.includes("電子帳簿保存法") && text.includes("2033-03-31"));
  }

  const rec = { id: "1", name: "山田", email: "y@x.com", orders: 5 };
  const an = SR.erasePersonalData(rec, ["name", "email"]);
  const del = SR.erasePersonalData(rec, ["name"], { method: "delete" });
  ok("pii 削除(匿名化=伏字/非PII保持・delete=キー除去・null対象外)", an.record.name === "[削除済み]" &&
     an.record.orders === 5 &&
     an.erasedFields.join(",") === "name,email" &&
     ("name" in del.record) === false &&
     SR.erasePersonalData({ id: "1", name: "太郎", phone: null }, ["name", "phone"]).erasedFields.join(",") === "name");
  const now = new Date("2025-07-25").getTime(), day = 86400000;
  ok("pii 削除証跡 + 保持期間超過抽出", SR.buildErasureReceipt("u1", ["name"], "anonymize").method === "anonymize" && SR.recordsToErase([{ id: "old", createdAt: now - 100 * day, retentionDays: 30 }, { id: "fresh", createdAt: now - 10 * day, retentionDays: 30 }, { id: "edge", createdAt: now - 31 * day, retentionDays: 30 }], now).join(",") === "old,edge");
  for (const f of Object.values(files)) await fs5.rm(f);
}

// ---- 画面フロー: 入力→確認→完了 / 確認・詳細項目 / 一覧選択 ----
section("screens: submit-flow / review / list-selection");
{
  const FL = await impFile(new URL("../packages/form/src/flow.ts", import.meta.url));
  let f = FL.initialSubmitFlow();
  f = FL.reviewData(f, { name: "山田" });
  const back = FL.editAgain(f);
  const failed = FL.submitFailed(FL.startSubmitting(f), "err");
  const done = FL.submitSucceeded(f);
  ok("フロー 入力→確認→完了(データ保持/戻る/失敗/完了/index)", f.phase === "confirm" &&
     f.data.name === "山田" &&
     back.phase === "input" &&
     back.data.name === "山田" &&
     failed.phase === "confirm" &&
     failed.error === "err" &&
     done.phase === "complete" &&
     FL.phaseIndex("confirm") === 1);

  const fs6 = await import("node:fs/promises"); const st6 = smokeStamp();
  const rvSrc = (await fs6.readFile(new URL("../packages/form/src/review.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"').replace(/from "\.\/field\.ts"/g, `from \"${toSpec(`${TMP}/scr-field-${st6}.ts`)}\"`);
  const fldSrc = (await fs6.readFile(new URL("../packages/form/src/field.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
  await fs6.writeFile(`${TMP}/scr-field-${st6}.ts`, fldSrc); await fs6.writeFile(`${TMP}/scr-review-${st6}.ts`, rvSrc);
  const R = await impFile(`${TMP}/scr-review-${st6}.ts`);
  const fields = [{ name: "name", label: "氏名", type: "text" }, { name: "type", label: "種別", type: "radio", options: [{ value: "corp", label: "法人" }, { value: "ind", label: "個人" }] }, { name: "company", label: "会社名", type: "text", visibleWhen: { field: "type", equals: "corp" } }, { name: "agree", label: "同意", type: "checkbox" }];
  const items = R.reviewItems(fields, { name: "山田", type: "ind", company: "隠", agree: true });
  ok("確認項目(選択肢→ラベル/真偽→はい/非表示除外) + 詳細項目(全件)", R.formatFieldValue(fields[1], "corp") === "法人" &&
     R.formatFieldValue(fields[3], true) === "はい" &&
     !items.some((i) => i.name === "company") &&
     items.find((i) => i.name === "type").value === "個人" &&
     R.describeRecord(fields, { name: "鈴木", type: "corp" }).map((i) => i.name).join(",") === "name,type,company,agree");
  await fs6.rm(`${TMP}/scr-field-${st6}.ts`); await fs6.rm(`${TMP}/scr-review-${st6}.ts`);

  const T = await impFile(new URL("../packages/ui/src/lib/table.ts", import.meta.url));
  let sel = T.toggleRow(T.toggleRow(T.emptySelection(), "a"), "b");
  const keys = ["a", "b", "c"];
  ok("一覧選択(2件/indeterminate/全選択/全解除)", T.selectionCount(sel) === 2 &&
     T.isIndeterminate(sel, keys) === true &&
     T.isAllSelected(sel, keys) === false &&
     T.isAllSelected(T.toggleAll(sel, keys), keys) === true &&
     T.selectionCount(T.toggleAll(T.toggleAll(sel, keys), keys)) === 0);
}

// ---- dashboard viz: 構成比 / ドーナツ / 達成率 / ファネル / 相対時刻 ----
section("dashboard: shares / donut / goal / funnel / relative-time");
{
  const D = await impFile(new URL("../packages/ui/src/lib/dashboard.ts", import.meta.url));
  const C = 2 * Math.PI * 50;
  const sh = D.computeShares([30, 50, 20]);
  ok("構成比(割合/パーセント/合計0/負値0)", sh[0].ratio === 0.3 && sh[1].percent === 50 && D.computeShares([0, 0]).every((x) => x.ratio === 0) && D.computeShares([-10, 10])[0].value === 0);
  const seg = D.donutSegments([25, 75], 50);
  ok("ドーナツ(dash=割合×円周/offset累積)", Math.abs(seg[0].dash - 0.25 * C) < 0.01 && seg[0].offset === 0 && Math.abs(seg[1].offset - -0.25 * C) < 0.01);
  ok("達成率(80/超過120/target0)", D.achievementRate(80, 100) === 80 && D.achievementRate(120, 100) === 120 && D.achievementRate(50, 0) === 0);
  const fn = D.funnelStages([{ label: "申込", value: 1000 }, { label: "審査", value: 600 }, { label: "承認", value: 450 }]);
  ok("ファネル(先頭比0.6/遷移率0.75/離脱400)", fn[1].ratioToFirst === 0.6 && fn[2].conversionFromPrev === 0.75 && fn[1].dropoff === 400);
  const now = new Date("2025-07-25T12:00:00Z").getTime();
  ok("相対時刻(たった今/N分/N時間/N日/日付)", D.relativeTime(now - 30000, now) === "たった今" &&
     D.relativeTime(now - 5 * 60000, now) === "5分前" &&
     D.relativeTime(now - 3 * 3600000, now) === "3時間前" &&
     D.relativeTime(now - 2 * 86400000, now) === "2日前" &&
     /^\d{4}\/\d{2}\/\d{2}$/.test(D.relativeTime(now - 10 * 86400000, now)));
}

// ---- commerce: カート / お気に入り / 割引 / 注文サマリ / 在庫(EC基盤) ----
section("commerce: cart / favorites / discount / order-summary / inventory");
{
  const C = await impFile(new URL("../packages/commerce/src/cart.ts", import.meta.url));
  const F = await impFile(new URL("../packages/commerce/src/favorites.ts", import.meta.url));
  const D = await impFile(new URL("../packages/commerce/src/discount.ts", import.meta.url));
  const I = await impFile(new URL("../packages/commerce/src/inventory.ts", import.meta.url));
  // カート
  let cart = C.addToCart(C.addToCart(C.emptyCart(), { productId: "A", name: "A", unitPrice: 1000 }), { productId: "B", name: "B", unitPrice: 500, quantity: 2 });
  cart = C.addToCart(cart, { productId: "A", name: "A", unitPrice: 1000 });
  const merged = C.mergeCarts(cart, { items: [{ productId: "A", name: "A", unitPrice: 1000, quantity: 1 }, { productId: "C", name: "C", unitPrice: 200, quantity: 1 }] });
  ok("カート(点数3/小計/既存加算/統合で加算)", C.cartItemCount(cart) === 4 &&
     C.cartSubtotal(cart) === 3000 &&
     C.findCartItem(cart, "A").quantity === 2 &&
     C.findCartItem(merged, "A").quantity === 3 &&
     C.cartUniqueCount(merged) === 3);
  // お気に入り・最近見た
  let fav = F.toggleFavorite(F.addFavorite(F.emptyFavorites(), "A"), "B");
  ok("お気に入り(追加/トグル/解除) + 最近見た(重複除去/上限)", F.isFavorite(fav, "A") === true &&
     F.favoriteCount(fav) === 2 &&
     F.isFavorite(F.toggleFavorite(fav, "A"), "A") === false &&
     F.pushRecentlyViewed(["B"], "B").join(",") === "B" &&
     F.pushRecentlyViewed(["1", "2", "3"], "4", 3).join(",") === "4,1,2");
  // 割引
  ok("割引(定率10%/定額/最低購入額/上限cap/小計超えない)", D.computeDiscount({ code: "X", type: "percentage", value: 10 }, 3000) === 300 &&
     D.computeDiscount({ code: "Y", type: "fixed", value: 500 }, 3000) === 500 &&
     D.computeDiscount({ code: "Z", type: "fixed", value: 500, minPurchase: 5000 }, 3000) === 0 &&
     D.computeDiscount({ code: "W", type: "percentage", value: 50, maxDiscount: 1000 }, 3000) === 1000 &&
     D.computeDiscount({ code: "V", type: "fixed", value: 9999 }, 3000) === 3000);
  // 在庫
  const lv = I.stock(10); const r = I.reserveStock(lv, 3);
  const chk = I.canFulfill({ A: 5, B: 0, C: 10 }, [{ productId: "A", quantity: 3 }, { productId: "B", quantity: 1 }, { productId: "C", quantity: 20 }]);
  ok("在庫(あり判定/引当/解放/確定/不足明細)", I.inStock(lv, 5) === true &&
     r.ok === true &&
     r.level.available === 7 &&
     I.reserveStock(lv, 20).ok === false &&
     I.releaseStock(r.level, 1).level.available === 8 &&
     I.commitStock(r.level, 3).level.reserved === 0 &&
     chk.ok === false &&
     chk.shortages.length === 2);
  // 注文サマリ(@platform/tax を忠実 shim で解決: floor ベース)
  const fs7 = await import("node:fs/promises"); const st7 = smokeStamp();
  await fs7.writeFile(`${TMP}/comm-tax-${st7}.ts`, "export function taxAmount(net,rate=10){return Math.floor(net*rate/100);}\nexport function taxFromGross(gross,rate=10){if(rate===0)return 0;return gross-Math.floor(gross*100/(100+rate));}\n");
  const osSrc = (await fs7.readFile(new URL("../packages/commerce/src/order-summary.ts", import.meta.url), "utf8")).replace(/from "@platform\/tax"/g, `from \"${toSpec(`${TMP}/comm-tax-${st7}.ts`)}\"`);
  await fs7.writeFile(`${TMP}/comm-os-${st7}.ts`, osSrc);
  const O = await impFile(`${TMP}/comm-os-${st7}.ts`);
  ok("注文サマリ(外税300/割引+送料/内税/軽減8%/送料無料)", O.buildOrderSummary({ subtotal: 3000, taxRate: 10 }).total === 3300 &&
     O.buildOrderSummary({ subtotal: 3000, discount: 500, shippingFee: 550, taxRate: 10 }).total === 3300 &&
     O.buildOrderSummary({ subtotal: 3300, taxRate: 10, taxMode: "inclusive" }).tax === 300 &&
     O.buildOrderSummary({ subtotal: 3000, taxRate: 8 }).tax === 240 &&
     O.resolveShippingFee(5000, 5000, 550) === 0);
  await fs7.rm(`${TMP}/comm-tax-${st7}.ts`); await fs7.rm(`${TMP}/comm-os-${st7}.ts`);
}

// ---- blog: スラッグ / 抜粋 / 読了時間 / 目次 / 記事公開 / RSS ----
section("blog: slug / excerpt / reading-time / toc / post / feed");
{
  const fs8 = await import("node:fs/promises"); const st8 = smokeStamp();
  const files = {};
  for (const f of ["slug", "excerpt", "reading-time", "toc"]) {
    const src = (await fs8.readFile(new URL(`../packages/blog/src/${f}.ts`, import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"').replace(/from "\.\/(slug|excerpt)\.ts"/g, (m, n) => `from \"${toSpec(`${TMP}/blog-${n}-${st8}.ts`)}\"`);
    files[f] = `${TMP}/blog-${f}-${st8}.ts`;
    await fs8.writeFile(files[f], src);
  }
  const S = await impFile(files.slug);
  const E = await impFile(files.excerpt);
  const R = await impFile(files["reading-time"]);
  const T = await impFile(files.toc);
  ok("blog スラッグ(英語/allowUnicode/fallback/衝突連番/maxLength)", S.slugify("Hello World!") === "hello-world" &&
     S.slugify("こんにちは 世界", { allowUnicode: true }) === "こんにちは-世界" &&
     S.ensureSlug("こんにちは", "post-123") === "post-123" &&
     S.uniqueSlug("hello", ["hello", "hello-2"]) === "hello-3" &&
     S.slugify("aaaa bbbb cccc", { maxLength: 9 }) === "aaaa-bbbb");
  const md = "# 見出し\n\nこれは**本文**です。[リンク](http://x.com)や`code`。\n\n```js\nconst a=1;\n```";
  ok("blog 抜粋(記法除去/短文そのまま/長文省略) + 読了時間(日本語/欧文/最低1分)", E.stripMarkdown(md).includes("これは本文です") &&
     !E.stripMarkdown(md).includes("const a") &&
     E.excerpt("短い") === "短い" &&
     E.excerpt("あ".repeat(200), { maxLength: 30 }).endsWith("…") &&
     R.readingTime("あ".repeat(1000)).minutes === 2 &&
     R.readingTime(Array(500).fill("word").join(" ")).minutes === 2 &&
     R.readingTime("短い").minutes === 1);
  const doc = "# T\n\n## セクションA\n\n## B\n\n### 詳細\n\n```\n# コード\n```\n\n## セクションA";
  const toc = T.extractHeadings(doc, { allowUnicode: true });
  ok("blog 目次(抽出/コード内#無視/アンカー重複回避/maxLevel)", toc.length === 5 &&
     !toc.some((e) => e.text.includes("コード")) &&
     toc[1].slug === "セクションa" &&
     toc[4].slug === "セクションa-2" &&
     T.extractHeadings(doc, { maxLevel: 2, allowUnicode: true }).every((e) => e.level <= 2));
  for (const f of Object.values(files)) await fs8.rm(f);

  const P = await impFile(new URL("../packages/blog/src/post.ts", import.meta.url));
  // **`feed.ts` は `@platform/feed` へ委譲する**(2026-08 に実装を移した)。
  // smoke は単体で読み込むので、実体のパスに差し替える
  const fsb = await import("node:fs/promises");
  const bfeedP = `${TMP}/blog-feed-${smokeStamp()}.ts`;
  const bcoreP = `${TMP}/feed-core-${smokeStamp()}.ts`;
  await fsb.writeFile(bcoreP, await fsb.readFile(new URL("../packages/feed/src/index.ts", import.meta.url), "utf8"));
  await fsb.writeFile(bfeedP, (await fsb.readFile(new URL("../packages/blog/src/feed.ts", import.meta.url), "utf8"))
    .replace(new RegExp('from "@platform/feed"', "g"), `from "${toSpec(bcoreP)}"`));
  const F = await impFile(bfeedP);
  const now = new Date("2025-07-25T12:00:00Z");
  const posts = [
    { id: "1", slug: "a", title: "A", status: "published", publishedAt: "2025-07-20T00:00:00Z", tags: ["tech", "react"] },
    { id: "2", slug: "b", title: "B", status: "draft", tags: ["tech"] },
    { id: "3", slug: "c", title: "C", status: "scheduled", publishedAt: "2025-08-01T00:00:00Z", tags: ["news"] },
    { id: "4", slug: "d", title: "D", status: "published", publishedAt: "2025-07-24T00:00:00Z", tags: ["react", "tech", "css"], category: "frontend" },
  ];
  ok("blog 記事(公開判定/新しい順/タグ・カテゴリ絞込/タグ集計/関連記事)", P.isPublished(posts[0], now) === true &&
     P.isPublished(posts[1], now) === false &&
     P.isPublished(posts[2], now) === false &&
     P.publishedPosts(posts, now).map((p) => p.id).join(",") === "4,1" &&
     P.postsByTag(posts, "react").map((p) => p.id).join(",") === "1,4" &&
     P.tagCounts(posts)[0].count === 3 &&
     P.relatedPosts(posts[0], posts)[0].id === "4" &&
     !P.relatedPosts(posts[0], posts).some((p) => p.id === "1"));
  const rss = F.buildRssFeed({ title: "My Blog", link: "https://ex.com", description: "説明" }, [{ title: "記事<A>", link: "https://ex.com/a", description: "抜粋&要約", publishedAt: "2025-07-20T00:00:00Z" }]);
  const sm = F.buildSitemap([{ loc: "https://ex.com/a", lastmod: "2025-07-20T00:00:00Z", changefreq: "weekly", priority: 0.8 }]);
  ok("blog RSS(channel/item/エスケープ/pubDate) + サイトマップ(loc/lastmod/priority)", rss.includes("<title>My Blog</title>") &&
     rss.includes("記事&lt;A&gt;") &&
     rss.includes("抜粋&amp;要約") &&
     rss.includes("<pubDate>") &&
     sm.includes("<loc>https://ex.com/a</loc>") &&
     sm.includes("<lastmod>2025-07-20</lastmod>") &&
     sm.includes("<priority>0.8</priority>"));
}

// ---- seo: メタ / OGP / Twitter / JSON-LD / robots ----
section("seo: meta / open-graph / json-ld / robots");
{
  const fs9 = await import("node:fs/promises"); const st9 = smokeStamp();
  const metaSrc = (await fs9.readFile(new URL("../packages/seo/src/meta.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
  await fs9.writeFile(`${TMP}/seo-meta-${st9}.ts`, metaSrc);
  const ogSrc = (await fs9.readFile(new URL("../packages/seo/src/open-graph.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"').replace(/from "\.\/meta\.ts"/g, `from \"${toSpec(`${TMP}/seo-meta-${st9}.ts`)}\"`);
  await fs9.writeFile(`${TMP}/seo-og-${st9}.ts`, ogSrc);
  const M = await impFile(`${TMP}/seo-meta-${st9}.ts`);
  const O = await impFile(`${TMP}/seo-og-${st9}.ts`);
  ok("seo メタ(title適用/desc160/robots/escape/render)", M.buildTitle("記事", "%s | S") === "記事 | S" &&
     M.truncateDescription("あ".repeat(200)).length === 160 &&
     M.robotsContent({ index: false, follow: false }) === "noindex, nofollow" &&
     M.escapeAttr('a"<&') === "a&quot;&lt;&amp;" &&
     M.renderMeta(M.buildMeta({ title: "T", canonical: "https://ex.com/p" })).includes('rel="canonical"'));
  const og = O.buildOpenGraphTags({ title: "記事", type: "article", image: "https://ex.com/i.png", article: { publishedTime: "2025-07-25T00:00:00Z", tags: ["a", "b"] } });
  const tw = O.buildTwitterCardTags({ title: "記事", site: "@site" });
  ok("seo OGP(title/type/locale/article:tag×2) + Twitter(card/site)", og.some((t) => t.property === "og:title" && t.content === "記事") &&
     og.some((t) => t.property === "og:locale" && t.content === "ja_JP") &&
     og.filter((t) => t.property === "article:tag").length === 2 &&
     tw.some((t) => t.name === "twitter:card" && t.content === "summary_large_image") &&
     tw.some((t) => t.name === "twitter:site"));
  await fs9.rm(`${TMP}/seo-meta-${st9}.ts`); await fs9.rm(`${TMP}/seo-og-${st9}.ts`);

  const J = await impFile(new URL("../packages/seo/src/json-ld.ts", import.meta.url));
  const R = await impFile(new URL("../packages/seo/src/robots.ts", import.meta.url));
  const art = J.articleJsonLd({ headline: "記事", authorName: "著者", publisherName: "S", publisherLogo: "https://ex.com/l.png", url: "https://ex.com/a" });
  const bc = J.breadcrumbJsonLd([{ name: "H", url: "https://ex.com" }, { name: "記事", url: "https://ex.com/a" }]);
  const web = J.websiteJsonLd({ name: "S", url: "https://ex.com", searchUrl: "https://ex.com/s?q={search_term_string}" });
  const prod = J.productJsonLd({ name: "商品", price: 1980, availability: "InStock" });
  ok("seo JSON-LD(Article/Breadcrumb/WebSite SearchAction/Product/FAQ)", art["@type"] === "BlogPosting" &&
     art.author.name === "著者" &&
     bc.itemListElement[1].position === 2 &&
     web.potentialAction["@type"] === "SearchAction" &&
     prod.offers.availability === "https://schema.org/InStock" &&
     J.faqJsonLd([{ question: "Q", answer: "A" }]).mainEntity.length === 1);
  ok("seo renderJsonLd(script/</script>エスケープ) + robots.txt(UA/Disallow/Sitemap/allowAll)", J.renderJsonLd(art).startsWith('<script type="application/ld+json">') &&
     J.renderJsonLd({ x: "</script>" }).includes("\\u003c/script>") &&
     R.buildRobotsTxt({ rules: [{ userAgent: "*", disallow: ["/admin"] }], sitemaps: ["https://ex.com/sitemap.xml"] }).includes("Disallow: /admin") &&
     R.buildRobotsTxt({ rules: [{ userAgent: "*", disallow: ["/admin"] }], sitemaps: ["https://ex.com/sitemap.xml"] }).includes("Sitemap: https://ex.com/sitemap.xml") &&
     R.allowAllRobotsTxt("https://ex.com/sitemap.xml").includes("Allow: /"));
}

// ---- commerce拡張: バリエーション / レビュー / 注文ステータス / ポイント / 送料 ----
section("commerce+: variant / review / order-status / points / shipping");
{
  const V = await impFile(new URL("../packages/commerce/src/variant.ts", import.meta.url));
  const RV = await impFile(new URL("../packages/commerce/src/review.ts", import.meta.url));
  const OS = await impFile(new URL("../packages/commerce/src/order-status.ts", import.meta.url));
  const PT = await impFile(new URL("../packages/commerce/src/points.ts", import.meta.url));
  const SH = await impFile(new URL("../packages/commerce/src/shipping.ts", import.meta.url));
  const variants = [{ sku: "S-赤", options: { サイズ: "S", 色: "赤" }, price: 1000, stock: 5 }, { sku: "M-赤", options: { サイズ: "M", 色: "赤" }, price: 1000, stock: 0 }, { sku: "M-青", options: { サイズ: "M", 色: "青" }, price: 1200, stock: 3 }, { sku: "L-青", options: { サイズ: "L", 色: "青" }, price: 1200, stock: 2 }];
  ok("variant(選択特定/在庫別選択肢/価格帯)", V.findVariant(variants, { サイズ: "M", 色: "青" }).sku === "M-青" &&
     V.availableValues(variants, "サイズ", { 色: "青" }).sort().join(",") === "L,M" &&
     V.availableValues(variants, "サイズ", { 色: "赤" }).join(",") === "S" &&
     V.priceRange(variants).min === 1000 &&
     V.priceRange(variants).max === 1200);
  const s = RV.ratingSummary([5, 5, 5, 4, 4, 3, 1]);
  ok("review(平均3.9/分布/割合)", RV.averageRating([5, 5, 5, 4, 4, 3, 1]) === 3.9 && RV.ratingDistribution([5, 5, 5, 4, 4, 3, 1])[5] === 3 && s.count === 7 && Math.abs(s.percentages[5] - 42.9) < 0.1);
  ok("order-status(遷移可否/次状態/終端/キャンセル可否)", OS.canTransition("pending", "paid") === true &&
     OS.canTransition("pending", "shipped") === false &&
     OS.nextStatuses("paid").sort().join(",") === "cancelled,processing,refunded" &&
     OS.isFinalStatus("cancelled") === true &&
     OS.isCancellable("shipped") === false);
  const now = new Date("2025-07-25T00:00:00Z");
  const txns = [{ amount: 100, date: "2025-01-01T00:00:00Z", expiresAt: "2026-01-01T00:00:00Z" }, { amount: 50, date: "x", expiresAt: "2025-06-01T00:00:00Z" }, { amount: -30, date: "x" }];
  ok("points(付与1%/残高失効考慮/利用上限)", PT.earnPoints(1980) === 19 && PT.pointsBalance(txns, now) === 70 && PT.redeemPoints(500, 300, 200).used === 200 && PT.redeemPoints(0, 100).ok === false);
  const zones = [{ name: "本州", regions: ["東京都"], fee: 550, freeThreshold: 5000 }, { name: "北海道", regions: ["北海道"], fee: 1100, freeThreshold: 10000 }];
  ok("shipping(エリア別/無料閾値/重量段階)", SH.shippingFeeForRegion(zones, "東京都", 3000) === 550 &&
     SH.shippingFeeForRegion(zones, "東京都", 5000) === 0 &&
     SH.shippingFeeForRegion(zones, "北海道", 5000) === 1100 &&
     SH.weightBasedFee(700, [{ maxWeight: 500, fee: 400 }, { maxWeight: 1000, fee: 600 }]) === 600 &&
     SH.totalWeight([{ weight: 200, quantity: 2 }, { weight: 100, quantity: 3 }]) === 700);
}

// ---- blog拡張: コメント / 記事ナビゲーション ----
section("blog+: comment / navigation");
{
  const CM = await impFile(new URL("../packages/blog/src/comment.ts", import.meta.url));
  const comments = [{ id: "1", author: "A", body: "最初", createdAt: "2025-07-20T10:00:00Z", status: "approved" }, { id: "2", parentId: "1", author: "B", body: "返信", createdAt: "2025-07-20T11:00:00Z", status: "approved" }, { id: "3", author: "C", body: "別", createdAt: "2025-07-21T10:00:00Z", status: "pending" }, { id: "4", parentId: "1", author: "D", body: "返信2", createdAt: "2025-07-20T12:00:00Z", status: "approved" }];
  const tree = CM.buildCommentTree(comments);
  ok("comment(ツリー/返信/承認済み/並替/総数/承認待ち)", tree.length === 2 &&
     tree[0].replies.length === 2 &&
     CM.approvedComments(comments).length === 3 &&
     CM.sortComments(comments, "newest")[0].id === "3" &&
     CM.countComments(tree) === 4 &&
     CM.pendingCount(comments) === 1);
  const fs10 = await import("node:fs/promises"); const st10 = smokeStamp();
  const navSrc = (await fs10.readFile(new URL("../packages/blog/src/navigation.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"').replace(/from "\.\/post\.ts"/g, `from \"${toSpec(`${TMP}/blognav-post-${st10}.ts`)}\"`);
  const postSrc = (await fs10.readFile(new URL("../packages/blog/src/post.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
  await fs10.writeFile(`${TMP}/blognav-post-${st10}.ts`, postSrc); await fs10.writeFile(`${TMP}/blognav-nav-${st10}.ts`, navSrc);
  const N = await impFile(`${TMP}/blognav-nav-${st10}.ts`);
  const posts = [{ id: "1", slug: "a", title: "A", status: "published", publishedAt: "2025-07-20T00:00:00Z", series: "入門", seriesOrder: 1 }, { id: "2", slug: "b", title: "B", status: "published", publishedAt: "2025-07-22T00:00:00Z", series: "入門", seriesOrder: 2 }, { id: "3", slug: "c", title: "C", status: "published", publishedAt: "2025-07-24T00:00:00Z", series: "入門", seriesOrder: 3 }];
  const adj = N.adjacentPosts(posts, "2"); const sn = N.seriesNavigation(posts, "2");
  ok("navigation(前後記事/連載順/連載内前後+位置)", adj.newer.id === "3" &&
     adj.older.id === "1" &&
     N.seriesPosts(posts, "入門").map((p) => p.id).join(",") === "1,2,3" &&
     sn.prev.id === "1" &&
     sn.next.id === "3" &&
     sn.total === 3);
  await fs10.rm(`${TMP}/blognav-post-${st10}.ts`); await fs10.rm(`${TMP}/blognav-nav-${st10}.ts`);
}

// ---- site: ページ構成 / ナビ / リダイレクト / お知らせ(公式サイト・LP) ----
section("site: blocks / navigation / redirects / announcement");
{
  const B = await impFile(new URL("../packages/site/src/blocks.ts", import.meta.url));
  const N = await impFile(new URL("../packages/site/src/navigation.ts", import.meta.url));
  const RD = await impFile(new URL("../packages/site/src/redirects.ts", import.meta.url));
  const AN = await impFile(new URL("../packages/site/src/announcement.ts", import.meta.url));
  const now = new Date("2025-07-25T12:00:00Z");
  const page = { slug: "home", title: "T", blocks: [{ id: "h", type: "hero", data: {} }, { id: "f", type: "features", data: {}, visible: false }, { id: "c", type: "cta", data: {}, visibleFrom: "2025-08-01T00:00:00Z" }, { id: "faq", type: "faq", data: {} }, { id: "s", type: "stats", data: {} }] };
  ok("site ブロック(公開中のみ/タイプ別/並べ替え/上下移動)", B.visibleBlocks(page, now).map((b) => b.id).join(",") === "h,faq,s" &&
     B.blocksByType(page, "hero").length === 1 &&
     B.reorderBlocks(page.blocks, 0, 2).map((b) => b.id).join(",") === "f,c,h,faq,s" &&
     B.moveBlockUp(page.blocks, "f").map((b) => b.id).join(",") === "f,h,c,faq,s");
  const menu = [{ label: "ホーム", href: "/" }, { label: "製品", href: "/products", children: [{ label: "製品A", href: "/products/a" }, { label: "製品B", href: "/products/b" }] }, { label: "会社概要", href: "/about" }];
  ok("site ナビ(アクティブ/exact/経路/パンくず/平坦化)", N.isActive(menu[1], "/products/a") === true &&
     N.isActive(menu[1], "/products", { exact: true }) === true &&
     N.activeTrail(menu, "/products/a").map((i) => i.label).join(">") === "製品>製品A" &&
     N.breadcrumbFromMenu(menu, "/products/b").length === 2 &&
     N.flattenMenu(menu).length === 5);
  const rules = [{ from: "/old-page", to: "/new-page" }, { from: "/blog/*", to: "/articles/:splat", status: 301 }, { from: "/campaign", to: "/sale", status: 302 }];
  ok("site リダイレクト(完全一致/ワイルドカード/クエリ無視/302/連鎖/該当なし)", RD.resolveRedirect(rules, "/old-page").to === "/new-page" &&
     RD.resolveRedirect(rules, "/blog/2025/hello").to === "/articles/2025/hello" &&
     RD.resolveRedirect(rules, "/old-page/?utm=x").to === "/new-page" &&
     RD.resolveRedirect(rules, "/campaign").status === 302 &&
     RD.resolveRedirectChain([{ from: "/a", to: "/b" }, { from: "/b", to: "/c" }], "/a").to === "/c" &&
     RD.resolveRedirect(rules, "/other") === null);
  const anns = [{ id: "1", message: "通常", level: "info" }, { id: "2", message: "期間外", startAt: "2025-08-01T00:00:00Z" }, { id: "3", message: "セール", endAt: "2025-12-31T00:00:00Z", level: "sale" }, { id: "4", message: "商品のみ", paths: ["/products"], level: "warning" }];
  ok("site お知らせ(期間/パス限定/閉じた除外/最優先sale)", AN.isAnnouncementActive(anns[0], "/", now) === true &&
     AN.isAnnouncementActive(anns[1], "/", now) === false &&
     AN.isAnnouncementActive(anns[3], "/products/a", now) === true &&
     AN.activeAnnouncements(anns, "/", { now }).map((a) => a.id).join(",") === "1,3" &&
     AN.activeAnnouncements(anns, "/", { now, dismissedIds: ["1"] }).map((a) => a.id).join(",") === "3" &&
     AN.topAnnouncement(anns, "/products", { now }).id === "3");
}

// ---- seo可視性: 社内noindex / 公開index(検索避けポリシー) ----
section("seo: visibility (internal noindex / public index)");
{
  const fs11 = await import("node:fs/promises"); const st11 = smokeStamp();
  const files = {};
  for (const f of ["meta", "robots", "indexing"]) {
    const src = (await fs11.readFile(new URL(`../packages/seo/src/${f}.ts`, import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"').replace(/from "\.\/(meta|robots)\.ts"/g, (m, n) => `from \"${toSpec(`${TMP}/seovis-${n}-${st11}.ts`)}\"`);
    files[f] = `${TMP}/seovis-${f}-${st11}.ts`;
    await fs11.writeFile(files[f], src);
  }
  const I = await impFile(files.indexing);
  const M = await impFile(files.meta);
  ok("可視性 internal→noindex / public→index / xRobotsTag", M.robotsContent(I.robotsForVisibility("internal")) === "noindex, nofollow, noarchive" &&
     M.robotsContent(I.robotsForVisibility("public")) === "index, follow" &&
     I.noindexRobots() === "noindex, nofollow, noarchive" &&
     I.xRobotsTag("internal") === "noindex, nofollow, noarchive" &&
     I.xRobotsTag("public") === "index, follow");
  ok("robots.txt 社内全拒否 / 公開許可+sitemap", I.internalRobotsTxt().includes("Disallow: /") &&
     !I.internalRobotsTxt().includes("Allow") &&
     I.publicRobotsTxt("https://ex.com/sitemap.xml").includes("Allow: /") &&
     I.publicRobotsTxt("https://ex.com/sitemap.xml").includes("Sitemap:"));
  ok("buildMeta visibility統合(internal noindex/public index/robots明示優先/無指定は無)", M.buildMeta({ title: "社内", visibility: "internal" }).tags.find((t) => t.name === "robots").content === "noindex, nofollow, noarchive" &&
     M.buildMeta({ title: "公開", visibility: "public" }).tags.find((t) => t.name === "robots").content === "index, follow" &&
     M.buildMeta({ title: "x", visibility: "public", robots: { index: false } }).tags.find((t) => t.name === "robots").content.includes("noindex") &&
     !M.buildMeta({ title: "x" }).tags.some((t) => t.name === "robots"));
  for (const f of Object.values(files)) await fs11.rm(f);
}

// ---- blog パーマリンク: URL構造の生成・逆引き ----
section("blog: permalink (URL structure)");
{
  const fs12 = await import("node:fs/promises"); const st12 = smokeStamp();
  const plSrc = (await fs12.readFile(new URL("../packages/blog/src/permalink.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"')// **URL を組み立ててから toSpec に渡す。** `toSpec(TMP)` の後ろに文字列を足すと
    // `file:///tmp` + `/x.ts` のように URL の途中へ連結することになる。
    // **`.pathname` は使わない**(Windows では `/C:/...` になり、パスとして解決すると `C:\C:\...` になる)
    .replace(/from "\.\/slug\.ts"/g, `from \"${toSpec(`${TMP}/pl-slug-${st12}.ts`)}\"`)
    .replace(/from "@platform\/url"/g, `from "${new URL("../packages/url/src/join.ts", import.meta.url).href}"`);
  const slugSrc = (await fs12.readFile(new URL("../packages/blog/src/slug.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
  await fs12.writeFile(`${TMP}/pl-slug-${st12}.ts`, slugSrc); await fs12.writeFile(`${TMP}/pl-perma-${st12}.ts`, plSrc);
  const P = await impFile(`${TMP}/pl-perma-${st12}.ts`);
  const post = { slug: "hello-world", id: "123", category: "技術ブログ", publishedAt: "2025-07-25T10:00:00Z" };
  const late = { slug: "night", publishedAt: "2025-07-25T23:00:00Z" };
  ok("permalink 生成(slug/日付/ID/カテゴリunicode/TZ)", P.buildPermalink("/blog/:slug", post) === "/blog/hello-world" &&
     P.buildPermalink("/:year/:month/:day/:slug", post) === "/2025/07/25/hello-world" &&
     P.buildPermalink("/archives/:id", post) === "/archives/123" &&
     P.buildPermalink("/:category/:slug", post, { allowUnicode: true }) === "/技術ブログ/hello-world" &&
     P.buildPermalink("/:year/:month/:day/:slug", late, { utcOffsetMinutes: 540 }) === "/2025/07/26/night");
  ok("permalink joinUrl/postUrl絶対/matchPermalink逆引き", P.joinUrl("https://ex.com/", "/blog/a") === "https://ex.com/blog/a" &&
     P.postUrl(post, { baseUrl: "https://ex.com", pattern: "/blog/:year/:slug" }) === "https://ex.com/blog/2025/hello-world" &&
     JSON.stringify(P.matchPermalink("/blog/:year/:month/:slug", "/blog/2025/07/hello")) === JSON.stringify({ year: "2025", month: "07", slug: "hello" }) &&
     P.matchPermalink("/blog/:slug", "/blog/2025/hello") === null);
  await fs12.rm(`${TMP}/pl-slug-${st12}.ts`); await fs12.rm(`${TMP}/pl-perma-${st12}.ts`);
}

// ---- url: 解析 / ドメイン / クエリ / 正規化 / 検証(URL・ドメイン処理) ----
section("url: parse / domain / query / normalize / validate");
{
  const P = await impFile(new URL("../packages/url/src/parse.ts", import.meta.url));
  const D = await impFile(new URL("../packages/url/src/domain.ts", import.meta.url));
  const Q = await impFile(new URL("../packages/url/src/query.ts", import.meta.url));
  const NM = await impFile(new URL("../packages/url/src/normalize.ts", import.meta.url));
  const VL = await impFile(new URL("../packages/url/src/validate.ts", import.meta.url));
  const pp = P.parseUrl("https://www.ex.com:8080/blog/a?x=1&y=2#top");
  ok("url 解析(分解/相対base/buildUrl/isAbsolute)", pp.hostname === "www.ex.com" &&
     pp.port === "8080" &&
     pp.pathname === "/blog/a" &&
     pp.search === "x=1&y=2" &&
     pp.hash === "top" &&
     P.parseUrl("/foo", "https://ex.com").hostname === "ex.com" &&
     P.buildUrl({ protocol: "https", hostname: "ex.com", pathname: "/a", search: "x=1" }) === "https://ex.com/a?x=1" &&
     P.isAbsoluteUrl("/p") === false);
  ok("url ドメイン(eTLD+1/co.jp/subdomain/tld/同一判定)", D.getRegistrableDomain("www.example.com") === "example.com" &&
     D.getRegistrableDomain("www.example.co.jp") === "example.co.jp" &&
     D.getRegistrableDomain("blog.mysite.ne.jp") === "mysite.ne.jp" &&
     D.getSubdomain("a.b.example.co.jp") === "a.b" &&
     D.getTld("example.co.jp") === "co.jp" &&
     D.isSameDomain("www.example.com", "api.example.com") === true &&
     D.isSameDomain("example.com", "other.com") === false);
  ok("url クエリ(解析/set/setParams削除/append/keep/相対)", JSON.stringify(Q.parseQuery("?a=1&b=2&a=3")) === JSON.stringify({ a: ["1", "3"], b: "2" }) &&
     Q.setParam("https://ex.com/a?x=1#top", "x", 9) === "https://ex.com/a?x=9#top" &&
     Q.setParams("https://ex.com/a?x=1&y=2", { x: 9, y: null, z: 3 }) === "https://ex.com/a?x=9&z=3" &&
     Q.appendParam("https://ex.com/a?tag=1", "tag", 2) === "https://ex.com/a?tag=1&tag=2" &&
     Q.keepParams("https://ex.com/a?x=1&y=2&z=3", ["x", "z"]) === "https://ex.com/a?x=1&z=3" &&
     Q.setParam("/search?q=old", "q", "new") === "/search?q=new");
  ok("url 正規化(host小文字/トラッキング除去/ソート/末尾スラッシュ/urlsEqual)", NM.normalizeUrl("https://EXAMPLE.com/Path") === "https://example.com/Path" &&
     NM.normalizeUrl("https://ex.com/a?id=1&utm_source=x&fbclid=y") === "https://ex.com/a?id=1" &&
     NM.normalizeUrl("https://ex.com/a?c=3&a=1&b=2") === "https://ex.com/a?a=1&b=2&c=3" &&
     NM.normalizeUrl("https://ex.com/blog/") === "https://ex.com/blog" &&
     NM.normalizeUrl("https://ex.com/") === "https://ex.com/" &&
     NM.urlsEqual("https://EX.com/a/?utm_source=x", "https://ex.com/a") === true);
  ok("url 検証(valid/http限定/safe危険排除/sameOrigin/external)", VL.isValidUrl("https://ex.com") === true &&
     VL.isValidUrl("not url") === false &&
     VL.isHttpUrl("ftp://ex.com") === false &&
     VL.isSafeUrl("javascript:alert(1)") === false &&
     VL.isSafeUrl("data:text/html,x") === false &&
     VL.isSafeUrl("/relative") === true &&
     VL.isSameOrigin("https://ex.com/a", "https://ex.com/b") === true &&
     VL.isExternalUrl("https://other.com/x", "example.com") === true &&
     VL.isExternalUrl("/internal", "example.com") === false);
}

// ---- social: X/TikTok/Instagram 連携(ハンドル/URL解析/oEmbed/アカウント) ----
section("social: handle / parse / embed / accounts");
{
  const fs13 = await import("node:fs/promises"); const st13 = smokeStamp();
  const names = ["platforms", "handle", "parse", "embed", "accounts"];
  const paths = {};
  for (const n of names) paths[n] = `${TMP}/soc-${n}-${st13}.ts`;
  for (const n of names) {
    let src = (await fs13.readFile(new URL(`../packages/social/src/${n}.ts`, import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
    for (const dep of names) src = src.replace(new RegExp(`from "\\./${dep}\\.ts"`, "g"), `from "${toSpec(paths[dep])}"`);
    await fs13.writeFile(paths[n], src);
  }
  const H = await impFile(paths.handle);
  const PR = await impFile(paths.parse);
  const E = await impFile(paths.embed);
  const A = await impFile(paths.accounts);
  ok("social ハンドル(normalize/valid X15字/TikTok./profileUrl/display@)", H.normalizeHandle("@yamada") === "yamada" &&
     H.isValidHandle("x", "yamada_taro") === true &&
     H.isValidHandle("x", "toolong_handle_over15") === false &&
     H.isValidHandle("tiktok", "cast.01") === true &&
     H.buildProfileUrl("tiktok", "cast01") === "https://www.tiktok.com/@cast01" &&
     H.displayHandle("tiktok", "cast01") === "@cast01" &&
     H.buildProfileUrl("x", "bad handle!") === null);
  const xr = PR.parseSocialUrl("https://twitter.com/y/status/123");
  const tr = PR.parseSocialUrl("https://www.tiktok.com/@c/video/71");
  const ir = PR.parseSocialUrl("https://www.instagram.com/p/ABC/");
  ok("social URL解析(Xプロフ/Xツイート/TikTok動画/IG投稿/reel/予約語除外)", PR.parseSocialUrl("https://x.com/yamada").type === "profile" &&
     xr.type === "post" &&
     xr.postId === "123" &&
     xr.postKind === "tweet" &&
     tr.postKind === "video" &&
     ir.postKind === "post" &&
     PR.parseSocialUrl("https://www.instagram.com/reel/XYZ/").postKind === "reel" &&
     PR.parseSocialUrl("https://x.com/home") === null &&
     PR.parseSocialUrl("https://example.com/x") === null);
  ok("social oEmbed(X/TikTok/IGはnull要トークン/supports)", E.oembedEndpoint("x", "https://x.com/y/status/123") === "https://publish.twitter.com/oembed?url=https%3A%2F%2Fx.com%2Fy%2Fstatus%2F123" &&
     E.oembedEndpoint("x", "https://x.com/y/status/123", { theme: "dark", omitScript: true }).includes("theme=dark") &&
     E.oembedEndpoint("tiktok", "https://www.tiktok.com/@c/video/71").startsWith("https://www.tiktok.com/oembed?url=") &&
     E.oembedEndpoint("instagram", "https://www.instagram.com/p/ABC/") === null &&
     E.supportsOEmbed("x") === true &&
     E.supportsOEmbed("instagram") === false);
  const accounts = A.accountsFromUrls(["https://x.com/yamada_taro", "https://twitter.com/yamada_taro", "https://www.tiktok.com/@yamada.dance", "https://www.instagram.com/yamada_ig/", "https://example.com/x", "@bad handle"]);
  const links = A.accountLinks(accounts);
  ok("social アカウント(複数URL→妥当のみ+重複排除/リンク順/プラットフォーム別)", accounts.length === 3 &&
     accounts.filter((a) => a.platform === "x").length === 1 &&
     links.map((l) => l.platform).join(",") === "x,tiktok,instagram" &&
     links[1].label === "@yamada.dance" &&
     A.accountsByPlatform(accounts).instagram.handle === "yamada_ig" &&
     A.dedupeAccounts([{ platform: "x", handle: "a", url: "u" }, { platform: "x", handle: "A", url: "u" }]).length === 1);
  for (const n of names) await fs13.rm(paths[n]);
}

// ---- booking: 営業時間 / スロット / 空き枠 / ルール / ステータス(予約サイト) ----
section("booking: hours / slots / availability / rules / status");
{
  const fs14 = await import("node:fs/promises"); const st14 = smokeStamp();
  const names = ["hours", "slots", "availability", "rules", "status"];
  const paths = {};
  for (const n of names) paths[n] = `${TMP}/bk-${n}-${st14}.ts`;
  for (const n of names) {
    let src = (await fs14.readFile(new URL(`../packages/booking/src/${n}.ts`, import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
    for (const dep of names) src = src.replace(new RegExp(`from "\\./${dep}\\.ts"`, "g"), `from "${toSpec(paths[dep])}"`);
    await fs14.writeFile(paths[n], src);
  }
  const H = await impFile(paths.hours);
  const S = await impFile(paths.slots);
  const A = await impFile(paths.availability);
  const R = await impFile(paths.rules);
  const ST = await impFile(paths.status);
  const weekly = { 1: [{ open: "09:00", close: "12:00" }, { open: "13:00", close: "18:00" }], 0: [] };
  // **不正な時刻で例外を投げる。** 2026-08 まで `NaN` や `0` を返しており、
  // **二重予約が通る**状態だった——`intervalsOverlap` は `NaN` との比較が
  // すべて false になるので「重なっていない」と判定される。
  // 空文字は 0(= 00:00)扱いで、**深夜の予約が取れて**しまう
  {
    const bad = ["", "abc", "09:70", "09:30:45"];
    ok("booking 時刻: 不正な形式は例外", bad.every((t) => {
      try { H.timeToMinutes(t); return false; } catch { return true; }
    }));
    // **24 時超えは通す**(深夜営業。`26:00` = 翌 2:00)
    ok("booking 時刻: 24 時超えは通す", H.timeToMinutes("26:00") === 1560);
  }
  ok("booking 営業時間(分変換/曜日/臨時休/特別営業/昼休み判定)", H.timeToMinutes("09:30") === 570 &&
     H.weekdayOf("2025-07-28") === 1 &&
     H.resolveDayHours("2025-07-28", weekly).length === 2 &&
     H.resolveDayHours("2025-07-28", weekly, { closedDates: ["2025-07-28"] }).length === 0 &&
     H.resolveDayHours("2025-07-28", weekly, { specialDates: { "2025-07-28": [{ open: "10:00", close: "15:00" }] } })[0].open === "10:00" &&
     H.isOpenAt("2025-07-28", "12:30", weekly) === false &&
     H.isBusinessDay("2025-07-27", weekly) === false);
  ok("booking スロット(30分×4/刻み幅/昼休み8枠/所要)", S.generateSlots([{ open: "09:00", close: "11:00" }], { slotMinutes: 30 }).length === 4 &&
     S.generateSlots([{ open: "09:00", close: "10:00" }], { slotMinutes: 30, stepMinutes: 15 }).map((x) => x.start).join(",") === "09:00,09:15,09:30" &&
     S.generateSlots(weekly[1], { slotMinutes: 60 }).length === 8 &&
     S.slotDuration({ start: "09:00", end: "10:30" }) === 90);
  const daySlots = S.generateSlots([{ open: "09:00", close: "12:00" }], { slotMinutes: 60 });
  const bookings = [{ start: "09:00", end: "10:00" }, { start: "10:30", end: "11:30" }];
  ok("booking 空き枠(重なり/capacity1埋まる/capacity2空く/残数/衝突)", A.intervalsOverlap("09:00", "10:00", "09:30", "10:30") === true &&
     A.intervalsOverlap("09:00", "10:00", "10:00", "11:00") === false &&
     A.availableSlots(daySlots, bookings, 1).length === 0 &&
     A.availableSlots(daySlots, bookings, 2).length === 3 &&
     A.remainingCapacity(daySlots, bookings, 2)[0].remaining === 1 &&
     A.hasConflict({ start: "09:00", end: "10:00" }, bookings, 1) === true &&
     A.hasConflict({ start: "09:00", end: "10:00" }, bookings, 2) === false);
  const now = new Date("2025-07-25T12:00:00Z");
  ok("booking ルール(適正/過去/直前/先すぎ/キャンセル期限/人数)", R.isWithinBookingWindow("2025-07-26T12:00:00Z", { minLeadMinutes: 60, maxAdvanceDays: 30 }, now).ok === true &&
     R.isWithinBookingWindow("2025-07-24T12:00:00Z", {}, now).reason === "past" &&
     R.isWithinBookingWindow("2025-07-25T12:30:00Z", { minLeadMinutes: 60 }, now).reason === "too_soon" &&
     R.isWithinBookingWindow("2025-09-25T12:00:00Z", { maxAdvanceDays: 30 }, now).reason === "too_far" &&
     R.canCancel("2025-07-26T12:00:00Z", 1440, now) === true &&
     R.canCancel("2025-07-25T18:00:00Z", 1440, now) === false &&
     R.validatePartySize(5, { max: 4 }).reason === "too_many");
  ok("booking ステータス(遷移/次状態/終端/枠占有/ラベル)", ST.canTransition("requested", "confirmed") === true &&
     ST.canTransition("requested", "completed") === false &&
     ST.nextStatuses("confirmed").sort().join(",") === "cancelled,completed,no_show" &&
     ST.isFinalStatus("completed") === true &&
     ST.isActiveBooking("confirmed") === true &&
     ST.isActiveBooking("cancelled") === false &&
     ST.BOOKING_STATUS_LABELS.no_show === "無断キャンセル");
  for (const n of names) await fs14.rm(paths[n]);
}

// ---- booking リマインダー / social 統合フィード / cast プロフィール ----
section("booking-reminders / social-feed / cast");
{
  const fs15 = await import("node:fs/promises"); const st15 = smokeStamp();
  // booking reminders(依存なし)
  const R = await impFile(new URL("../packages/booking/src/reminders.ts", import.meta.url));
  const bookingAt = "2025-07-26T18:00:00Z";
  const sched = R.reminderSchedule(bookingAt, [{ beforeMinutes: 1440, channel: "email" }, { beforeMinutes: 60, channel: "sms" }]);
  ok("reminders(発火時刻/due/送信済除外/grace/timing/本文)", sched[0].fireAt === "2025-07-25T18:00:00.000Z" &&
     sched[1].fireAt === "2025-07-26T17:00:00.000Z" &&
     R.dueReminders("bk1", sched, new Date("2025-07-25T18:30:00Z")).length === 1 &&
     R.dueReminders("bk1", sched, new Date("2025-07-25T18:30:00Z"), { sentKeys: ["bk1:email:1440"] }).length === 0 &&
     R.dueReminders("bk1", sched, new Date("2025-07-26T17:30:00Z"), { graceMinutes: 60 }).length === 1 &&
     R.reminderTiming(1440) === "day_before" &&
     R.reminderMessage({ customerName: "山田", bookingAt, beforeMinutes: 1440 }).includes("明日"));
  // social feed(platforms 依存 → shim)
  const feedSrc = (await fs15.readFile(new URL("../packages/social/src/feed.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"').replace(/from "\.\/platforms\.ts"/g, `from \"${toSpec(`${TMP}/sf-plat-${st15}.ts`)}\"`);
  const platSrc = (await fs15.readFile(new URL("../packages/social/src/platforms.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
  await fs15.writeFile(`${TMP}/sf-plat-${st15}.ts`, platSrc); await fs15.writeFile(`${TMP}/sf-feed-${st15}.ts`, feedSrc);
  const F = await impFile(`${TMP}/sf-feed-${st15}.ts`);
  const posts = [{ platform: "x", id: "1", url: "u1", createdAt: "2025-07-20T10:00:00Z" }, { platform: "tiktok", id: "10", url: "u10", createdAt: "2025-07-25T10:00:00Z" }, { platform: "x", id: "2", url: "u2", createdAt: "2025-07-24T10:00:00Z" }, { platform: "x", id: "1", url: "dup", createdAt: "2025-07-20T10:00:00Z" }, { platform: "instagram", id: "100", url: "u100", createdAt: "2025-07-22T10:00:00Z" }];
  ok("social-feed(重複排除+新しい順/最新1件/新着/直近N)", F.mergeSocialFeed(posts).length === 4 &&
     F.mergeSocialFeed(posts)[0].id === "10" &&
     F.latestPerPlatform(posts).length === 3 &&
     F.newPosts(posts, ["x:1", "x:2"]).some((p) => p.id === "1") === false &&
     F.recentPosts(posts, 2).map((p) => p.id).join(",") === "10,2");
  await fs15.rm(`${TMP}/sf-plat-${st15}.ts`); await fs15.rm(`${TMP}/sf-feed-${st15}.ts`);
  // cast(profile が cast 依存 → shim)
  const castSrc = (await fs15.readFile(new URL("../packages/cast/src/cast.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
  const profSrc = (await fs15.readFile(new URL("../packages/cast/src/profile.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"').replace(/from "\.\/cast\.ts"/g, `from \"${toSpec(`${TMP}/cast-c-${st15}.ts`)}\"`);
  await fs15.writeFile(`${TMP}/cast-c-${st15}.ts`, castSrc); await fs15.writeFile(`${TMP}/cast-p-${st15}.ts`, profSrc);
  const C = await impFile(`${TMP}/cast-c-${st15}.ts`);
  const P = await impFile(`${TMP}/cast-p-${st15}.ts`);
  const now = new Date("2025-07-25T00:00:00Z");
  const casts = [{ id: "1", name: "あおい", status: "active", tags: ["ダンス", "歌"], featured: true, rating: 4.8, joinedAt: "2025-01-01" }, { id: "2", name: "かえで", status: "active", tags: ["トーク"], rating: 4.2, joinedAt: "2025-07-10" }, { id: "3", name: "さくら", status: "hidden", tags: ["ダンス"], rating: 5.0 }, { id: "4", name: "みなと", status: "active", tags: ["ダンス", "トーク"], rating: 4.5, joinedAt: "2024-06-01" }];
  ok("cast(在籍/タグ/全タグ/集計/新人/並替featured/注目)", C.activeCasts(casts).length === 3 &&
     C.castsByTag(casts, "ダンス").map((c) => c.id).sort().join(",") === "1,3,4" &&
     C.castsByAllTags(casts, ["ダンス", "トーク"]).map((c) => c.id).join(",") === "4" &&
     C.tagCounts(casts)[0].count === 3 &&
     C.newcomers(casts, 30, now).map((c) => c.id).join(",") === "2" &&
     C.sortCasts(casts, "featured", now).map((c) => c.id).join(",") === "1,4,2" &&
     C.featuredCasts(casts).map((c) => c.id).join(",") === "1");
  const fields = [{ key: "name", label: "名前" }, { key: "tags", label: "得意" }, { key: "height", label: "身長" }, { key: "message", label: "ひとこと" }];
  const one = { id: "x", name: "あおい", status: "active", tags: ["ダンス"], height: "160cm" };
  ok("cast-profile(項目値ありのみ/充実度0.75/必須判定)", P.profileItems(one, fields).length === 3 &&
     P.profileItems(one, fields).find((i) => i.label === "得意").value === "ダンス" &&
     P.profileCompleteness(one, fields) === 0.75 &&
     P.hasRequiredProfile(one, ["name", "tags"]) === true &&
     P.hasRequiredProfile(one, ["name", "message"]) === false);
  await fs15.rm(`${TMP}/cast-c-${st15}.ts`); await fs15.rm(`${TMP}/cast-p-${st15}.ts`);
}

// ---- booking シフト / cast 口コミランキング ----
section("booking-shift / cast-ranking");
{
  const fs16 = await import("node:fs/promises"); const st16 = smokeStamp();
  // booking shift(slots/hours/availability 依存 → shim)
  const bn = ["shift", "slots", "hours", "availability"];
  const bp = {};
  for (const n of bn) bp[n] = `${TMP}/bks-${n}-${st16}.ts`;
  for (const n of bn) {
    let src = (await fs16.readFile(new URL(`../packages/booking/src/${n}.ts`, import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
    for (const dep of bn) src = src.replace(new RegExp(`from "\\./${dep}\\.ts"`, "g"), `from "${toSpec(bp[dep])}"`);
    await fs16.writeFile(bp[n], src);
  }
  const SH = await impFile(bp.shift);
  const S = await impFile(bp.slots);
  const slots = S.generateSlots([{ open: "09:00", close: "18:00" }], { slotMinutes: 60 });
  const staffShifts = { aoi: [{ start: "10:00", end: "14:00" }], kaede: [{ start: "12:00", end: "18:00" }], minato: [{ start: "09:00", end: "12:00" }] };
  const staffing = SH.slotStaffing(slots, staffShifts);
  const avail = SH.availableWithStaffing(slots, staffShifts, [{ start: "12:00", end: "13:00" }, { start: "12:00", end: "13:00" }]);
  ok("booking-shift(シフト内枠/指名空き/勤務人数/配置空き)", SH.staffSlots(slots, [{ start: "10:00", end: "14:00" }]).map((x) => x.start).join(",") === "10:00,11:00,12:00,13:00" &&
     SH.staffAvailableSlots(slots, [{ start: "10:00", end: "14:00" }], [{ start: "11:00", end: "12:00" }]).map((x) => x.start).join(",") === "10:00,12:00,13:00" &&
     staffing.find((x) => x.slot.start === "12:00").staffCount === 2 &&
     staffing.find((x) => x.slot.start === "09:00").staffCount === 1 &&
     avail.some((x) => x.slot.start === "12:00") === false &&
     avail.find((x) => x.slot.start === "13:00").remaining === 2);
  for (const n of bn) await fs16.rm(bp[n]);
  // cast ranking(cast 依存 → shim)
  const rankSrc = (await fs16.readFile(new URL("../packages/cast/src/ranking.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"').replace(/from "\.\/cast\.ts"/g, `from \"${toSpec(`${TMP}/rk-cast-${st16}.ts`)}\"`);
  const castSrc = (await fs16.readFile(new URL("../packages/cast/src/cast.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"');
  await fs16.writeFile(`${TMP}/rk-cast-${st16}.ts`, castSrc); await fs16.writeFile(`${TMP}/rk-rank-${st16}.ts`, rankSrc);
  const RK = await impFile(`${TMP}/rk-rank-${st16}.ts`);
  const casts = [{ id: "1", name: "あおい", status: "active", rating: 5.0, reviewCount: 2 }, { id: "2", name: "かえで", status: "active", rating: 4.7, reviewCount: 150 }, { id: "3", name: "みなと", status: "active", rating: 4.9, reviewCount: 80 }, { id: "4", name: "さくら", status: "hidden", rating: 5.0, reviewCount: 200 }];
  const ranking = RK.rankCasts(casts, { minCount: 10 });
  ok("cast-ranking(重み付き/少件数満点は独占せず/在籍のみ/単純平均別)", RK.weightedRating(5.0, 1, 10, 4.0) < RK.weightedRating(4.8, 100, 10, 4.0) &&
     RK.weightedRating(0, 0, 10, 4.0) === 4.0 &&
     ranking.length === 3 &&
     ranking[0].cast.id !== "1" &&
     ranking[0].rank === 1 &&
     RK.rankByRawRating(casts)[0].cast.id === "1");
  await fs16.rm(`${TMP}/rk-cast-${st16}.ts`); await fs16.rm(`${TMP}/rk-rank-${st16}.ts`);
}

