  await fsc.writeFile(crp, (await fsc.readFile(new URL("../packages/core/src/result.ts", import.meta.url), "utf8")).replace(/(from "\.{1,2}\/[^"]*)"/g, '$1.ts"').replace('from "./error.ts"', `from "${toSpec(cep)}"`));
